window.COURSE = {"version":1,"lessons":[{"lesson":{"slug":"writing-a-cv","titleAr":"كتابة سيرة ذاتية تُقرأ","titleEn":"Writing a CV that gets read","estMinutes":30,"bilingual":true,"levels":["L1","L2"],"objectives":["JOB-01"],"conceptsIntroduced":["cv_structure","relevant_result","action_verb","outcome_description","selection_by_advert","removal_of_irrelevant"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"JOB-01","payload":{"textAr":"ما الذي يجعل السيرة الذاتية تُقرأ؟","textEn":"What makes a CV get read?","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"JOB-01","payload":{"mdAr":"السيرة الذاتية ليست قائمة بكل ما فعلته، بل أداة لاختيار ما يهم صاحب العمل. القارئ يبحث عن إجابة واحدة: هل هذا الشخص قادر على أداء هذه الوظيفة المحددة؟ إذا لم يجد الإجابة بسرعة، ينتقل إلى السيرة التالية.\n\nالبداية الصحيحة هي الإعلان الوظيفي، وليس تاريخك. اقرأ الإعلان وحدد المهام والمهارات والأدوات المطلوبة، ثم اختر ما تضعه في السيرة وترتيبه بناءً على مدى ارتباطه بتلك النقاط.","mdEn":"A CV is not a list of everything you have done — it is a tool to select what matters to the employer. The reader is looking for one answer: can this person do this specific job? If they do not find it quickly, they move to the next CV.\n\nThe right starting point is the job advert, not your history. Read the advert, identify the tasks, skills and tools it asks for, then choose what to put in the CV and in what order, based on how directly it answers those lines."}},{"id":"b_l1_def_cv_structure","type":"definition_card","objectiveId":"JOB-01","payload":{"termAr":"بنية السيرة الذاتية","termEn":"CV structure","defAr":"الترتيب القياسي للأقسام في السيرة الذاتية: المعلومات الشخصية، الملخص، الخبرة، التعليم، المهارات.","defEn":"The standard order of sections in a CV: personal information, summary, experience, education, skills.","icon":"📄","exampleAr":"مثال تدريبي: سيرة ذاتية تبدأ بالاسم والبريد الإلكتروني، ثم سطرين عن الهدف المهني، ثم قائمة بالخبرات من الأحدث إلى الأقدم.","exampleEn":"Training example: a CV starting with name and email, then two lines about the career goal, then a list of experiences from newest to oldest."}},{"id":"b_l1_def_relevant_result","type":"definition_card","objectiveId":"JOB-01","payload":{"termAr":"النتيجة ذات الصلة","termEn":"Relevant result","defAr":"ما حققته في دور سابق يتطابق مع ما يطلبه الإعلان الوظيفي.","defEn":"What you achieved in a previous role that matches what the job advert asks for.","icon":"✔️"}},{"id":"b_l1_def_action_verb","type":"definition_card","objectiveId":"JOB-01","payload":{"termAr":"الفعل الإجرائي","termEn":"Action verb","defAr":"الفعل الذي يبدأ به وصف الإنجاز، مثل «أنشأت»، «حسّنت»، «قلّلت».","defEn":"The verb that starts a description of an achievement, such as 'created', 'improved', 'reduced'.","icon":"🔧"}},{"id":"b_l1_def_outcome_description","type":"definition_card","objectiveId":"JOB-01","payload":{"termAr":"وصف النتيجة","termEn":"Outcome description","defAr":"ما تغير بسبب العمل الذي قمت به، وليس مجرد وصف للمهمة.","defEn":"What changed as a result of the work you did, not just a description of the task.","icon":"📈"}},{"id":"b_l1_compare_entries","type":"compare_table","objectiveId":"JOB-01","payload":{"captionAr":"المهمة مقابل النتيجة","captionEn":"Task vs. result","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"مهمة فقط","labelEn":"Task only"},{"labelAr":"نتيجة ذات صلة","labelEn":"Relevant result"}],"rows":[[{"textAr":"ما يُقال","textEn":"What is said"},{"textAr":"«مسؤول عن مكالمات العملاء»","textEn":"'Responsible for customer calls'"},{"textAr":"«أجبت حوالي أربعين مكالمة يوميًا وحللت معظمها دون تحويلها»","textEn":"'Answered about forty customer calls a day and resolved most of them without passing them on'"}],[{"textAr":"ما يظهر","textEn":"What it shows"},{"textAr":"الدور الذي شغلته","textEn":"The role you held"},{"textAr":"ما فعلته ومدى فعاليتك","textEn":"What you did and how effective you were"}],[{"textAr":"ما يفتقده","textEn":"What it lacks"},{"textAr":"دليل على الأثر","textEn":"Evidence of impact"},{"textAr":"لا شيء — النتيجة واضحة","textEn":"Nothing — the result is clear"}]]}},{"id":"b_l1_flow_selection","type":"process_flow","objectiveId":"JOB-01","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"اقرأ الإعلان","labelEn":"Read the advert","detailAr":"حدد المهام والمهارات والأدوات المطلوبة.","detailEn":"Identify the tasks, skills and tools asked for."},{"id":"s2","labelAr":"راجع تاريخك","labelEn":"Review your history","detailAr":"ابحث عن أدوار أو مشاريع تتطابق مع الإعلان.","detailEn":"Look for roles or projects that match the advert."},{"id":"s3","labelAr":"اكتب النتيجة","labelEn":"Write the result","detailAr":"استخدم فعلًا إجرائيًا، وصفًا للعمل، وتأثيرًا.","detailEn":"Use an action verb, a description of the work, and the impact."},{"id":"s4","labelAr":"رتب الأقسام","labelEn":"Order the sections","detailAr":"ضع الأقسام الأكثر صلة بالأعلى.","detailEn":"Put the most relevant sections first."},{"id":"s5","labelAr":"احذف ما لا صلة له","labelEn":"Remove what is not relevant","detailAr":"احذف التفاصيل الشخصية غير المطلوبة والمهارات غير المدعومة.","detailEn":"Remove personal details not asked for and skills not supported."}]}},{"id":"b_l1_tip_advert","type":"job_tip","objectiveId":"JOB-01","payload":{"mdAr":"إذا طلب الإعلان مهارة معينة، ضعها في قسم المهارات فقط إذا كان لديك مثال على استخدامها. وإلا، احذفها — قائمة بالمهارات دون دليل لا تضيف شيئًا.","mdEn":"If the advert asks for a specific skill, put it in the skills section only if you have an example of using it. Otherwise, remove it — a list of skills with no evidence adds nothing."}},{"id":"b_l1_tip_numbers","type":"job_tip","objectiveId":"JOB-01","payload":{"mdAr":"إذا لم تعرف الرقم الدقيق، لا تخترعه. قل «حسّنت وقت الاستجابة بشكل ملحوظ» بدلًا من «حسّنت وقت الاستجابة بنسبة 30%» إذا لم تكن متأكدًا من النسبة.","mdEn":"If you do not know the exact number, do not invent it. Say 'improved response time noticeably' instead of 'improved response time by 30%' if you are not sure of the percentage."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"JOB-01","payload":{"itemsAr":["السيرة الذاتية أداة اختيار، تبدأ بالإعلان الوظيفي وليس بتاريخك.","كل إدخال يوضح نتيجة ذات صلة: فعل إجرائي، ما فعلته، وما تغير.","رتب الأقسام واحذف ما لا صلة له بناءً على الإعلان."],"itemsEn":["A CV is a selection tool, starting from the job advert, not your history.","Each entry shows a relevant result: an action verb, what you did, and what changed.","Order the sections and remove what is not relevant, based on the advert."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"JOB-01","payload":{"textAr":"طبّق ما تعلمته","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_example","type":"worked_example","objectiveId":"JOB-01","payload":{"promptAr":"الإعلان الوظيفي يطلب: «إدارة حسابات العملاء، حل الشكاوى بسرعة، استخدام نظام CRM». لديك في مسودتك: «مسؤول عن حسابات العملاء». أعد كتابته.","promptEn":"The job advert asks for: 'manage client accounts, resolve complaints quickly, use a CRM system'. Your draft says: 'Responsible for client accounts'. Rewrite it.","steps":[{"showAr":"حدد الفعل الإجرائي: «مسؤول عن» ليست كافية.","showEn":"Identify the action verb: 'responsible for' is not enough.","whyAr":"«مسؤول عن» يصف الدور فقط، بينما الفعل الإجرائي يوضح ما فعلته بالضبط. الإعلان يطلب إدارة وحل، لذا يجب أن يظهر الفعلان.","whyEn":"The verb 'responsible for' only describes the role, not what you actually did. The advert asks for managing and resolving, so both actions must appear."},{"showAr":"أضف ما فعلته: «أدرتُ حسابات العملاء، وحللت الشكاوى باستخدام نظام CRM».","showEn":"Add what you did: 'managed client accounts, resolved complaints using the CRM system'.","whyAr":"هذا يربط الإعلان بما فعلته بالفعل، ويظهر استخدام الأداة المحددة.","whyEn":"This connects the advert to what you actually did, and shows using the specific tool."},{"showAr":"أضف النتيجة: «قللت وقت الاستجابة من يومين إلى أربع ساعات».","showEn":"Add the result: 'reduced response time from two days to four hours'.","whyAr":"النتيجة تظهر الأثر، وهو ما يبحث عنه القارئ. بدونها، يبقى الإدخال وصفًا للمهمة فقط.","whyEn":"The result shows the impact, which is what the reader is looking for. Without it, the entry remains only a description of the task."}],"answerAr":"«أدرتُ حسابات العملاء، وحللت الشكاوى باستخدام نظام CRM، وقللت وقت الاستجابة من يومين إلى أربع ساعات».","answerEn":"'Managed client accounts, resolved complaints using the CRM system, and reduced response time from two days to four hours.'"}},{"id":"b_l2_scenario_irrelevant","type":"scenario","objectiveId":"JOB-01","payload":{"situationAr":"الإعلان الوظيفي يطلب خبرة في إدارة المشاريع باستخدام أداة محددة. لديك في مسودتك: «خبرة في مايكروسوفت أوفيس»، و«متطوع في تنظيم فعالية مدرسية». الموعد النهائي لإرسال السيرة اليوم. بالإضافة إلى ذلك، الإدخال التطوعي هو أول تجربة تنظيمية لك، وقد استغرقت وقتًا طويلًا في كتابته.","situationEn":"The job advert asks for experience in project management using a specific tool. Your draft includes: 'experience with Microsoft Office', and 'volunteered to organise a school event'. The deadline to send the CV is today. Also, the volunteering entry is your first experience of organising anything, and you spent a long time writing it up.","decisions":[{"id":"d1","optionAr":"أبقي كلا الإدخالين لأنهما يظهران مهارات متنوعة.","optionEn":"Keep both entries because they show a range of skills.","consequenceAr":"القارئ يبحث عن الخبرة ذات الصلة، وليس التنوع. كلا الإدخالين لا يجيبان على ما يطلبه الإعلان، وقد يُنظر إليهما كملء مساحة دون قيمة.","consequenceEn":"The reader is looking for relevant experience, not variety. Neither entry answers what the advert asks for, and may be seen as filler with no value.","isBest":false},{"id":"d2","optionAr":"أبقي إدخال التطوع وأحذف مايكروسوفت أوفيس.","optionEn":"Keep the volunteering entry and remove Microsoft Office.","consequenceAr":"إدخال التطوع يمكن إعادة كتابته ليوضح مهارات تنظيمية، لكنه سيبقى بعيدًا عن متطلبات الإعلان. إعادة الكتابة تستغرق وقتًا، والسيرة ستبدو غير مركزة، مما يقلل فرص قراءتها.","consequenceEn":"The volunteering entry can be rewritten to show organising skills, but it will still not match the advert's requirements. Rewriting takes time, and the CV will look unfocused, reducing the chance it will be read.","isBest":false},{"id":"d3","optionAr":"احذف كلا الإدخالين وأركز على ما يتطابق مع الإعلان.","optionEn":"Remove both entries and focus on what matches the advert.","consequenceAr":"السيرة تصبح أقصر وأكثر تركيزًا. كل ما يبقى يجيب مباشرة على الإعلان، مما يزيد فرص قراءتها.","consequenceEn":"The CV becomes shorter and more focused. Everything that remains answers the advert directly, increasing the chance it will be read.","isBest":true},{"id":"d4","optionAr":"أبقي إدخال التطوع لأنه أول تجربة تنظيمية لي، وأحذف مايكروسوفت أوفيس.","optionEn":"Keep the volunteering entry because it is my first organising experience, and remove Microsoft Office.","consequenceAr":"الإدخال يبقى لأنه يحمل قيمة شخصية، لكنه لا يوضح استخدام الأداة المحددة أو مهارات إدارة المشاريع. السيرة ستبدو غير متطابقة مع الإعلان، وقد يُنظر إلى الإدخال كملء مساحة.","consequenceEn":"The entry stays because it has personal value, but it does not show using the specific tool or project-management skills. The CV will look mismatched to the advert, and the entry may be seen as filler.","isBest":false}]}},{"id":"b_l2_sort_selection","type":"sort_buckets","objectiveId":"JOB-01","payload":{"buckets":[{"id":"keep","labelAr":"يُحتفظ به","labelEn":"Keep"},{"id":"remove","labelAr":"يُحذف","labelEn":"Remove"}],"cards":[{"id":"c1","textAr":"خبرة في مايكروسوفت إكسل","textEn":"Experience with Microsoft Excel","bucketId":"remove","whyAr":"ما لم يُظهر كيف استخدمت إكسل في سياق الإعلان، لا يضيف شيئًا.","whyEn":"Unless it shows how you used Excel in the context the advert asks for, it adds nothing."},{"id":"c2","textAr":"أنشأت تقارير شهرية باستخدام أداة إدارة المشاريع","textEn":"Created monthly reports using a project management tool","bucketId":"keep","whyAr":"هذا يوضح استخدام الأداة المحددة في الإعلان، مع نتيجة واضحة.","whyEn":"This shows using the specific tool the advert asks for, with a clear result."},{"id":"c3","textAr":"متطوع في تنظيم فعالية مدرسية","textEn":"Volunteered to organise a school event","bucketId":"remove","whyAr":"ما لم يُعاد كتابته ليوضح مهارات ذات صلة، مثل التخطيط أو العمل الجماعي، فهو لا يجيب على الإعلان.","whyEn":"Unless rewritten to show relevant skills like planning or teamwork, it does not answer the advert."},{"id":"c4","textAr":"قادت فريقًا لتسليم مشروع في الموعد المحدد","textEn":"Led a team to deliver a project on deadline","bucketId":"keep","whyAr":"هذا يوضح مهارة ذات صلة بالإعلان، مع نتيجة واضحة.","whyEn":"This shows a skill relevant to the advert, with a clear result."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"JOB-01","payload":{"itemRef":"JOB-01-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"JOB-01","payload":{"itemRef":"JOB-01-KC-02"}}]}},"items":[{"key":"JOB-01-KC-01","objectiveId":"JOB-01","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"أي من هذه الإدخالات يجيب مباشرة على إعلان يطلب «إدارة حسابات العملاء وحل الشكاوى بسرعة»؟","stemEn":"Which of these entries directly answers an advert asking for 'manage client accounts and resolve complaints quickly'?","rationaleAr":"الإدخال الصحيح يربط الإعلان بما فعلته والنتيجة التي حققتها.","rationaleEn":"The correct entry connects the advert to what you did and the result you achieved.","options":[{"textAr":"«مسؤول عن حسابات العملاء»","textEn":"'Responsible for client accounts'","isCorrect":false,"feedbackAr":"هذا يصف الدور فقط، دون توضيح ما فعلته أو الأثر الذي حققته.","feedbackEn":"This describes the role only, without showing what you did or the impact."},{"textAr":"«أدرتُ حسابات العملاء، وحللت الشكاوى باستخدام نظام CRM، وقللت وقت الاستجابة من يومين إلى أربع ساعات»","textEn":"'Managed client accounts, resolved complaints using the CRM system, and reduced response time from two days to four hours'","isCorrect":true,"feedbackAr":"هذا يوضح الفعل، الأداة المستخدمة، والنتيجة، وكلها تطابق الإعلان.","feedbackEn":"This shows the action, the tool used, and the result, all matching the advert."},{"textAr":"«خبرة في خدمة العملاء»","textEn":"'Experience in customer service'","isCorrect":false,"feedbackAr":"هذا عام جدًا ولا يربط الإعلان بما فعلته.","feedbackEn":"This is too general and does not connect the advert to what you did."},{"textAr":"«استخدمت نظام CRM لإدارة الحسابات»","textEn":"'Used a CRM system to manage accounts'","isCorrect":false,"feedbackAr":"هذا يوضح الأداة ولكنه لا يوضح النتيجة أو الأثر.","feedbackEn":"This shows the tool but not the result or impact."}]},{"key":"JOB-01-KC-02","objectiveId":"JOB-01","type":"MULTI_SELECT","bloom":"ANALYZE","formative":true,"stemAr":"أي من هذه يجب حذفه من السيرة الذاتية بناءً على إعلان يطلب «خبرة في إدارة المشاريع باستخدام أداة محددة»؟","stemEn":"Which of these should be removed from a CV based on an advert asking for 'experience in project management using a specific tool'?","rationaleAr":"الإدخالات التي لا تظهر استخدام الأداة المحددة أو مهارات ذات صلة يجب حذفها.","rationaleEn":"Entries that do not show using the specific tool or relevant skills should be removed.","options":[{"textAr":"«خبرة في مايكروسوفت أوفيس»","textEn":"'Experience with Microsoft Office'","isCorrect":true,"feedbackAr":"ما لم يُظهر كيف استخدمت أوفيس في إدارة المشاريع، لا يضيف شيئًا.","feedbackEn":"Unless it shows how you used Office for project management, it adds nothing."},{"textAr":"«أنشأت تقارير شهرية باستخدام أداة إدارة المشاريع»","textEn":"'Created monthly reports using a project management tool'","isCorrect":false,"feedbackAr":"هذا يوضح استخدام الأداة المحددة مع نتيجة واضحة.","feedbackEn":"This shows using the specific tool with a clear result."},{"textAr":"«متطوع في تنظيم فعالية مدرسية»","textEn":"'Volunteered to organise a school event'","isCorrect":true,"feedbackAr":"ما لم يُعاد كتابته ليوضح مهارات ذات صلة، مثل التخطيط، فهو لا يجيب على الإعلان.","feedbackEn":"Unless rewritten to show relevant skills like planning, it does not answer the advert."},{"textAr":"«قادت فريقًا لتسليم مشروع في الموعد المحدد»","textEn":"'Led a team to deliver a project on deadline'","isCorrect":false,"feedbackAr":"هذا يوضح مهارة ذات صلة بالإعلان مع نتيجة واضحة.","feedbackEn":"This shows a skill relevant to the advert with a clear result."}]}]},{"lesson":{"slug":"answering-interview-questions","titleAr":"الإجابة على أسئلة المقابلة بأمثلة واقعية","titleEn":"Answering interview questions with real examples","estMinutes":35,"bilingual":true,"levels":["L1","L2"],"objectives":["JOB-02"],"conceptsIntroduced":["situation_task_action_result","star_structure","behavioural_question"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"JOB-02","payload":{"textAr":"لماذا الأمثلة؟","textEn":"Why examples matter","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"JOB-02","payload":{"mdAr":"أسئلة المقابلة السلوكية مثل «حدثني عن وقت تعاملت فيه مع عميل صعب» أو «صف خطأ ارتكبته وماذا فعلت» لا تسأل عن ما تعتقد أنه الإجابة الصحيحة، بل عن كيفية تفكيرك وتصرفك في موقف حقيقي. المثال الواحد الجيد أفضل من قائمة المبادئ العامة، لأن المحاور يريد دليلًا على ما ستفعله يوم الاثنين، وليس ما تقوله الآن.","mdEn":"Behavioural interview questions like \"Tell me about a time you dealt with a difficult customer\" or \"Describe a mistake you made and what you did\" are not asking for what you think the right answer is. They are asking for how you think and act in a real situation. One good example is better than a list of general principles, because the interviewer wants evidence of what you will do on Monday, not what you say now."}},{"id":"b_l1_def_star","type":"definition_card","objectiveId":"JOB-02","payload":{"termAr":"هيكل STAR","termEn":"STAR structure","defAr":"طريقة لترتيب مثال واحد في أربع أجزاء: Situation (الموقف)، Task (المهمة)، Action (الإجراء)، Result (النتيجة).","defEn":"A way to organise one example into four parts: Situation, Task, Action, Result.","icon":"✦","exampleAr":"مثال تدريبي: في وظيفتي السابقة، كان علينا تسليم تقرير في يومين (الموقف)، وكان دوري جمع البيانات من ثلاثة أقسام (المهمة). اتصلت بكل قسم وطلبت البيانات أولًا، ثم راجعت الأرقام مع كل منهم للتأكد من صحتها (الإجراء)، فأكملنا التقرير في الوقت المحدد وتعلمت أهمية التواصل المبكر (النتيجة).","exampleEn":"Training example: In my last job, we had to deliver a report in two days (Situation), and my task was to gather data from three departments (Task). I contacted each department first, then reviewed the numbers with each of them to confirm accuracy (Action), and we finished the report on time and I learned the importance of early communication (Result)."}},{"id":"b_l1_def_behavioural","type":"definition_card","objectiveId":"JOB-02","payload":{"termAr":"السؤال السلوكي","termEn":"Behavioural question","defAr":"سؤال يطلب مثالًا محددًا من ماضيك ليرى كيف ستتصرف في المستقبل.","defEn":"A question that asks for a specific example from your past to see how you will act in the future.","icon":"?"}},{"id":"b_l1_compare_answers","type":"compare_table","objectiveId":"JOB-02","payload":{"captionAr":"الإجابة العامة مقابل الإجابة بأمثلة","captionEn":"General answer compared with an example-based answer","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"إجابة عامة","labelEn":"General answer"},{"labelAr":"إجابة بأمثلة","labelEn":"Example-based answer"}],"rows":[[{"textAr":"ماذا تقول","textEn":"What you say"},{"textAr":"«أنا دائمًا هادئ مع العملاء الصعبين»","textEn":"\"I always stay calm with difficult customers.\""},{"textAr":"«في وظيفتي الأخيرة، كان لدينا عميل يطلب تعديلات مستمرة على التقرير. قلت له إن التعديلات الإضافية ستتطلب وقتًا إضافيًا، واتفقنا على موعد نهائي جديد»","textEn":"\"In my last job, we had a client who kept asking for changes to the report. I told them additional changes would require extra time, and we agreed on a new deadline.\""}],[{"textAr":"ماذا يظهر","textEn":"What it shows"},{"textAr":"مبادئ، لا دليلًا","textEn":"Principles, no evidence"},{"textAr":"موقف حقيقي، تصرفات محددة، نتيجة واضحة","textEn":"A real situation, specific actions, a clear result"}],[{"textAr":"كيف يُقيّم","textEn":"How it is judged"},{"textAr":"«هل هذا صحيح؟»","textEn":"\"Is this true?\""},{"textAr":"«هل أستطيع أن أرى نفسي أعمل معك؟»","textEn":"\"Can I see myself working with you?\""}]]}},{"id":"b_l1_flow_star","type":"process_flow","objectiveId":"JOB-02","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"الموقف","labelEn":"Situation","detailAr":"أين ومتى حدث هذا؟ (جملة أو اثنتان)","detailEn":"Where and when did this happen? (one or two sentences)"},{"id":"s2","labelAr":"المهمة","labelEn":"Task","detailAr":"ما كان دورك أو ما كان يجب تحقيقه؟","detailEn":"What was your responsibility, or what needed to be achieved?"},{"id":"s3","labelAr":"الإجراء","labelEn":"Action","detailAr":"ماذا فعلت أنت، خطوة بخطوة؟ (استخدم «أنا»)","detailEn":"What did you do, step by step? (Use \"I\")"},{"id":"s4","labelAr":"النتيجة","labelEn":"Result","detailAr":"ماذا حدث، وماذا تعلمت؟","detailEn":"What happened, and what did you learn?"}]}},{"id":"b_l1_tip_weakness","type":"job_tip","objectiveId":"JOB-02","payload":{"mdAr":"عندما يُسأل عن نقطة ضعف، اختر نقطة حقيقية ومتواضعة، ثم أظهر ما تفعله حيالها. الإجابة القوية هي: «أحيانًا أركز كثيرًا على التفاصيل حتى أفوّت الصورة العامة، لذلك الآن أخصص وقتًا لمراجعة الأهداف قبل البدء». الإجابة الضعيفة هي: «أنا مثالي جدًا» — المحاور يعرف أنك تتجنب السؤال.","mdEn":"When asked about a weakness, pick a real, modest one, then show what you are doing about it. A strong answer is: \"Sometimes I focus too much on details and miss the big picture, so now I set aside time to review the goals before I start.\" A weak answer is: \"I am too much of a perfectionist\" — the interviewer knows you are dodging the question."}},{"id":"b_l1_tip_pause","type":"job_tip","objectiveId":"JOB-02","payload":{"mdAr":"إذا احتجت إلى لحظة للتفكير، قل: «اسمح لي أن أفكر لحظة». وقفة قصيرة تليها إجابة واضحة أفضل من إجابة فورية غامضة.","mdEn":"If you need a moment to think, say: \"Let me think for a moment.\" A short pause followed by a clear answer is better than an immediate vague one."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"JOB-02","payload":{"itemsAr":["الإجابة الجيدة تركز على مثال واحد حقيقي، لا على مبادئ عامة.","هيكل STAR يرتب المثال في أربع خطوات: الموقف، المهمة، الإجراء، النتيجة.","الإجراء هو أطول جزء، ويستخدم «أنا» للخطوات التي قمت بها أنت.","النتيجة تُظهر ما حدث وما تعلمته، وليس فقط ما كان مقصودًا."],"itemsEn":["A good answer focuses on one real example, not general principles.","The STAR structure organises the example into four steps: Situation, Task, Action, Result.","Action is the longest part, and uses \"I\" for the steps you took yourself.","Result shows what happened and what you learned, not just what was intended."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"JOB-02","payload":{"textAr":"طبّق الهيكل","textEn":"Put the structure to work","level":2}},{"id":"b_l2_worked_example","type":"worked_example","objectiveId":"JOB-02","payload":{"promptAr":"السؤال: «حدثني عن وقت عملت فيه مع فريق لتحقيق هدف تحت ضغط الوقت». لديك مثال: في وظيفتك السابقة، كان عليك إعداد تقرير لتحليل بيانات من ثلاثة أقسام، وكان الموعد النهائي بعد يومين.","promptEn":"Question: \"Tell me about a time you worked with a team to meet a deadline under pressure.\" You have an example: in your previous job, you had to prepare a report analysing data from three departments, with a deadline in two days.","steps":[{"showAr":"ابدأ بالموقف: «في وظيفتي السابقة، كان علينا تسليم تقرير لتحليل بيانات ثلاثة أقسام في يومين».","showEn":"Start with the Situation: \"In my previous job, we had to deliver a report analysing data from three departments in two days.\"","whyAr":"الموقف القصير يضع السياق دون أن يسرق وقت الإجراء. لو وصفت كل قسم وتفاصيل التقرير، لبدا كأنك تتجنب الحديث عن أفعالك.","whyEn":"A short Situation sets context without stealing time from the Action. If you described each department and report details, it would sound like you're avoiding talking about what you did."},{"showAr":"حدد المهمة: «كان دوري جمع البيانات من كل قسم والتأكد من دقتها».","showEn":"Define the Task: \"My task was to gather the data from each department and confirm its accuracy.\"","whyAr":"المهمة توضح مسؤوليتك المحددة، وليس مجرد تكرار الموقف. لو قلت «كان علينا تسليم التقرير»، لبدا كأنك تتجنب تحديد دورك.","whyEn":"The Task clarifies your specific responsibility, not just restating the Situation. If you said \"We had to deliver the report,\" it would sound like you're avoiding specifying your role."},{"showAr":"صف الإجراء خطوة بخطوة: «اتصلت بكل قسم وطلبت البيانات أولًا، ثم راجعت الأرقام مع كل منهم للتأكد من صحتها».","showEn":"Describe the Action step by step: \"I contacted each department and requested the data first, then reviewed the numbers with each of them to confirm accuracy.\"","whyAr":"الإجراء هو الجزء الذي يثبت مهاراتك. لو قلت «جمعنا البيانات»، لبدا كأنك لم تفعل شيئًا بنفسك. استخدام «أنا» يوضح بالضبط ما فعلته.","whyEn":"Action is where you prove your skills. If you said \"We gathered the data,\" it would sound like you didn't do anything yourself. Using \"I\" makes clear exactly what you did."},{"showAr":"اختم بالنتيجة: «أكملنا التقرير في الوقت المحدد، وتعلمت أهمية التواصل المبكر مع الفرق الأخرى».","showEn":"End with the Result: \"We finished the report on time, and I learned the importance of early communication with other teams.\"","whyAr":"النتيجة تُظهر الأثر وليس مجرد النية. لو قلت «التقرير كان جاهزًا»، لبدا كأنك لم تستفد من التجربة. ذكر ما تعلمته يثبت أنك تفكر في التحسين.","whyEn":"Result shows impact, not just intention. If you said \"The report was ready,\" it would sound like you didn't learn from the experience. Mentioning what you learned proves you think about improvement."}],"answerAr":"«في وظيفتي السابقة، كان علينا تسليم تقرير لتحليل بيانات ثلاثة أقسام في يومين (الموقف). كان دوري جمع البيانات من كل قسم والتأكد من دقتها (المهمة). اتصلت بكل قسم وطلبت البيانات أولًا، ثم راجعت الأرقام مع كل منهم للتأكد من صحتها (الإجراء). أكملنا التقرير في الوقت المحدد، وتعلمت أهمية التواصل المبكر مع الفرق الأخرى (النتيجة)».","answerEn":"\"In my previous job, we had to deliver a report analysing data from three departments in two days (Situation). My task was to gather the data from each department and confirm its accuracy (Task). I contacted each department and requested the data first, then reviewed the numbers with each of them to confirm accuracy (Action). We finished the report on time, and I learned the importance of early communication with other teams (Result).\""}},{"id":"b_l2_scenario_weakness","type":"scenario","objectiveId":"JOB-02","payload":{"situationAr":"السؤال: «ما هي أكبر نقطة ضعف لديك؟». لديك مثالان: الأول، أنك أحيانًا تركز على التفاصيل حتى تفوّت الصورة العامة؛ الثاني، أنك تستغرق وقتًا أطول من الآخرين في تعلم البرامج الجديدة.","situationEn":"Question: \"What is your greatest weakness?\" You have two examples: first, that you sometimes focus on details and miss the big picture; second, that you take longer than others to learn new software.","decisions":[{"id":"d1","optionAr":"اختر المثال الثاني، لأنه أقل خطورة.","optionEn":"Pick the second example, because it is less risky.","consequenceAr":"المحاور قد يرى أن هذا ضعف تقني يمكن تجاوزه، وليس نمط تفكير قد يؤثر على العمل اليومي.","consequenceEn":"The interviewer may see this as a technical weakness that can be overcome, not a thinking pattern that will affect daily work.","isBest":false},{"id":"d2","optionAr":"اختر المثال الأول، وأظهر ما تفعله حياله.","optionEn":"Pick the first example, and show what you are doing about it.","consequenceAr":"المثال حقيقي ومتواضع، والإجراء يُظهر أنك تدرك المشكلة وتعمل على حلها، وهذا ما يبحث عنه المحاور.","consequenceEn":"The example is real and modest, and the action shows you recognise the problem and are working on it — exactly what the interviewer is looking for.","isBest":true},{"id":"d3","optionAr":"قل إنك لا تعرف، أو إنك مثالي جدًا.","optionEn":"Say you don't know, or that you are too much of a perfectionist.","consequenceAr":"المحاور يعرف أنك تتجنب السؤال، وهذا يترك انطباعًا سلبيًا.","consequenceEn":"The interviewer knows you are dodging the question, and this leaves a negative impression.","isBest":false}]}},{"id":"b_l2_sort_parts","type":"sort_buckets","objectiveId":"JOB-02","payload":{"buckets":[{"id":"situation","labelAr":"الموقف","labelEn":"Situation"},{"id":"task","labelAr":"المهمة","labelEn":"Task"},{"id":"action","labelAr":"الإجراء","labelEn":"Action"},{"id":"result","labelAr":"النتيجة","labelEn":"Result"}],"cards":[{"id":"c1","textAr":"كان علينا تسليم تقرير في يومين","textEn":"We had to deliver a report in two days","bucketId":"situation","whyAr":"يصف السياق الزمني والمكاني دون تفاصيل غير ضرورية. لو ذكرت تفاصيل التقرير، لبدا كأنك تتجنب الحديث عن أفعالك.","whyEn":"Describes the time and place context without unnecessary details. If you mentioned report details, it would sound like you're avoiding talking about your actions."},{"id":"c2","textAr":"كان دوري جمع البيانات من ثلاثة أقسام","textEn":"My task was to gather data from three departments","bucketId":"task","whyAr":"يحدد مسؤوليتك المحددة، وليس مجرد تكرار الموقف. لو قلت «كان علينا تسليم التقرير»، لبدا كأنك تتجنب تحديد دورك.","whyEn":"Defines your specific responsibility, not just restating the Situation. If you said \"We had to deliver the report,\" it would sound like you're avoiding specifying your role."},{"id":"c3","textAr":"اتصلت بكل قسم وطلبت البيانات أولًا","textEn":"I contacted each department and requested the data first","bucketId":"action","whyAr":"يصف ما فعلته أنت، وليس ما فعله الفريق. لو قلت «جمعنا البيانات»، لبدا كأنك لم تفعل شيئًا بنفسك.","whyEn":"Describes what you did, not what the team did. If you said \"We gathered the data,\" it would sound like you didn't do anything yourself."},{"id":"c4","textAr":"أكملنا التقرير في الوقت المحدد وتعلمت أهمية التواصل المبكر","textEn":"We finished the report on time and I learned the importance of early communication","bucketId":"result","whyAr":"يُظهر الأثر وليس مجرد النية. لو قلت «التقرير كان جاهزًا»، لبدا كأنك لم تستفد من التجربة.","whyEn":"Shows impact, not just intention. If you said \"The report was ready,\" it would sound like you didn't learn from the experience."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"JOB-02","payload":{"itemRef":"JOB-02-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"JOB-02","payload":{"itemRef":"JOB-02-KC-02"}}]}},"items":[{"key":"JOB-02-KC-01","objectiveId":"JOB-02","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"أي جزء من هيكل STAR يجب أن يكون أطول جزء في الإجابة؟","stemEn":"Which part of the STAR structure should be the longest in your answer?","rationaleAr":"الإجراء هو الجزء الذي يوضح ما فعلته أنت، خطوة بخطوة، وهذا ما يبحث عنه المحاور.","rationaleEn":"Action is the part that shows what you did, step by step — this is what the interviewer is looking for.","options":[{"textAr":"الموقف","textEn":"Situation","isCorrect":false,"feedbackAr":"الموقف يضع السياق فقط، ولا يوضح تصرفاتك.","feedbackEn":"Situation only sets the context, and does not show your actions."},{"textAr":"المهمة","textEn":"Task","isCorrect":false,"feedbackAr":"المهمة تحدد ما كان عليك فعله، لكنها لا تصف ما فعلته.","feedbackEn":"Task defines what you were responsible for, but does not describe what you did."},{"textAr":"الإجراء","textEn":"Action","isCorrect":true,"feedbackAr":"الإجراء يوضح ما فعلته أنت، وهذا ما يبحث عنه المحاور.","feedbackEn":"Action shows what you did yourself — this is what the interviewer wants to hear."},{"textAr":"النتيجة","textEn":"Result","isCorrect":false,"feedbackAr":"النتيجة تُظهر ما حدث، لكنها لا تصف تصرفاتك.","feedbackEn":"Result shows what happened, but does not describe your actions."}]},{"key":"JOB-02-KC-02","objectiveId":"JOB-02","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"أي من هذه الأخطاء الشائعة يجب تجنبه في الإجابة على سؤال سلوكي؟","stemEn":"Which of these common mistakes should you avoid when answering a behavioural question?","rationaleAr":"كل خيار غير صحيح يمثل خطأً شائعًا في الإجابات.","rationaleEn":"Each incorrect option represents a common mistake in answers.","options":[{"textAr":"اختيار مثال حيث قام شخص آخر بالجزء المهم","textEn":"Choosing an example where someone else did the important part","isCorrect":true,"feedbackAr":"المحاور يريد أن يرى ما فعلته أنت، وليس ما فعله الآخرون.","feedbackEn":"The interviewer wants to see what you did, not what others did."},{"textAr":"إنفاق معظم الإجابة على وصف الموقف","textEn":"Spending most of the answer describing the situation","isCorrect":true,"feedbackAr":"الموقف مهم، لكن الإجراء هو ما يوضح تصرفاتك.","feedbackEn":"Situation is important, but Action is what shows your actions."},{"textAr":"استخدام مثال واحد للإجابة على عدة أسئلة","textEn":"Using one example to answer several questions","isCorrect":false,"feedbackAr":"هذا مقبول، بل وموصى به، إذا كان المثال مناسبًا.","feedbackEn":"This is acceptable, and even recommended, if the example fits."},{"textAr":"الانتهاء بالإجراء دون ذكر النتيجة","textEn":"Ending with the Action and not mentioning the Result","isCorrect":true,"feedbackAr":"النتيجة تُظهر ما حدث وما تعلمته، وهذا جزء مهم من الإجابة.","feedbackEn":"Result shows what happened and what you learned — an important part of the answer."}]}]},{"lesson":{"slug":"writing-a-clear-work-message","titleAr":"كتابة رسالة عمل واضحة","titleEn":"Writing a clear work message","estMinutes":30,"bilingual":true,"levels":["L1","L2"],"objectives":["JOB-03"],"conceptsIntroduced":["purpose_first","clear_ask","subject_line","short_paragraphs","tone_check","before_sending"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"JOB-03","payload":{"textAr":"لماذا تكتب رسالة عمل؟","textEn":"Why write a work message?","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"JOB-03","payload":{"mdAr":"رسالة العمل هي أداة، وليست تعبيرًا عن الذات. هدفها أن يعرف القارئ ما تريده بالضبط ومتى تريد ذلك، دون أن يضطر إلى قراءة الرسالة مرتين أو كتابة سؤال للعودة إليك.\n\nالقارئ مشغول، وغالبًا ما يقرأ على هاتف بين مهام أخرى. إذا جعلته يفكر في ما تعنيه رسالتك، فقد يتأخر الرد أو يأتي غير صحيح أو لا يأتي على الإطلاق.","mdEn":"A work message is a tool, not self-expression. Its purpose is to tell the reader exactly what you want and by when, without making them read it twice or write back to ask.\n\nThe reader is busy, often reading on a phone between other tasks. If you make them work out what your message means, the reply may be late, wrong, or not come at all."}},{"id":"b_l1_def_purpose_first","type":"definition_card","objectiveId":"JOB-03","payload":{"termAr":"الغرض أولاً","termEn":"Purpose first","defAr":"السطر الأول من الرسالة يوضح لماذا تكتب: طلب، تحديث، سؤال، أو قرار مطلوب.","defEn":"The first line of the message states why you are writing: a request, an update, a question, or a decision needed.","icon":"↑","exampleAr":"مثال: \"أحتاج إلى موافقتك على تاريخ التسليم الجديد بحلول يوم الخميس.\"","exampleEn":"Example: \"I need your approval on the new delivery date by Thursday.\""}},{"id":"b_l1_def_clear_ask","type":"definition_card","objectiveId":"JOB-03","payload":{"termAr":"طلب واضح","termEn":"Clear ask","defAr":"تحديد ما تريده بالضبط، ممن، ومتى. إذا كان هناك أكثر من طلب، رقّمها.","defEn":"Saying exactly what you want, from whom, and by when. If there are several requests, number them.","icon":"✓","exampleAr":"مثال: \"1. هل الأرقام في القسم الثاني نهائية؟\n2. إذا لم تكن كذلك، متى ستكون جاهزة؟\"","exampleEn":"Example: \"1. Are the figures in section two final?\n2. If not, when will they be ready?\""}},{"id":"b_l1_def_subject_line","type":"definition_card","objectiveId":"JOB-03","payload":{"termAr":"سطر الموضوع","termEn":"Subject line","defAr":"سطر يقول ما بداخل الرسالة، حتى يمكن العثور عليها لاحقًا.","defEn":"A line that says what is inside the message, so it can be found later.","icon":"📧","exampleAr":"مثال: \"تاريخ التسليم لطلب مارس — أحتاج إلى تأكيدك\"","exampleEn":"Example: \"Delivery date for the March order — need your confirmation\""}},{"id":"b_l1_def_short_paragraphs","type":"definition_card","objectiveId":"JOB-03","payload":{"termAr":"فقرات قصيرة","termEn":"Short paragraphs","defAr":"فكرة واحدة لكل فقرة، بدون مقدمات طويلة أو اعتذارات متكررة.","defEn":"One idea per paragraph. Avoid long introductions and repeated apologies.","icon":"✂️","exampleAr":"مثال: \"التقرير جاهز للمراجعة. هل يمكنك إعادته بحلول يوم الجمعة؟ شكرًا.\"","exampleEn":"Example: \"The report is ready for review. Can you return it by Friday? Thanks.\""}},{"id":"b_l1_def_tone_check","type":"definition_card","objectiveId":"JOB-03","payload":{"termAr":"فحص النبرة","termEn":"Tone check","defAr":"قراءة الرسالة كما لو كنت القارئ: هل تبدو باردة أو غاضبة؟ لا تكتب وأنت غاضب.","defEn":"Read the message as if you were the receiver: does it sound cold or angry? Do not write when angry.","icon":"😊","exampleAr":"مثال: \"هل يمكنك إرسال الأرقام المحدثة؟ شكرًا.\" بدلاً من \"لم أتلق الأرقام بعد.\"","exampleEn":"Example: \"Can you send the updated figures? Thanks.\" instead of \"I still haven't received the figures.\""}},{"id":"b_l1_def_before_sending","type":"definition_card","objectiveId":"JOB-03","payload":{"termAr":"قبل الإرسال","termEn":"Before sending","defAr":"التحقق من أن الشخص الصحيح مخاطب، وأن المرفقات مرفقة، وأن الأسماء والتواريخ والأرقام صحيحة.","defEn":"Check that the right person is addressed, attachments are attached, and names, dates, and numbers are correct.","icon":"✅","exampleAr":"مثال: \"هل أضفت ملف الميزانية؟ هل تاريخ الاجتماع صحيح؟\"","exampleEn":"Example: \"Did I attach the budget file? Is the meeting date correct?\""}},{"id":"b_l1_compare_messages","type":"compare_table","objectiveId":"JOB-03","payload":{"captionAr":"رسالة واضحة مقابل رسالة غير واضحة","captionEn":"A clear message compared with an unclear one","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"واضح","labelEn":"Clear"},{"labelAr":"غير واضح","labelEn":"Unclear"}],"rows":[[{"textAr":"السطر الأول","textEn":"First line"},{"textAr":"يذكر الغرض مباشرة","textEn":"States the purpose immediately"},{"textAr":"يبدأ بخلفية أو اعتذار","textEn":"Starts with background or apology"}],[{"textAr":"الطلب","textEn":"The ask"},{"textAr":"يقول ما هو مطلوب ومتى","textEn":"Says what is needed and by when"},{"textAr":"\"هل يمكنك النظر في هذا؟\"","textEn":"\"Can you look at this?\""}],[{"textAr":"الطول","textEn":"Length"},{"textAr":"فقرات قصيرة، فكرة واحدة لكل فقرة","textEn":"Short paragraphs, one idea each"},{"textAr":"فقرة واحدة طويلة","textEn":"One long paragraph"}],[{"textAr":"المرفقات","textEn":"Attachments"},{"textAr":"تم التحقق من وجودها","textEn":"Checked for presence"},{"textAr":"قد تُنسى","textEn":"May be forgotten"}],[{"textAr":"الرد المتوقع","textEn":"Expected reply"},{"textAr":"يعرف القارئ ما يجب فعله","textEn":"Reader knows what to do"},{"textAr":"قد يحتاج القارئ إلى السؤال","textEn":"Reader may need to ask"}]]}},{"id":"b_l1_tip_reply","type":"job_tip","objectiveId":"JOB-03","payload":{"mdAr":"عند الرد، أجب عن كل سؤال بالترتيب الذي سُئل به. إذا لم تستطع الإجابة بعد، قل متى ستفعل.","mdEn":"When replying, answer every question in the order it was asked. If you cannot answer yet, say when you will."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"JOB-03","payload":{"itemsAr":["السطر الأول يوضح الغرض.","الطلب الواضح يقول ما تريده ومتى.","سطر الموضوع يقول ما بداخل الرسالة.","فقرات قصيرة، فكرة واحدة لكل فقرة.","اقرأ الرسالة كما لو كنت القارئ.","قبل الإرسال، تحقق من كل شيء."],"itemsEn":["The first line states the purpose.","A clear ask says what you want and by when.","The subject line says what is inside.","Short paragraphs, one idea each.","Read the message as if you were the receiver.","Before sending, check everything."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"JOB-03","payload":{"textAr":"طبّق ما تعلمت","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_example","type":"worked_example","objectiveId":"JOB-03","payload":{"promptAr":"لديك تقرير جاهز للمراجعة. تريد من زميلك مراجعته وإعادته بحلول يوم الجمعة. كيف تكتب الرسالة؟","promptEn":"You have a report ready for review. You want your colleague to review it and return it by Friday. How do you write the message?","steps":[{"showAr":"ابدأ بالغرض مباشرة.","showEn":"Start with the purpose immediately.","whyAr":"القارئ يعرف لماذا تكتب قبل أن يقرأ أي شيء آخر.","whyEn":"The reader knows why you are writing before reading anything else."},{"showAr":"قل ما تريده ومتى.","showEn":"Say what you want and by when.","whyAr":"الطلب الواضح لا يترك للقارئ أن يخمن.","whyEn":"A clear ask leaves no guesswork for the reader."},{"showAr":"استخدم سطر موضوع واضح.","showEn":"Use a clear subject line.","whyAr":"سطر الموضوع هو ما سيراه القارئ في صندوق الوارد وفي البحث لاحقًا.","whyEn":"The subject line is what the reader sees in the inbox and in searches later."},{"showAr":"اقرأ الرسالة كما لو كنت القارئ.","showEn":"Read the message as if you were the receiver.","whyAr":"تجنب النبرة التي قد تبدو باردة أو غاضبة.","whyEn":"Avoid a tone that might sound cold or angry."}],"answerAr":"الموضوع: تقرير مارس — المراجعة مطلوبة بحلول الجمعة\n\nمرحبًا [الاسم],\n\nأحتاج إلى مراجعتك لتقرير مارس وإعادته إليّ بحلول يوم الجمعة.\n\nشكرًا،\n[اسمك]","answerEn":"Subject: March report — review needed by Friday\n\nHi [Name],\n\nI need you to review the March report and return it to me by Friday.\n\nThanks,\n[Your name]"}},{"id":"b_l2_scenario_missing_ask","type":"scenario","objectiveId":"JOB-03","payload":{"situationAr":"طلب منك مديرك كتابة رسالة إلى فريق المالية لطلب الأرقام المحدثة للميزانية. الموعد النهائي هو اليوم، وأنت مشغول بمهمة أخرى.","situationEn":"Your manager has asked you to write a message to the finance team asking for updated budget figures. The deadline is today, and you are busy with another task.","decisions":[{"id":"d1","optionAr":"اكتب رسالة طويلة تشرح لماذا تحتاج الأرقام، ثم اطلبها في السطر الأخير.","optionEn":"Write a long message explaining why you need the figures, then ask for them in the last line.","consequenceAr":"القارئ قد لا يرى الطلب، أو قد يتأخر في الرد لأنه لا يعرف ما هو مطلوب بالضبط.","consequenceEn":"The reader may miss the ask, or delay replying because they do not know exactly what is needed.","isBest":false},{"id":"d2","optionAr":"اكتب رسالة قصيرة تبدأ بالطلب مباشرة، وتحدد الموعد النهائي.","optionEn":"Write a short message that starts with the ask immediately, and states the deadline.","consequenceAr":"القارئ يعرف بالضبط ما هو مطلوب ومتى، ويمكنه الرد بسرعة.","consequenceEn":"The reader knows exactly what is needed and by when, and can reply quickly.","isBest":true},{"id":"d3","optionAr":"أرسل رسالة تقول \"هل يمكنك إرسال الأرقام؟\" بدون موعد نهائي.","optionEn":"Send a message saying \"Can you send the figures?\" without a deadline.","consequenceAr":"القارئ لا يعرف متى تحتاج الأرقام، وقد يؤجل الرد.","consequenceEn":"The reader does not know when you need the figures, and may put off replying.","isBest":false}]}},{"id":"b_l2_scenario_tone","type":"scenario","objectiveId":"JOB-03","payload":{"situationAr":"اكتشفت خطأً في تقرير أرسلته بالأمس. تحتاج إلى أن يراجعه زميلك ويصححه اليوم.","situationEn":"You have found an error in a report you sent yesterday. You need your colleague to review and correct it today.","decisions":[{"id":"d1","optionAr":"اكتب رسالة تقول \"أرسلت التقرير الخطأ. أصلحه الآن.\"","optionEn":"Write a message saying \"I sent the wrong report. Fix it now.\"","consequenceAr":"قد يقرأ القارئ الرسالة على أنها غاضبة أو فظة، وقد لا يرغب في المساعدة.","consequenceEn":"The reader may read the message as angry or abrupt, and may not want to help.","isBest":false},{"id":"d2","optionAr":"اكتب رسالة تقول \"مرحبًا، وجدت خطأً في التقرير الذي أرسلته بالأمس. هل يمكنك مراجعته وتصحيحه اليوم؟ شكرًا.\"","optionEn":"Write a message saying \"Hi, I found an error in the report I sent yesterday. Can you review and correct it today? Thanks.\"","consequenceAr":"القارئ يعرف ما هو مطلوب ومتى، والرسالة مهذبة ومباشرة.","consequenceEn":"The reader knows what is needed and by when, and the message is polite and direct.","isBest":true},{"id":"d3","optionAr":"لا تذكر الخطأ، واطلب المراجعة فقط.","optionEn":"Do not mention the error, just ask for the review.","consequenceAr":"القارئ قد لا يفهم أهمية التصحيح، وقد لا يعطي الأولوية للمهمة.","consequenceEn":"The reader may not understand the importance of the correction, and may not prioritise the task.","isBest":false}]}},{"id":"b_l2_sort_parts","type":"sort_buckets","objectiveId":"JOB-03","payload":{"buckets":[{"id":"purpose","labelAr":"الغرض","labelEn":"Purpose"},{"id":"ask","labelAr":"الطلب","labelEn":"The ask"},{"id":"background","labelAr":"الخلفية","labelEn":"Background"}],"cards":[{"id":"c1","textAr":"\"أحتاج إلى موافقتك على تاريخ التسليم الجديد.\"","textEn":"\"I need your approval on the new delivery date.\"","bucketId":"purpose","whyAr":"يذكر الغرض مباشرة.","whyEn":"States the purpose immediately."},{"id":"c2","textAr":"\"هل الأرقام في القسم الثاني نهائية؟\"","textEn":"\"Are the figures in section two final?\"","bucketId":"ask","whyAr":"يحدد ما هو مطلوب بالضبط.","whyEn":"Specifies exactly what is needed."},{"id":"c3","textAr":"\"التقرير جاهز للمراجعة.\"","textEn":"\"The report is ready for review.\"","bucketId":"background","whyAr":"يوفر سياقًا، لكنه ليس طلبًا.","whyEn":"Provides context, but is not an ask."},{"id":"c4","textAr":"\"أحتاج إلى إعادته بحلول يوم الجمعة.\"","textEn":"\"I need it returned by Friday.\"","bucketId":"ask","whyAr":"يحدد الموعد النهائي.","whyEn":"Specifies the deadline."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"JOB-03","payload":{"itemRef":"JOB-03-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"JOB-03","payload":{"itemRef":"JOB-03-KC-02"}}]}},"items":[{"key":"JOB-03-KC-01","objectiveId":"JOB-03","type":"MCQ_SINGLE","bloom":"RECALL","formative":true,"stemAr":"ما هو الغرض من السطر الأول في رسالة العمل؟","stemEn":"What is the purpose of the first line in a work message?","rationaleAr":"السطر الأول يجب أن يوضح لماذا تكتب الرسالة، حتى يعرف القارئ ما يمكن توقعه.","rationaleEn":"The first line should state why you are writing, so the reader knows what to expect.","options":[{"textAr":"تقديم اعتذار عن الإزعاج.","textEn":"To apologise for the interruption.","isCorrect":false,"feedbackAr":"الاعتذار ليس الغرض من الرسالة، بل توضيح ما تريده.","feedbackEn":"An apology is not the purpose of the message; it is to clarify what you want."},{"textAr":"شرح الخلفية كاملة.","textEn":"To explain the full background.","isCorrect":false,"feedbackAr":"الخلفية تأتي بعد الغرض، وليس قبله.","feedbackEn":"Background comes after the purpose, not before."},{"textAr":"ذكر الغرض من الرسالة.","textEn":"To state the purpose of the message.","isCorrect":true,"feedbackAr":"هذا هو الغرض من السطر الأول: أن يعرف القارئ لماذا تكتب.","feedbackEn":"This is the purpose of the first line: the reader knows why you are writing."},{"textAr":"ترك القارئ يخمن.","textEn":"To leave the reader guessing.","isCorrect":false,"feedbackAr":"الرسالة الواضحة لا تترك القارئ يخمن.","feedbackEn":"A clear message does not leave the reader guessing."}]},{"key":"JOB-03-KC-02","objectiveId":"JOB-03","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"أي من هذه الطلبات تعتبر واضحة؟ (اختر كل ما ينطبق)","stemEn":"Which of these asks are clear? (Select all that apply)","rationaleAr":"الطلب الواضح يقول ما هو مطلوب ومتى، دون ترك مجال للتخمين.","rationaleEn":"A clear ask says what is needed and by when, without leaving room for guesswork.","options":[{"textAr":"\"هل يمكنك إرسال الأرقام؟\"","textEn":"\"Can you send the figures?\"","isCorrect":false,"feedbackAr":"هذا الطلب لا يحدد ما هي الأرقام المطلوبة أو متى تحتاجها، مما يترك مجالًا للتخمين.","feedbackEn":"This ask does not specify which figures are needed or when, leaving room for guesswork."},{"textAr":"\"أحتاج إلى الأرقام المحدثة للميزانية بحلول يوم الخميس.\"","textEn":"\"I need the updated budget figures by Thursday.\"","isCorrect":true,"feedbackAr":"هذا الطلب واضح: يحدد ما هو مطلوب (الأرقام المحدثة للميزانية) ومتى (يوم الخميس).","feedbackEn":"This ask is clear: it specifies what is needed (updated budget figures) and by when (Thursday)."},{"textAr":"\"هل يمكنك مراجعة التقرير؟\"","textEn":"\"Can you review the report?\"","isCorrect":false,"feedbackAr":"هذا الطلب لا يحدد متى يجب إتمام المراجعة، مما يجعله غير واضح.","feedbackEn":"This ask does not specify when the review should be completed, making it unclear."},{"textAr":"\"أحتاج إلى مراجعتك للتقرير وإعادته إليّ بحلول يوم الجمعة.\"","textEn":"\"I need you to review the report and return it to me by Friday.\"","isCorrect":true,"feedbackAr":"هذا الطلب واضح: يحدد ما هو مطلوب (مراجعة التقرير وإعادته) ومتى (يوم الجمعة).","feedbackEn":"This ask is clear: it specifies what is needed (review the report and return it) and by when (Friday)."}]}]},{"lesson":{"slug":"your-first-week","titleAr":"أسبوعك الأول: تعلّم الوظيفة عن قصد","titleEn":"Your first week: learning the job on purpose","estMinutes":35,"bilingual":true,"levels":["L1","L2"],"objectives":["JOB-04"],"conceptsIntroduced":["what_good_looks_like","who_to_ask_for_what","write_things_down","ask_good_questions","watch_how_things_are_done","be_careful_with_changes","agree_a_check_in"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"JOB-04","payload":{"textAr":"لماذا الأسبوع الأول مهم","textEn":"Why the first week matters","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"JOB-04","payload":{"mdAr":"الأسبوع الأول هو الوقت الأسهل لطرح الأسئلة والأصعب لمعرفة أي الأسئلة يجب طرحها. الأشخاص الذين يبدأون بشكل جيد ليسوا عادةً من يعرفون كل شيء مسبقًا، بل من يكتشفون عمدًا ما يهم.\n\nالهدف ليس أن تبدو كفئًا، بل أن تتعلم بسرعة كيف تُنجز العمل هنا. كل سؤال تطرحه الآن يوفر عليك ساعات من التخمين لاحقًا.","mdEn":"The first week is when it's easiest to ask questions and hardest to know which ones to ask. People who start well are usually not those who already know everything, but those who deliberately find out what matters.\n\nThe goal isn't to look competent - it's to learn quickly how work gets done here. Every question you ask now saves hours of guessing later."}},{"id":"b_l1_def_good","type":"definition_card","objectiveId":"JOB-04","payload":{"termAr":"ما يبدو عليه الأداء الجيد","termEn":"What good looks like","defAr":"التوقعات الواضحة لما يعتبر نجاحًا في هذه الوظيفة خلال الشهر الأول.","defEn":"Clear expectations of what success in this role looks like during the first month.","icon":"🎯","exampleAr":"مثال تدريبي: مديرك يقول إن الأداء الجيد يعني إرسال 95% من المطالبات النظيفة في الوقت المحدد خلال أول شهر.","exampleEn":"Training example: Your manager says good performance means submitting 95% of clean claims on time during the first month."}},{"id":"b_l1_def_who_to_ask","type":"definition_card","objectiveId":"JOB-04","payload":{"termAr":"من تسأل ومتى","termEn":"Who to ask for what","defAr":"تحديد الأشخاص المناسبين لكل نوع من الأسئلة أو المساعدة في مكان العمل.","defEn":"Identifying the right people for each type of question or help in the workplace.","icon":"👥","exampleAr":"مثال تدريبي: سارة تعرف الأنظمة، وأحمد يعرف العملاء، وليلى توافق على الأمور.","exampleEn":"Training example: Sarah knows the systems, Ahmed knows the customers, and Layla approves things."}},{"id":"b_l1_compare_questions","type":"compare_table","objectiveId":"JOB-04","payload":{"captionAr":"أسئلة جيدة مقابل أسئلة غير فعالة","captionEn":"Good questions vs ineffective questions","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"سؤال جيد","labelEn":"Good question"},{"labelAr":"سؤال غير فعال","labelEn":"Ineffective question"}],"rows":[[{"textAr":"الاستعداد","textEn":"Preparation"},{"textAr":"«بحثت في المجلد المشترك والدليل ولم أجد قائمة الأسعار - أين تُحفظ؟»","textEn":"\"I looked in the shared folder and the guide, and couldn't find the price list - where is it kept?\""},{"textAr":"«أين قائمة الأسعار؟»","textEn":"\"Where is the price list?\""}],[{"textAr":"التوقيت","textEn":"Timing"},{"textAr":"تجميع عدة أسئلة صغيرة في مكالمة واحدة","textEn":"Grouping several small questions in one call"},{"textAr":"مقاطعة شخص لكل سؤال صغير","textEn":"Interrupting someone for each small question"}],[{"textAr":"الوضوح","textEn":"Clarity"},{"textAr":"«ما هي الخطوات الدقيقة لإرسال مطالبة هنا؟»","textEn":"\"What are the exact steps to submit a claim here?\""},{"textAr":"«كيف أفعل هذا؟»","textEn":"\"How do I do this?\""}],[{"textAr":"النتيجة","textEn":"Outcome"},{"textAr":"توفير وقت الشخص الآخر وإظهار الجهد","textEn":"Saves the other person's time and shows effort"},{"textAr":"يبدو وكأنك لم تحاول","textEn":"Appears like you didn't try"}]]}},{"id":"b_l1_flow_first_week","type":"process_flow","objectiveId":"JOB-04","payload":{"steps":[{"id":"s1","labelAr":"اسأل عن التوقعات","labelEn":"Ask about expectations","detailAr":"اسأل مديرك مباشرة: كيف يبدو الشهر الأول الجيد؟","detailEn":"Ask your manager directly: what does a good first month look like?"},{"id":"s2","labelAr":"تعرّف على الأشخاص الرئيسيين","labelEn":"Identify key people","detailAr":"تعلم من يساعد في الأنظمة، من يعرف العملاء، ومن يوافق على الأمور.","detailEn":"Learn who helps with systems, who knows customers, and who approves things."},{"id":"s3","labelAr":"دوّن المعلومات","labelEn":"Write things down","detailAr":"احتفظ بدفتر ملاحظات شخصي لكيفية إنجاز المهام هنا.","detailEn":"Keep a personal notebook of how tasks are done here."},{"id":"s4","labelAr":"راقب الممارسات الفعلية","labelEn":"Observe actual practices","detailAr":"لاحظ كيف يتواصل الزملاء وكيف تُتخذ القرارات.","detailEn":"Notice how colleagues communicate and how decisions are made."},{"id":"s5","labelAr":"اتفق على متابعة منتظمة","labelEn":"Agree on regular check-ins","detailAr":"حدد محادثات قصيرة مع مديرك في الأسابيع الأولى.","detailEn":"Schedule short conversations with your manager in the first weeks."}],"interactive":false}},{"id":"b_l1_tip_silence","type":"job_tip","objectiveId":"JOB-04","payload":{"mdAr":"**الخطأ الأكثر شيوعًا هو الصمت.** البقاء صامتًا لتظهر كفاءة غالبًا ما يؤدي إلى اكتشاف بعد أسابيع أنك كنت تقوم بمهمة بشكل خاطئ طوال الوقت. اسأل مبكرًا لتجنب إعادة العمل لاحقًا.","mdEn":"**The most common mistake is silence.** Staying silent to appear competent often leads to discovering weeks later that you've been doing a task wrong the whole time. Ask early to avoid rework later."}},{"id":"b_l1_tip_changes","type":"job_tip","objectiveId":"JOB-04","payload":{"mdAr":"**كن حذرًا مع التغييرات في وقت مبكر.** قد ترى مشاكل بوضوح، لكن دوّنها واطرحها بعد أن تفهم لماذا تُفعل الأمور بهذه الطريقة - قد يكون هناك سبب لم تره بعد.","mdEn":"**Be careful with changes early on.** You may see problems clearly, but note them and raise them after you understand why things are done this way - there may be a reason you haven't seen yet."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"JOB-04","payload":{"itemsAr":["الأسبوع الأول هو الوقت الأفضل لطرح الأسئلة التي ستوفر عليك ساعات لاحقًا.","اكتشف عمدًا ما يعتبر نجاحًا هنا، ومن يساعد في ماذا، وكيف تُنجز المهام فعليًا.","دوّن المعلومات لتجنب تكرار الأسئلة وتوفير الوقت."],"itemsEn":["The first week is the best time to ask questions that will save you hours later.","Deliberately find out what success looks like here, who helps with what, and how tasks are actually done.","Write things down to avoid repeating questions and save time."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"JOB-04","payload":{"textAr":"طبّق ما تعلمته","textEn":"Put it into practice","level":2}},{"id":"b_l2_worked_example","type":"worked_example","objectiveId":"JOB-04","payload":{"promptAr":"في يومك الثاني، لاحظت أن زملاءك يستخدمون مجلدًا مختلفًا عن الذي قيل لك في التدريب لتخزين الملفات. ماذا تفعل؟","promptEn":"On your second day, you notice colleagues using a different folder than the one you were told in training to store files. What do you do?","steps":[{"showAr":"راقب كيف يستخدم الزملاء المجلد الفعلي.","showEn":"Observe how colleagues are actually using the real folder.","whyAr":"الممارسات المكتوبة والفعلية غالبًا ما تختلف. مراقبة الاستخدام الفعلي تظهر لك كيف تُنجز المهام هنا حقًا.","whyEn":"Written procedures and actual practice often differ. Observing actual use shows you how work really gets done here."},{"showAr":"دوّن المسار الصحيح في دفتر ملاحظاتك.","showEn":"Write down the correct path in your notebook.","whyAr":"التوثيق الشخصي يضمن أنك لن تنسى أو تضطر لطرح السؤال مرة أخرى.","whyEn":"Personal documentation ensures you won't forget or need to ask the question again."},{"showAr":"اسأل زميلًا موثوقًا في وقت مناسب: «لاحظت أن الناس يستخدمون مجلد X بدلاً من Y - هل هذا هو المسار الصحيح؟»","showEn":"Ask a trusted colleague at a good time: \"I noticed people using folder X instead of Y - is this the correct path?\"","whyAr":"السؤال في الوقت المناسب مع ملاحظة ما رأيته يظهر أنك منتبه ويقلل من مقاطعة عملهم.","whyEn":"Asking at a good time with your observation shows you're attentive and minimizes interrupting their work."}],"answerAr":"راقب الاستخدام الفعلي، دوّن المسار الصحيح، ثم اسأل زميلًا موثوقًا في وقت مناسب لتأكيد ما لاحظته.","answerEn":"Observe actual use, document the correct path, then ask a trusted colleague at a good time to confirm what you observed."}},{"id":"b_l2_scenario_questions","type":"scenario","objectiveId":"JOB-04","payload":{"situationAr":"في يومك الثالث، لديك ثلاثة أسئلة صغيرة: أين تُحفظ النماذج، كيف تُرسل عبر البريد الإلكتروني الداخلي، وأين قائمة الأسعار. مديرك مشغول في اجتماع.","situationEn":"On your third day, you have three small questions: where forms are kept, how to send internal email, and where the price list is. Your manager is busy in a meeting.","decisions":[{"id":"d1","optionAr":"انتظر حتى ينتهي الاجتماع واطرح الأسئلة الثلاثة معًا.","optionEn":"Wait until the meeting ends and ask all three questions together.","consequenceAr":"مديرك يقدر أنك احترمت وقته ويجيب على الأسئلة الثلاثة في وقت واحد. تتعلم الإجابات وتوفر عليك مقاطعة أخرى لاحقًا.","consequenceEn":"Your manager appreciates that you respected their time and answers all three questions at once. You learn the answers and save another interruption later.","isBest":true},{"id":"d2","optionAr":"اطرح الأسئلة الثلاثة عبر رسالة بريد إلكتروني.","optionEn":"Send the three questions in an email.","consequenceAr":"قد يستغرق الأمر وقتًا أطول للحصول على إجابات، وقد لا تكون واضحة كما لو طُرحت شخصيًا. لكنك تحترم وقت مديرك.","consequenceEn":"It may take longer to get answers, and they might not be as clear as if asked in person. But you respect your manager's time.","isBest":false},{"id":"d3","optionAr":"قاطعه في الاجتماع لكل سؤال.","optionEn":"Interrupt the meeting for each question.","consequenceAr":"يبدو هذا غير محترف ويزعج مديرك وزملاءه. قد تحصل على إجابات سريعة لكنك تخلق انطباعًا سلبيًا.","consequenceEn":"This appears unprofessional and disrupts your manager and colleagues. You might get quick answers but create a negative impression.","isBest":false},{"id":"d4","optionAr":"تخمين الإجابات بنفسك.","optionEn":"Guess the answers yourself.","consequenceAr":"قد ترتكب أخطاء تؤدي إلى إعادة العمل لاحقًا. من الأفضل دائمًا التأكد من الإجابات الصحيحة مبكرًا.","consequenceEn":"You might make mistakes that lead to rework later. It's always better to confirm correct answers early.","isBest":false}]}},{"id":"b_l2_sort_questions","type":"sort_buckets","objectiveId":"JOB-04","payload":{"buckets":[{"id":"ask_now","labelAr":"اسأل الآن","labelEn":"Ask now"},{"id":"write_down","labelAr":"دوّن","labelEn":"Write down"},{"id":"observe_first","labelAr":"راقب أولًا","labelEn":"Observe first"}],"cards":[{"id":"c1","textAr":"كيف تُرسل مطالبة نظيفة؟","textEn":"How to submit a clean claim?","bucketId":"ask_now","whyAr":"هذه معلومة أساسية تحتاجها لبدء العمل. من الأفضل أن تسأل مبكرًا لتجنب الأخطاء.","whyEn":"This is fundamental information you need to start working. Better to ask early to avoid mistakes."},{"id":"c2","textAr":"أين تُحفظ النماذج؟","textEn":"Where are the forms kept?","bucketId":"write_down","whyAr":"هذه معلومة ستحتاجها كثيرًا. دوّن الإجابة لتجنب تكرار السؤال.","whyEn":"This is information you'll need often. Write down the answer to avoid asking repeatedly."},{"id":"c3","textAr":"كيف يتواصل الزملاء عادة؟","textEn":"How do colleagues usually communicate?","bucketId":"observe_first","whyAr":"هذه ممارسة مكان العمل التي ستتعلمها بشكل أفضل من خلال الملاحظة قبل السؤال.","whyEn":"This is workplace practice you'll learn better by observing before asking."},{"id":"c4","textAr":"ما هي التوقعات لشهري الأول؟","textEn":"What are the expectations for my first month?","bucketId":"ask_now","whyAr":"هذه معلومة أساسية تحتاجها لفهم ما يعتبر نجاحًا. اسأل مديرك مباشرة.","whyEn":"This is fundamental information you need to understand what success looks like. Ask your manager directly."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"JOB-04","payload":{"itemRef":"JOB-04-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"JOB-04","payload":{"itemRef":"JOB-04-KC-02"}}]}},"items":[{"key":"JOB-04-KC-01","objectiveId":"JOB-04","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"في يومك الأول، تريد معرفة ما يعتبر نجاحًا في هذه الوظيفة. ما هو أفضل سؤال تطرحه على مديرك؟","stemEn":"On your first day, you want to know what success looks like in this role. What's the best question to ask your manager?","rationaleAr":"السؤال المباشر عن التوقعات المحددة يوضح لك بالضبط ما يُتوقع منك، وهو ما يهدف إليه الهدف JOB-04.","rationaleEn":"The direct question about specific expectations gives you exactly what you need to know, which is what objective JOB-04 aims for.","options":[{"textAr":"«كيف يمكنني أن أكون ناجحًا هنا؟»","textEn":"\"How can I be successful here?\"","isCorrect":false,"feedbackAr":"هذا سؤال عام جدًا. لا يحدد ما يعتبر نجاحًا في هذه الوظيفة على وجه التحديد.","feedbackEn":"This is too general. It doesn't specify what success looks like in this particular role."},{"textAr":"«ما الذي يعتبر شهرًا أولًا جيدًا في هذه الوظيفة؟»","textEn":"\"What does a good first month look like in this role?\"","isCorrect":true,"feedbackAr":"هذا السؤال يحدد التوقعات بوضوح ويطلب معايير محددة للنجاح.","feedbackEn":"This question clearly specifies expectations and asks for concrete success criteria."},{"textAr":"«هل هناك أي نصائح للنجاح هنا؟»","textEn":"\"Are there any tips for success here?\"","isCorrect":false,"feedbackAr":"هذا سؤال غامض. قد تحصل على نصائح عامة بدلاً من توقعات محددة.","feedbackEn":"This is vague. You might get general advice rather than specific expectations."},{"textAr":"«ما هي المهام الرئيسية التي سأقوم بها؟»","textEn":"\"What are the main tasks I'll be doing?\"","isCorrect":false,"feedbackAr":"هذا يسأل عن المهام وليس عن معايير النجاح. قد تعرف ما تفعله دون معرفة ما يعتبر نجاحًا.","feedbackEn":"This asks about tasks, not success criteria. You might know what to do without knowing what success looks like."}]},{"key":"JOB-04-KC-02","objectiveId":"JOB-04","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"أي من هذه الإجراءات تساعدك على تعلم الوظيفة بشكل فعال في الأسبوع الأول؟ (اختر جميع ما ينطبق)","stemEn":"Which of these actions help you learn the job effectively in your first week? (Select all that apply)","rationaleAr":"هذه الإجراءات كلها جزء من تعلم الوظيفة عمدًا كما هو موضح في الهدف JOB-04.","rationaleEn":"These actions are all part of learning the job deliberately as described in objective JOB-04.","options":[{"textAr":"تحديد الأشخاص الرئيسيين لكل نوع من المساعدة","textEn":"Identifying key people for each type of help","isCorrect":true,"feedbackAr":"هذا إجراء أساسي لتعلم من تسأل ومتى، وهو جزء رئيسي من الهدف JOB-04.","feedbackEn":"This is fundamental to learning who to ask for what, a key part of objective JOB-04."},{"textAr":"البقاء صامتًا لتظهر كفاءة","textEn":"Staying silent to appear competent","isCorrect":false,"feedbackAr":"هذا هو الخطأ الأكثر شيوعًا الذي يؤدي إلى اكتشاف الأخطاء لاحقًا.","feedbackEn":"This is the most common mistake that leads to discovering errors later."},{"textAr":"دوّن المعلومات المهمة في دفتر ملاحظات شخصي","textEn":"Writing down important information in a personal notebook","isCorrect":true,"feedbackAr":"هذا يساعدك على تذكر كيفية إنجاز المهام وتجنب تكرار الأسئلة.","feedbackEn":"This helps you remember how tasks are done and avoids repeating questions."},{"textAr":"اقتراح تغييرات على الإجراءات في يومك الأول","textEn":"Suggesting changes to procedures on your first day","isCorrect":false,"feedbackAr":"من الأفضل فهم سبب القيام بالأمور بهذه الطريقة قبل اقتراح التغييرات.","feedbackEn":"It's better to understand why things are done this way before suggesting changes."},{"textAr":"اتفق على متابعة منتظمة مع مديرك","textEn":"Agreeing on regular check-ins with your manager","isCorrect":true,"feedbackAr":"هذا يساعد على اكتشاف سوء الفهم مبكرًا قبل أن يصبح مشكلة كبيرة.","feedbackEn":"This helps catch misunderstandings early before they become big problems."}]}]},{"lesson":{"slug":"priorities-and-asking-for-help","titleAr":"الأولويات والمواعيد النهائية والإبلاغ المبكر عن المشكلات","titleEn":"Priorities, deadlines and asking for help early","estMinutes":40,"bilingual":true,"levels":["L1","L2"],"objectives":["JOB-05"],"conceptsIntroduced":["urgent_important","urgent_and_important","task_list","honest_estimate","raise_early","problem_statement"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"JOB-05","payload":{"textAr":"لماذا ترتيب العمل مهم","textEn":"Why ordering work matters","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"JOB-05","payload":{"mdAr":"في العمل، عادة ما يكون هناك أكثر مما يمكنك إنجازه في الوقت المتاح. المهارة ليست في إنجاز كل شيء، بل في تحديد ما يجب إنجازه أولاً والإبلاغ مبكرًا عندما لا يمكن إنجاز شيء ما في موعده.\n\nالمشكلة ليست في وجود عمل كثير، بل في ترك المواعيد النهائية تُفوت دون إبلاغ مسبق. عندما تخبر مديرك قبل يومين من الموعد النهائي، يكون لديه خيارات: مزيد من الوقت، أو مساعدة إضافية، أو نسخة مختصرة، أو أولوية مختلفة. عندما تخبره في يوم الموعد النهائي، لا يكون لديه أي خيارات.","mdEn":"At work, there is usually more to do than time to do it. The skill is not doing everything; it is deciding what comes first and saying early when something will not be finished on time.\n\nThe problem is not having too much work — it is missing deadlines without warning. When you tell your manager two days before the deadline, they have options: more time, more help, a smaller version, or a different priority. When you tell them on the day, they have none."}},{"id":"b_l1_def_task_list","type":"definition_card","objectiveId":"JOB-05","payload":{"termAr":"قائمة المهام","termEn":"Task list","defAr":"قائمة مكتوبة بكل مهمة، موعدها النهائي، ومن ينتظرها.","defEn":"A written list of every task, its deadline, and who is waiting for it.","icon":"📋","exampleAr":"مثال تدريبي: تقرير التحليل (موعد التسليم الخميس، ينتظره فريق التسويق).","exampleEn":"Training example: Analytics report (due Thursday, awaited by the marketing team)."}},{"id":"b_l1_def_urgent_important","type":"definition_card","objectiveId":"JOB-05","payload":{"termAr":"العاجل والمهم","termEn":"Urgent and important","defAr":"العاجل له موعد نهائي قريب. المهم له تأثير كبير إذا لم يُنجز أو أُنجز بشكل خاطئ.","defEn":"Urgent means it has a near deadline. Important means it matters a lot if it is wrong or missing.","icon":"⏳"}},{"id":"b_l1_compare_urgent_important","type":"compare_table","objectiveId":"JOB-05","payload":{"captionAr":"العاجل مقابل المهم","captionEn":"Urgent vs. important","columns":[{"labelAr":"النوع","labelEn":"Type"},{"labelAr":"العاجل والمهم","labelEn":"Urgent and important"},{"labelAr":"المهم غير العاجل","labelEn":"Important, not urgent"},{"labelAr":"العاجل غير المهم","labelEn":"Urgent, not important"},{"labelAr":"غير العاجل وغير المهم","labelEn":"Neither"}],"rows":[[{"textAr":"ماذا تفعل","textEn":"What to do"},{"textAr":"أنجز أولاً","textEn":"Do first"},{"textAr":"خطط للوقت","textEn":"Schedule time"},{"textAr":"أنجز بسرعة أو أعد التوكيل","textEn":"Handle quickly or delegate"},{"textAr":"اسأل هل يحتاج إلى الإنجاز أصلًا","textEn":"Question whether it needs doing at all"}],[{"textAr":"مثال","textEn":"Example"},{"textAr":"تقرير مطلوب اليوم لدعم قرار مالي","textEn":"A report due today to support a financial decision"},{"textAr":"تحديث نظام طويل الأجل","textEn":"A long-term system upgrade"},{"textAr":"رد على بريد إلكتروني يطلب معلومات عامة","textEn":"Reply to an email asking for general information"},{"textAr":"اجتماع دوري لا يضيف قيمة","textEn":"A recurring meeting that adds no value"}]]}},{"id":"b_l1_def_honest_estimate","type":"definition_card","objectiveId":"JOB-05","payload":{"termAr":"التقدير الصادق","termEn":"Honest estimate","defAr":"تقدير الوقت الذي ستستغرقه المهمة حقًا، بما في ذلك التحقق والمقاطعات.","defEn":"An estimate of how long the task will actually take, including checking and interruptions.","icon":"⏱️","exampleAr":"مثال تدريبي: كتابة تقرير مدته ساعة، لكن التقدير الصادق هو ساعتين ونصف مع المراجعة.","exampleEn":"Training example: writing a report takes one hour, but the honest estimate is two and a half hours with review."}},{"id":"b_l1_flow_raise_early","type":"process_flow","objectiveId":"JOB-05","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"رصد المشكلة","labelEn":"Notice the problem","detailAr":"ترى أن المهمة لن تُنجز في موعدها.","detailEn":"You see that the task will not be finished on time."},{"id":"s2","labelAr":"جمع الحقائق","labelEn":"Gather facts","detailAr":"ما المهمة؟ ما المشكلة؟ ماذا فعلت بالفعل؟","detailEn":"What is the task? What is the problem? What have you already done?"},{"id":"s3","labelAr":"اقتراح حل","labelEn":"Propose a solution","detailAr":"ماذا تقترح كبديل؟","detailEn":"What do you propose as an alternative?"},{"id":"s4","labelAr":"الإبلاغ المبكر","labelEn":"Raise early","detailAr":"أخبر الشخص المسؤول بالمشكلة والحل المقترح.","detailEn":"Tell the responsible person the problem and your proposed solution."},{"id":"s5","labelAr":"التأكيد الكتابي","labelEn":"Confirm in writing","detailAr":"أرسل ملخصًا قصيرًا للتأكد من الفهم المشترك.","detailEn":"Send a brief summary to confirm shared understanding."}]}},{"id":"b_l1_def_raise_early","type":"definition_card","objectiveId":"JOB-05","payload":{"termAr":"الإبلاغ المبكر","termEn":"Raise early","defAr":"الإبلاغ عن مشكلة محتملة قبل حدوثها، مع الحقائق والحل المقترح.","defEn":"Reporting a potential problem before it happens, with the facts and a proposed solution.","icon":"🚨"}},{"id":"b_l1_def_problem_statement","type":"definition_card","objectiveId":"JOB-05","payload":{"termAr":"صياغة المشكلة","termEn":"Problem statement","defAr":"جملة واضحة تصف المهمة، المشكلة، ما فعلته بالفعل، والحل المقترح.","defEn":"A clear sentence describing the task, the problem, what you have already done, and the proposed solution.","icon":"📝","exampleAr":"مثال تدريبي: «التقرير مطلوب يوم الخميس. البيانات من الفريق الآخر لم تصل، وبدونها لا يمكنني إنهاء القسم الثالث. سألتهم مرتين. يمكنني إرسال القسمين الأول والثاني يوم الخميس والقسم الثالث بعد يوم من وصول البيانات — هل هذا مناسب؟»","exampleEn":"Training example: \"The report is due Thursday. The data from the other team has not arrived, and without it I cannot finish section three. I have asked them twice. I can send the first two sections on Thursday and section three a day after the data arrives — does that work?\""}},{"id":"b_l1_tip_list","type":"job_tip","objectiveId":"JOB-05","payload":{"mdAr":"اكتب قائمة المهام فورًا عند استلامها. المهام التي تبقى في رأسك تُنسى أو يُستهان بها.","mdEn":"Write the task list as soon as you receive work. Tasks that stay in your head get forgotten or underestimated."}},{"id":"b_l1_tip_ask","type":"job_tip","objectiveId":"JOB-05","payload":{"mdAr":"عندما لا تكون متأكدًا مما هو أهم، اسأل الشخص الذي أعطاك العمل بدلاً من التخمين.","mdEn":"When you are not sure what matters more, ask the person who set the work instead of guessing."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"JOB-05","payload":{"itemsAr":["اكتب كل مهمة مع موعدها النهائي ومن ينتظرها.","العاجل والمهم شيئان مختلفان: أنجز أولاً ما هو كلاهما.","قدّر الوقت بصدق، بما في ذلك التحقق والمقاطعات.","أبلغ عن المشكلات مبكرًا مع الحقائق والحل المقترح.","أكد الأولويات الجديدة كتابةً بعد الاتفاق عليها."],"itemsEn":["Write every task down with its deadline and who is waiting for it.","Urgent and important are different: do first what is both.","Estimate time honestly, including checking and interruptions.","Raise problems early, with the facts and a proposed solution.","Confirm new priorities in writing after agreeing them."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"JOB-05","payload":{"textAr":"طبّق ما قرأت","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_example_1","type":"worked_example","objectiveId":"JOB-05","payload":{"promptAr":"لديك ثلاث مهام: \n1. تقرير التحليل (موعد التسليم الخميس، ينتظره فريق التسويق)\n2. تحديث قاعدة البيانات (موعد التسليم الجمعة، ينتظره فريق تكنولوجيا المعلومات)\n3. الرد على بريد إلكتروني من عميل (موعد التسليم اليوم، يطلب معلومات عامة)\n\nما الذي تنجزه أولاً؟","promptEn":"You have three tasks:\n1. Analytics report (due Thursday, awaited by the marketing team)\n2. Database update (due Friday, awaited by the IT team)\n3. Reply to a client email (due today, asking for general information)\n\nWhat do you do first?","steps":[{"showAr":"صنّف كل مهمة حسب العاجل والمهم.","showEn":"Classify each task by urgent and important.","whyAr":"التصنيف يحدد الأولوية. التقرير عاجل ومهم، التحديث مهم غير عاجل، البريد الإلكتروني عاجل غير مهم.","whyEn":"The classification decides priority. The report is urgent and important, the update is important but not urgent, the email is urgent but not important."},{"showAr":"أنجز أولاً ما هو عاجل ومهم.","showEn":"Do first what is both urgent and important.","whyAr":"هذا هو العمل الذي له تأثير كبير وموعد نهائي قريب.","whyEn":"This is the work that has high impact and a near deadline."},{"showAr":"خطط للوقت للمهمة المهمة غير العاجلة.","showEn":"Schedule time for the important, not urgent task.","whyAr":"التخطيط يمنعها من أن تصبح عاجلة لاحقًا.","whyEn":"Scheduling prevents it from becoming urgent later."},{"showAr":"أنجز البريد الإلكتروني بسرعة أو أعد توكيله.","showEn":"Handle the email quickly or delegate it.","whyAr":"هذا عمل عاجل لكنه ليس مهمًا، لذا لا يستحق وقتًا طويلًا.","whyEn":"This is urgent but not important, so it does not deserve much time."}],"answerAr":"ابدأ بتقرير التحليل، ثم خطط وقتًا لتحديث قاعدة البيانات، وأجب على البريد الإلكتروني بسرعة أو أعد توكيله.","answerEn":"Start with the analytics report, then schedule time for the database update, and reply to the email quickly or delegate it."}},{"id":"b_l2_worked_example_2","type":"worked_example","objectiveId":"JOB-05","payload":{"promptAr":"اكتشفت أن تقرير التحليل لن يُنجز في موعده يوم الخميس لأن البيانات من الفريق الآخر لم تصل. ماذا تقول لمديرك؟","promptEn":"You find the analytics report will not be finished by Thursday because the data from the other team has not arrived. What do you say to your manager?","steps":[{"showAr":"ابدأ بالحقيقة: المهمة وموعدها النهائي.","showEn":"Start with the fact: the task and its deadline.","whyAr":"هذا يحدد السياق ويظهر أنك تعرف ما هو مطلوب.","whyEn":"This sets the context and shows you know what is expected."},{"showAr":"اشرح المشكلة بوضوح.","showEn":"Explain the problem clearly.","whyAr":"المشكلة ليست في عدم إنجاز العمل، بل في سبب عدم الإنجاز.","whyEn":"The problem is not that the work is not done — it is why it is not done."},{"showAr":"اذكر ما فعلته بالفعل.","showEn":"State what you have already done.","whyAr":"هذا يظهر أنك حاولت حل المشكلة بنفسك أولاً.","whyEn":"This shows you tried to solve the problem yourself first."},{"showAr":"اقترح حلًا.","showEn":"Propose a solution.","whyAr":"الإبلاغ المبكر ليس لإلقاء المشكلة، بل لإظهار أنك تفكر في الحلول.","whyEn":"Raising early is not dumping the problem — it is showing you are thinking of solutions."}],"answerAr":"«التقرير مطلوب يوم الخميس. البيانات من الفريق الآخر لم تصل، وبدونها لا يمكنني إنهاء القسمين الثالث. سألتهم مرتين. يمكنني إرسال القسمين الأول والثاني يوم الخميس والقسم الثالث بعد يوم من وصول البيانات — هل هذا مناسب؟»","answerEn":"\"The report is due Thursday. The data from the other team has not arrived, and without it I cannot finish section three. I have asked them twice. I can send the first two sections on Thursday and section three a day after the data arrives — does that work?\""}},{"id":"b_l2_scenario_1","type":"scenario","objectiveId":"JOB-05","payload":{"situationAr":"لديك أربع مهام: \n1. إعداد عرض تقديمي لعملاء جدد (موعد التسليم بعد ثلاثة أيام، ينتظره فريق المبيعات)\n2. مراجعة عقد مع مورد (موعد التسليم بعد أسبوع، ينتظره القسم القانوني)\n3. الرد على بريد إلكتروني من زميل يطلب معلومات عن مشروع قديم (موعد التسليم اليوم)\n4. حضور اجتماع دوري لفريقك (موعده بعد ساعتين)\n\nما ترتيب الأولويات الذي تختاره؟","situationEn":"You have four tasks:\n1. Prepare a presentation for new clients (due in three days, awaited by the sales team)\n2. Review a contract with a vendor (due in one week, awaited by the legal department)\n3. Reply to an email from a colleague asking for information about an old project (due today)\n4. Attend your team's recurring meeting (in two hours)\n\nWhat order of priority do you choose?","decisions":[{"id":"d1","optionAr":"الاجتماع، البريد الإلكتروني، العرض التقديمي، العقد","optionEn":"Meeting, email, presentation, contract","consequenceAr":"الاجتماع والبريد الإلكتروني عاجلان، لكنهما ليسا مهمين. العرض التقديمي والعقد مهمان، لكنهما يُنجزان في اللحظة الأخيرة، مما يزيد من خطر الخطأ أو الفشل.","consequenceEn":"The meeting and email are urgent but not important. The presentation and contract are important, but they are done at the last minute, increasing the risk of error or failure.","isBest":false},{"id":"d2","optionAr":"العرض التقديمي، العقد، البريد الإلكتروني، الاجتماع","optionEn":"Presentation, contract, email, meeting","consequenceAr":"العرض التقديمي والعقد هما الأهم، لذا يُنجزان أولاً. البريد الإلكتروني والاجتماع عاجلان لكنهما ليسا مهمين، لذا يُنجزان بسرعة أو يُعاد توكيلهما.","consequenceEn":"The presentation and contract are the most important, so they are done first. The email and meeting are urgent but not important, so they are handled quickly or delegated.","isBest":true},{"id":"d3","optionAr":"البريد الإلكتروني، العرض التقديمي، العقد، الاجتماع","optionEn":"Email, presentation, contract, meeting","consequenceAr":"البريد الإلكتروني يُنجز أولاً لأنه عاجل، لكن العرض التقديمي والعقد هما الأهم ويُنهيان في اللحظة الأخيرة، مما قد يؤدي إلى أخطاء أو تأخير.","consequenceEn":"The email is done first because it is urgent, but the presentation and contract are the most important and are finished at the last minute, which may lead to errors or delay.","isBest":false}]}},{"id":"b_l2_scenario_2","type":"scenario","objectiveId":"JOB-05","payload":{"situationAr":"اكتشفت أن مراجعة العقد لن تُنجز في موعدها الأسبوع المقبل لأن القسم القانوني طلب معلومات إضافية لم تصل بعد. الموعد النهائي هو الجمعة، واليوم هو الثلاثاء. ماذا تفعل؟","situationEn":"You find the contract review will not be finished by next week's deadline because the legal department asked for additional information that has not arrived yet. The deadline is Friday, and today is Tuesday. What do you do?","decisions":[{"id":"d1","optionAr":"انتظر حتى يوم الخميس لترى إذا وصلت المعلومات، ثم أبلغ إذا لم تصل.","optionEn":"Wait until Thursday to see if the information arrives, then raise it if it has not.","consequenceAr":"إذا لم تصل المعلومات، سيكون لديك يوم واحد فقط لحل المشكلة، مما يقلل من خيارات مديرك.","consequenceEn":"If the information does not arrive, you will have only one day to solve the problem, reducing your manager's options.","isBest":false},{"id":"d2","optionAr":"أبلغ مديرك اليوم بالمشكلة والحل المقترح.","optionEn":"Raise the problem with your manager today, with the facts and a proposed solution.","consequenceAr":"مديرك لديه ثلاثة أيام كاملة لاستكشاف الخيارات: مزيد من الوقت، أو مساعدة إضافية، أو نسخة مختصرة من المراجعة.","consequenceEn":"Your manager has three full days to explore options: more time, more help, or a smaller version of the review.","isBest":true},{"id":"d3","optionAr":"أنجز ما تستطيع من المراجعة الآن، ثم أبلغ يوم الجمعة إذا لم تصل المعلومات.","optionEn":"Do what you can of the review now, then raise it on Friday if the information has not arrived.","consequenceAr":"هذا يترك لمديرك أقل وقت ممكن، وقد يؤدي إلى عدم إنجاز المراجعة في موعدها.","consequenceEn":"This leaves your manager the least time possible, and may result in the review not being finished on time.","isBest":false}]}},{"id":"b_l2_sort_buckets","type":"sort_buckets","objectiveId":"JOB-05","payload":{"buckets":[{"id":"urgent_important","labelAr":"العاجل والمهم","labelEn":"Urgent and important"},{"id":"important_not_urgent","labelAr":"المهم غير العاجل","labelEn":"Important, not urgent"},{"id":"urgent_not_important","labelAr":"العاجل غير المهم","labelEn":"Urgent, not important"},{"id":"neither","labelAr":"غير العاجل وغير المهم","labelEn":"Neither"}],"cards":[{"id":"c1","textAr":"تقرير التحليل مطلوب يوم الخميس لدعم قرار مالي","textEn":"Analytics report due Thursday to support a financial decision","bucketId":"urgent_important","whyAr":"له موعد نهائي قريب وتأثير كبير.","whyEn":"It has a near deadline and high impact."},{"id":"c2","textAr":"تحديث نظام طويل الأجل","textEn":"Long-term system upgrade","bucketId":"important_not_urgent","whyAr":"مهم لكنه ليس له موعد نهائي قريب.","whyEn":"It is important but has no near deadline."},{"id":"c3","textAr":"رد على بريد إلكتروني يطلب معلومات عامة","textEn":"Reply to an email asking for general information","bucketId":"urgent_not_important","whyAr":"عاجل لكنه ليس له تأثير كبير.","whyEn":"It is urgent but has low impact."},{"id":"c4","textAr":"اجتماع دوري لا يضيف قيمة","textEn":"Recurring meeting that adds no value","bucketId":"neither","whyAr":"ليس له موعد نهائي قريب ولا تأثير كبير.","whyEn":"It has no near deadline and no high impact."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"JOB-05","payload":{"itemRef":"JOB-05-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"JOB-05","payload":{"itemRef":"JOB-05-KC-02"}}]}},"items":[{"key":"JOB-05-KC-01","objectiveId":"JOB-05","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"ما الخطوة الأولى عند اكتشاف أن مهمة لن تُنجز في موعدها؟","stemEn":"What is the first step when you find a task will not be finished on time?","rationaleAr":"الإبلاغ المبكر يبدأ بجمع الحقائق والحل المقترح، وليس بإلقاء المشكلة.","rationaleEn":"Raising early starts with gathering the facts and a proposed solution, not dumping the problem.","options":[{"textAr":"انتظر لترى إذا كان بإمكانك إنجازها في اللحظة الأخيرة.","textEn":"Wait to see if you can finish it at the last minute.","isCorrect":false,"feedbackAr":"هذا تجنب للمشكلة بدلاً من حلها، وقد يؤدي إلى فقدان الخيارات المتاحة.","feedbackEn":"This is avoiding the problem rather than solving it, which may lead to losing available options."},{"textAr":"أخبر مديرك فورًا أنك لن تنجز المهمة.","textEn":"Tell your manager immediately that you will not finish the task.","isCorrect":false,"feedbackAr":"هذا إلقاء للمشكلة دون تقديم سياق أو حل، مما يترك المدير بدون خيارات.","feedbackEn":"This dumps the problem without context or solution, leaving the manager with no options."},{"textAr":"اجمع الحقائق عن المهمة والمشكلة وما فعلته بالفعل، واقترح حلًا.","textEn":"Gather the facts about the task, the problem, what you have already done, and propose a solution.","isCorrect":true,"feedbackAr":"هذه هي الخطوة الصحيحة للإبلاغ المبكر: الحقائق والحل المقترح يوفران للمدير خيارات.","feedbackEn":"This is the correct first step for raising early: facts and a proposed solution give the manager options."},{"textAr":"اطلب من شخص آخر إنجاز المهمة نيابةً عنك.","textEn":"Ask someone else to do the task for you.","isCorrect":false,"feedbackAr":"هذا قد يكون جزءًا من الحل لاحقًا، لكنه ليس الخطوة الأولى الصحيحة.","feedbackEn":"This may be part of a later solution, but it is not the correct first step."}]},{"key":"JOB-05-KC-02","objectiveId":"JOB-05","type":"MCQ_SINGLE","bloom":"ANALYZE","formative":true,"stemAr":"أي من هذه المهام يجب إنجازها أولاً؟","stemEn":"Which of these tasks should be done first?","rationaleAr":"العاجل والمهم يُنجزان أولاً، المهم غير العاجل يُخطط له، والعاجل غير المهم يُنجز بسرعة أو يُعاد توكيله.","rationaleEn":"Urgent and important is done first, important but not urgent is scheduled, and urgent but not important is handled quickly or delegated.","options":[{"textAr":"تقرير مطلوب اليوم لدعم قرار مالي","textEn":"A report due today to support a financial decision","isCorrect":true,"feedbackAr":"هذا هو العمل العاجل والمهم، لذا يجب إنجازه أولاً.","feedbackEn":"This is urgent and important work, so it should be done first."},{"textAr":"تحديث قاعدة بيانات مطلوب بعد أسبوعين","textEn":"A database update due in two weeks","isCorrect":false,"feedbackAr":"هذا عمل مهم لكنه ليس عاجلًا، لذا يجب تخطيط وقت له وليس إنجازه أولاً.","feedbackEn":"This is important but not urgent, so it should be scheduled rather than done first."},{"textAr":"رد على بريد إلكتروني يطلب معلومات عامة، موعده اليوم","textEn":"Reply to an email asking for general information, due today","isCorrect":false,"feedbackAr":"هذا عمل عاجل لكنه ليس مهمًا، لذا يجب إنجازه بسرعة أو إعادة توكيله، وليس أولاً.","feedbackEn":"This is urgent but not important, so it should be handled quickly or delegated, not done first."},{"textAr":"اجتماع دوري لا يضيف قيمة","textEn":"A recurring meeting that adds no value","isCorrect":false,"feedbackAr":"هذا ليس عاجلًا ولا مهمًا، لذا يجب التشكيك في الحاجة لإنجازه على الإطلاق.","feedbackEn":"This is neither urgent nor important, so it should be questioned whether it needs doing at all."}]},{"key":"JOB-05-KC-03","objectiveId":"JOB-05","type":"MCQ_SINGLE","bloom":"RECALL","formative":true,"stemAr":"ماذا تفعل بعد الاتفاق على أولويات جديدة مع مديرك؟","stemEn":"What do you do after agreeing new priorities with your manager?","rationaleAr":"التأكيد الكتابي يضمن الفهم المشترك ويمنع سوء الفهم لاحقًا.","rationaleEn":"Confirming in writing ensures shared understanding and prevents later confusion.","options":[{"textAr":"ابدأ العمل فورًا دون تأكيد.","textEn":"Start work immediately without confirming.","isCorrect":false,"feedbackAr":"هذا قد يؤدي إلى سوء فهم إذا تغيرت الأولويات في ذهن شخص آخر.","feedbackEn":"This may lead to confusion if priorities changed in someone else's mind."},{"textAr":"أرسل ملخصًا كتابيًا قصيرًا للتأكد من الفهم المشترك.","textEn":"Send a brief written summary to confirm shared understanding.","isCorrect":true,"feedbackAr":"هذا هو التأكيد الكتابي الصحيح الذي يمنع سوء الفهم لاحقًا.","feedbackEn":"This is the correct written confirmation that prevents later confusion."},{"textAr":"انتظر حتى يسألك مديرك عن التقدم.","textEn":"Wait until your manager asks about progress.","isCorrect":false,"feedbackAr":"هذا لا يضمن أن الأولويات واضحة للطرفين.","feedbackEn":"This does not ensure priorities are clear to both sides."},{"textAr":"اطلب من مديرك إرسال التأكيد.","textEn":"Ask your manager to send the confirmation.","isCorrect":false,"feedbackAr":"المسؤولية على الشخص الذي يغير الأولويات.","feedbackEn":"The responsibility is on the person changing priorities."}]}]},{"lesson":{"slug":"feedback-and-mistakes","titleAr":"تلقّي الملاحظات والاعتراف بالخطأ","titleEn":"Receiving feedback and owning a mistake","estMinutes":40,"bilingual":true,"levels":["L1","L2"],"objectives":["JOB-06"],"conceptsIntroduced":["listen_to_understand","separate_work_from_self","feedback_correctness","early_admission","fix_what_can_be_fixed","change_something","admit_the_mistake_early","not_all_feedback_is_correct","separate_the_work_from_yourself"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"JOB-06","payload":{"textAr":"لماذا يهم ما تفعله بعد الخطأ","textEn":"Why what you do next matters","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"JOB-06","payload":{"mdAr":"الخطأ نفسه غالبًا ما يُنسى بسرعة. ما يتذكره الزملاء هو كيف استجبت له. الاستجابة الجيدة تقلل الضرر، وتبني الثقة، وتحول الموقف السلبي إلى فرصة للتعلم.","mdEn":"The mistake itself is often forgotten quickly. What colleagues remember is how you responded to it. A good response limits damage, builds trust, and turns a negative into a learning opportunity."}},{"id":"b_l1_def_listen_to_understand","type":"definition_card","objectiveId":"JOB-06","payload":{"termAr":"استمع لتفهم","termEn":"Listen to understand","defAr":"الهدف الأول عند تلقي الملاحظة هو معرفة ما يقصده الشخص بالضبط، قبل محاولة الرد أو الدفاع.","defEn":"The first goal when receiving feedback is to know exactly what the person means, before attempting to reply or defend.","icon":"👂","exampleAr":"إذا قال أحدهم: «هذا التقرير غير واضح»، اسأل: «هل يمكنك أن تريني الجزء الذي وجدته غير واضح؟»","exampleEn":"If someone says, \"This report is unclear,\" ask, \"Can you show me which part you found unclear?\""}},{"id":"b_l1_def_separate_the_work_from_yourself","type":"definition_card","objectiveId":"JOB-06","payload":{"termAr":"افصل العمل عن نفسك","termEn":"Separate the work from yourself","defAr":"الملاحظة على المهمة هي معلومات عن المهمة، وليست حكماً على قيمتك كشخص.","defEn":"Feedback on a task is information about the task. It is not a judgement of your worth as a person.","icon":"🔄","exampleAr":"إذا قيل لك إن الجدول غير منظم، فهذا لا يعني أنك غير كفء، بل يعني أن الجدول يحتاج إلى تحسين.","exampleEn":"If you are told a table is disorganized, that does not mean you are incompetent — it means the table needs improvement."}},{"id":"b_l1_def_not_all_feedback_is_correct","type":"definition_card","objectiveId":"JOB-06","payload":{"termAr":"ليست كل الملاحظات صحيحة","termEn":"Not all feedback is correct","defAr":"إذا اختلفت مع الملاحظة، عبر عن ذلك بهدوء مع ذكر السبب، بعد أن تفهم وجهة نظر الشخص.","defEn":"If you disagree with feedback, state your reason calmly, after you have understood the other person's point.","icon":"⚖️","exampleAr":"«أرى لماذا يبدو هذا الجزء غير مكتمل؛ لقد حذفته لأن العميل طلب نسخة أقصر. هل أضيفه مرة أخرى؟»","exampleEn":"\"I see why this section looks incomplete; I left it out because the client asked for a shorter version. Should I add it back?\""}},{"id":"b_l1_def_admit_the_mistake_early","type":"definition_card","objectiveId":"JOB-06","payload":{"termAr":"اعترف بالخطأ مبكرًا","termEn":"Admit the mistake early","defAr":"إخفاء الخطأ غالبًا يجعله يتفاقم. أخبر الشخص الذي يحتاج إلى المعرفة فورًا بما حدث وتأثيره.","defEn":"Hiding a mistake often lets it grow. Tell the person who needs to know, as soon as you know, what happened and its effect.","icon":"⏳","exampleAr":"إذا اكتشفت خطأ في فاتورة أرسلتها، أبلغ المحاسب فورًا بدلاً من الانتظار ليرفضها العميل.","exampleEn":"If you find an error in an invoice you sent, notify the accountant immediately rather than waiting for the client to reject it."}},{"id":"b_l1_flow_response","type":"process_flow","objectiveId":"JOB-06","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"استمع","labelEn":"Listen","detailAr":"افهم ما قيل بالضبط.","detailEn":"Understand exactly what is said."},{"id":"s2","labelAr":"افصل","labelEn":"Separate","detailAr":"افصل بين العمل والنقد الشخصي.","detailEn":"Separate the work from personal criticism."},{"id":"s3","labelAr":"قيم","labelEn":"Evaluate","detailAr":"قرر ما إذا كانت الملاحظة صحيحة.","detailEn":"Decide whether the feedback is correct."},{"id":"s4","labelAr":"اعترف","labelEn":"Admit","detailAr":"إذا كان هناك خطأ، اعترف به مبكرًا.","detailEn":"If there is a mistake, admit it early."},{"id":"s5","labelAr":"صلح","labelEn":"Correct","detailAr":"صلح ما يمكن إصلاحه.","detailEn":"Fix what can be fixed."},{"id":"s6","labelAr":"غيّر","labelEn":"Change","detailAr":"غيّر شيئًا لمنع تكرار الخطأ.","detailEn":"Change something to prevent the mistake from happening again."}]}},{"id":"b_l1_tip_thank","type":"job_tip","objectiveId":"JOB-06","payload":{"mdAr":"شكر الشخص على الملاحظة المحددة، حتى لو كانت غير مريحة، يجعله أكثر احتمالًا لإخبارك في المرة القادمة إذا كان هناك خطأ.","mdEn":"Thanking someone for specific feedback, even if it is uncomfortable, makes them more likely to tell you next time if something is wrong."}},{"id":"b_l1_tip_apology","type":"job_tip","objectiveId":"JOB-06","payload":{"mdAr":"الاعتذار المفرط يركز على المشاعر بدلاً من الإصلاح. قل ما حدث، وما فعلته، وما ستغيره، ثم انتقل.","mdEn":"Over-apologizing focuses on feelings rather than the fix. Say what happened, what you did, and what you will change, then move on."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"JOB-06","payload":{"itemsAr":["استمع لتفهم قبل الرد.","افصل بين العمل والنقد الشخصي.","إذا كان هناك خطأ، اعترف به مبكرًا وقل ما فعلته لإصلاحه.","غيّر شيئًا لمنع تكرار الخطأ."],"itemsEn":["Listen to understand before replying.","Separate the work from personal criticism.","If there is a mistake, admit it early and say what you did to correct it.","Change something to prevent the mistake from happening again."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"JOB-06","payload":{"textAr":"طبّق ما تعلمته","textEn":"Put it into practice","level":2}},{"id":"b_l2_worked_example_vague","type":"worked_example","objectiveId":"JOB-06","payload":{"promptAr":"يقول لك زميلك: «هذا التقرير غير واضح». كيف ترد؟","promptEn":"A colleague tells you, \"This report is unclear.\" How do you respond?","steps":[{"showAr":"اسأل عن مثال محدد.","showEn":"Ask for a specific example.","whyAr":"الملاحظة العامة لا تخبرك بما يحتاج إلى تغيير. المثال يحدد المشكلة.","whyEn":"Vague feedback does not tell you what needs to change. An example pinpoints the problem."},{"showAr":"استمع إلى الإجابة دون مقاطعة.","showEn":"Listen to the answer without interrupting.","whyAr":"المقاطعة تبدو دفاعية. الاستماع يظهر أنك تريد الفهم.","whyEn":"Interrupting sounds defensive. Listening shows you want to understand."},{"showAr":"اشكر الشخص على الملاحظة.","showEn":"Thank the person for the feedback.","whyAr":"الشكر يجعل الشخص يشعر بأن ملاحظته موضع ترحيب، حتى لو اختلفت معها.","whyEn":"Thanking makes the person feel their input is welcome, even if you disagree."}],"answerAr":"اسأل: «أي جزء وجدته غير واضح؟» واستمع إلى الإجابة، ثم اشكر الشخص.","answerEn":"Ask, \"Which part did you find unclear?\" Listen to the answer, then thank the person."}},{"id":"b_l2_worked_example_mistake","type":"worked_example","objectiveId":"JOB-06","payload":{"promptAr":"اكتشفت أنك أرسلت فاتورة بمبلغ 1,500 جنيه بدلًا من 1,200 جنيه إلى عميل. الموعد النهائي للدفع كان أمس. ماذا تفعل؟","promptEn":"You discover you sent an invoice for 1,500 instead of 1,200 to a client. The payment deadline was yesterday. What do you do?","steps":[{"showAr":"أبلغ العميل فورًا.","showEn":"Notify the client immediately.","whyAr":"الاعتراف المبكر يقلل من الضرر ويظهر النزاهة.","whyEn":"Early admission limits damage and shows integrity."},{"showAr":"قل ما حدث وتأثيره.","showEn":"State what happened and its effect.","whyAr":"العميل يحتاج إلى معرفة الخطأ وكيف يؤثر عليه لاتخاذ قرار.","whyEn":"The client needs to know the error and how it affects them to make a decision."},{"showAr":"أرسل الفاتورة المصححة مع اعتذار مختصر.","showEn":"Send the corrected invoice with a brief apology.","whyAr":"الفاتورة المصححة هي الإصلاح. الاعتذار المختصر يركز على الحل.","whyEn":"The corrected invoice is the fix. A brief apology keeps the focus on the solution."},{"showAr":"قل ما ستفعله لمنع تكرار الخطأ.","showEn":"Say what you will do to prevent the mistake from happening again.","whyAr":"هذا يبني الثقة ويحول الخطأ إلى فرصة للتحسين.","whyEn":"This builds trust and turns the mistake into an improvement opportunity."}],"answerAr":"اتصل بالعميل وقل: «أخطأت في الفاتورة وأرسلت مبلغ 1,500 جنيه بدلًا من 1,200 جنيه. أعتذر عن الخطأ وأرسل الفاتورة المصححة الآن. سأضيف خطوة مراجعة قبل الإرسال لمنع تكرار ذلك.»","answerEn":"Call the client and say, \"I made a mistake on the invoice and sent 1,500 instead of 1,200. I apologize for the error and am sending the corrected invoice now. I will add a review step before sending to prevent this from happening again.\""}},{"id":"b_l2_scenario_vague_feedback","type":"scenario","objectiveId":"JOB-06","payload":{"situationAr":"يقول لك مشرفك أثناء مراجعة ملف تدريبي: «هذا الجزء غير مفيد».","situationEn":"Your supervisor says during a review of a training file, \"This section is not helpful.\"","decisions":[{"id":"d1","optionAr":"اشرح لماذا أضفت هذا الجزء.","optionEn":"Explain why you included this section.","consequenceAr":"المشرف يكرر أن الجزء غير مفيد، ويبدو أنك تدافع بدلاً من الاستماع.","consequenceEn":"The supervisor repeats that the section is not helpful, and you appear defensive rather than listening.","isBest":false},{"id":"d2","optionAr":"اسأل: «ما الذي يجعله غير مفيد؟»","optionEn":"Ask, \"What makes it not helpful?\"","consequenceAr":"المشرف يعطي مثالًا محددًا، والآن تعرف بالضبط ما يحتاج إلى تغيير.","consequenceEn":"The supervisor gives a specific example, and now you know exactly what needs to change.","isBest":true},{"id":"d3","optionAr":"قل: «شكرًا، سأحذفه.»","optionEn":"Say, \"Thank you, I will remove it.\"","consequenceAr":"تحذف جزءًا ربما كان مفيدًا إذا عُدّل بدلاً من حذفه. لم تفهم السبب.","consequenceEn":"You remove a section that might have been helpful if revised rather than removed. You did not understand the reason.","isBest":false}]}},{"id":"b_l2_scenario_disagree","type":"scenario","objectiveId":"JOB-06","payload":{"situationAr":"يقول لك زميلك في المطالبات: «لقد أخطأت في ترميز هذا الإجراء. يجب أن يكون PRC-1042، وليس PRC-1043.» السجل يدعم PRC-1043.","situationEn":"A colleague in claims tells you, \"You coded this procedure wrong. It should be PRC-1042, not PRC-1043.\" The record supports PRC-1043.","decisions":[{"id":"d1","optionAr":"قل: «السجل يدعم PRC-1043، لذا هذا ليس خطأ.»","optionEn":"Say, \"The record supports PRC-1043, so this is not a mistake.\"","consequenceAr":"الزميل يشعر بأنك تدافع بدلاً من الاستماع، وقد يتوقف عن إعطائك ملاحظات.","consequenceEn":"The colleague feels you are defending rather than listening, and may stop giving you feedback.","isBest":false},{"id":"d2","optionAr":"اسأل: «لماذا تعتقد أنه يجب أن يكون PRC-1042؟»","optionEn":"Ask, \"Why do you think it should be PRC-1042?\"","consequenceAr":"تكتشف أن الزميل رأى جزءًا مختلفًا من السجل. الآن يمكنك توضيح أي جزء يدعم الترميز الصحيح.","consequenceEn":"You discover the colleague saw a different part of the record. Now you can clarify which part supports the correct code.","isBest":true},{"id":"d3","optionAr":"غيّر الترميز إلى PRC-1042 لتجنب الجدال.","optionEn":"Change the code to PRC-1042 to avoid an argument.","consequenceAr":"المطالبة تُرسل بترميز غير مدعوم، مما قد يؤدي إلى رفض أو طلب مراجعة لاحقًا.","consequenceEn":"The claim goes out with an unsupported code, which may lead to a rejection or request for review later.","isBest":false}]}},{"id":"b_l2_sort_feedback","type":"sort_buckets","objectiveId":"JOB-06","payload":{"buckets":[{"id":"correct","labelAr":"ملاحظة صحيحة","labelEn":"Correct feedback"},{"id":"incorrect","labelAr":"ملاحظة غير صحيحة","labelEn":"Incorrect feedback"}],"cards":[{"id":"c1","textAr":"«هذا الجدول غير منظم.» الجدول يحتوي على أعمدة غير متساوية العرض.","textEn":"\"This table is disorganized.\" The table has columns of unequal width.","bucketId":"correct","whyAr":"الملاحظة محددة وقابلة للتحقق.","whyEn":"The feedback is specific and verifiable."},{"id":"c2","textAr":"«هذا التقرير غير واضح.» التقرير يحتوي على جميع المعلومات المطلوبة.","textEn":"\"This report is unclear.\" The report contains all required information.","bucketId":"incorrect","whyAr":"الملاحظة عامة وغير مدعومة بأدلة.","whyEn":"The feedback is vague and not supported by evidence."},{"id":"c3","textAr":"«لقد أخطأت في ترميز هذا الإجراء.» السجل يدعم الترميز الحالي.","textEn":"\"You coded this procedure wrong.\" The record supports the current code.","bucketId":"incorrect","whyAr":"الملاحظة تتعارض مع السجل.","whyEn":"The feedback contradicts the record."},{"id":"c4","textAr":"«هذا الجزء غير ضروري.» العميل طلب إزالة هذا الجزء بالذات.","textEn":"\"This section is unnecessary.\" The client specifically asked to remove this section.","bucketId":"correct","whyAr":"الملاحظة تتوافق مع طلب العميل.","whyEn":"The feedback aligns with the client's request."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"JOB-06","payload":{"itemRef":"JOB-06-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"JOB-06","payload":{"itemRef":"JOB-06-KC-02"}}]}},"items":[{"key":"JOB-06-KC-01","objectiveId":"JOB-06","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"ما هو أفضل رد أولي على ملاحظة عامة مثل «هذا التقرير غير واضح»؟","stemEn":"What is the best initial response to vague feedback like \"This report is unclear\"?","rationaleAr":"الهدف الأول هو تحديد المشكلة بالضبط، وهذا يتطلب مثالًا محددًا.","rationaleEn":"The first goal is to pinpoint the problem, which requires a specific example.","options":[{"textAr":"اشرح لماذا كتبت التقرير بهذه الطريقة.","textEn":"Explain why you wrote the report that way.","isCorrect":false,"feedbackAr":"هذا رد دفاعي قبل فهم النقطة.","feedbackEn":"This is defensive before understanding the point."},{"textAr":"اسأل عن مثال محدد لما وجده غير واضح.","textEn":"Ask for a specific example of what they found unclear.","isCorrect":true,"feedbackAr":"هذا يحدد المشكلة ويظهر أنك تريد الفهم.","feedbackEn":"This pinpoints the problem and shows you want to understand."},{"textAr":"قل إنك ستعيد كتابته بالكامل.","textEn":"Say you will rewrite it entirely.","isCorrect":false,"feedbackAr":"هذا افتراض قبل معرفة ما يحتاج إلى تغيير.","feedbackEn":"This assumes what needs to change before knowing."},{"textAr":"اشكر الشخص وانتظر المزيد من الملاحظات.","textEn":"Thank the person and wait for more feedback.","isCorrect":false,"feedbackAr":"هذا لا يحل المشكلة أو يحددها.","feedbackEn":"This does not solve or identify the problem."}]},{"key":"JOB-06-KC-02","objectiveId":"JOB-06","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"ما الذي يجب أن يتضمنه الاعتراف المبكر بالخطأ؟ (اختر كل ما ينطبق)","stemEn":"What should an early admission of a mistake include? (Select all that apply)","rationaleAr":"الاعتراف الكامل يتطلب أربعة عناصر: ما حدث، التأثير، ما تم فعله للحد منه، وما سيتغير.","rationaleEn":"A complete admission requires four elements: what happened, the effect, what was done to limit it, and what will change.","options":[{"textAr":"ما حدث بالضبط.","textEn":"What exactly happened.","isCorrect":true,"feedbackAr":"هذا ضروري لفهم الخطأ.","feedbackEn":"This is necessary to understand the mistake."},{"textAr":"تأثير الخطأ.","textEn":"The effect of the mistake.","isCorrect":true,"feedbackAr":"هذا ضروري لاتخاذ قرار بشأن الخطوات التالية.","feedbackEn":"This is necessary to decide next steps."},{"textAr":"ما فعلته بالفعل للحد من الضرر.","textEn":"What you have already done to limit the damage.","isCorrect":true,"feedbackAr":"هذا يظهر أنك تتحمل المسؤولية.","feedbackEn":"This shows you are taking responsibility."},{"textAr":"ما ستفعله لمنع تكرار الخطأ.","textEn":"What you will do so it does not happen again.","isCorrect":true,"feedbackAr":"هذا يبني الثقة ويحول الخطأ إلى فرصة للتحسين.","feedbackEn":"This builds trust and turns the mistake into an improvement opportunity."},{"textAr":"من ساهم في الخطأ.","textEn":"Who contributed to the mistake.","isCorrect":false,"feedbackAr":"التركيز على المسؤولية الجماعية يقلل من مسؤوليتك.","feedbackEn":"Focusing on shared responsibility dilutes your ownership."}]}]},{"lesson":{"slug":"handling-a-customer-complaint","titleAr":"التعامل مع شكوى العميل","titleEn":"Handling a customer complaint","estMinutes":40,"bilingual":true,"levels":["L1","L2"],"objectives":["CS-01"],"conceptsIntroduced":["acknowledgement","establish_the_facts","ownership","agreed_next_step"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"CS-01","payload":{"textAr":"ما الشكوى؟","textEn":"What a complaint is","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"CS-01","payload":{"mdAr":"الشكوى ليست هجومًا وليست طلب اعتذار. هي العميل يخبرك أن الفجوة بين ما توقع وما حصل أصبحت تستحق وقته للإبلاغ عنها. معظم العملاء الذين يخيب أملهم لا يقولون شيئًا ويغادرون. الذي يشكو يمنحك الفرصة التي لم يمنحها الآخرون.\n\nالدقيقة الأولى تحدد العشرين التالية. العميل الذي يبدأ غاضبًا يحمل مشكلتين: الشيء الذي أخفق، والشعور بأن أحدًا لم يستمع إليه. يجب التعامل مع الثانية أولًا، لأن الشخص الذي لا يشعر بأنه سمع لا يمكنه سماع أي شيء تقوله.","mdEn":"A complaint is not an attack and it is not a request for an apology. It is a customer telling you that the gap between what they expected and what they got has become worth their time to report. Most customers who are let down say nothing and leave. The one who complains is giving you the chance the others did not.\n\nThe first minute decides the next twenty. A customer who opens angry is carrying two problems: the thing that went wrong, and the feeling that nobody has listened. The second has to be dealt with first, because a person who does not feel heard cannot hear anything you say."}},{"id":"b_l1_def_acknowledgement","type":"definition_card","objectiveId":"CS-01","payload":{"termAr":"الاعتراف","termEn":"Acknowledgement","defAr":"تسمية ما حدث بكلمات العميل، والقول إنك تفهم لماذا يهم، قبل أي شيء عن الأسباب أو الحلول.","defEn":"Naming what happened in the customer's words, and saying you understand why it matters, before saying anything about causes or fixes.","icon":"👂","exampleAr":"«تم خصم المبلغ مرتين ولم يتصل بك أحد، وقد قضيت ساعة في هذا. أفهم لماذا أنت غاضب.»","exampleEn":"“You were charged twice and nobody called you back, and you have spent an hour on this. I can see why you are angry.”"}},{"id":"b_l1_def_establish_facts","type":"definition_card","objectiveId":"CS-01","payload":{"termAr":"تحديد الحقائق","termEn":"Establish the facts","defAr":"الترتيب الصحيح للأسئلة: ما حدث، ومتى، وما فعله العميل حياله بالفعل، وما يريد الآن.","defEn":"The correct order of questions: what happened, when, what the customer has already done about it, and what they now want.","icon":"🔍"}},{"id":"b_l1_def_ownership","type":"definition_card","objectiveId":"CS-01","payload":{"termAr":"الملكية","termEn":"Ownership","defAr":"الشكوى تحمل اسمًا واحدًا حتى تُغلق، وهذا الاسم هو اسمك.","defEn":"The complaint has one name on it until it is closed, and that name is yours.","icon":"📛"}},{"id":"b_l1_def_agreed_next_step","type":"definition_card","objectiveId":"CS-01","payload":{"termAr":"الخطوة التالية المتفق عليها","termEn":"Agreed next step","defAr":"إجراء محدد، وقت محدد، وطريقة محددة يعرف بها العميل أنه تم.","defEn":"A specific action, a specific time, and a specific way the customer will know it happened.","icon":"✅","exampleAr":"«سأرفع طلب الاسترداد الآن؛ سيصل إلى بطاقتك خلال خمسة أيام عمل؛ ستتلقى تأكيدًا عبر البريد الإلكتروني اليوم.»","exampleEn":"“I will raise the refund now; it reaches your card within five working days; you will get a confirmation by email today.”"}},{"id":"b_l1_compare_acknowledgement","type":"compare_table","objectiveId":"CS-01","payload":{"captionAr":"ما الاعتراف به وما ليس اعترافًا","captionEn":"What acknowledgement is and is not","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"اعتراف","labelEn":"Acknowledgement"},{"labelAr":"ليس اعترافًا","labelEn":"Not acknowledgement"}],"rows":[[{"textAr":"التركيز","textEn":"Focus"},{"textAr":"تجربة العميل","textEn":"The customer's experience"},{"textAr":"منظمة أو سياسة","textEn":"The organisation or policy"}],[{"textAr":"اللغة","textEn":"Language"},{"textAr":"«أرى لماذا أنت غاضب»","textEn":"“I can see why you are angry”"},{"textAr":"«آسف لأنك تشعر بهذه الطريقة»","textEn":"“I'm sorry you feel that way”"}],[{"textAr":"النتيجة","textEn":"Outcome"},{"textAr":"يخفض درجة الغضب","textEn":"Lowers anger"},{"textAr":"يزيد الغضب","textEn":"Increases anger"}]]}},{"id":"b_l1_flow_stages","type":"process_flow","objectiveId":"CS-01","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"الاعتراف","labelEn":"Acknowledge","detailAr":"قل ما حدث بكلمات العميل.","detailEn":"Say what happened in the customer's words."},{"id":"s2","labelAr":"خفض التوتر","labelEn":"De-escalate","detailAr":"قل إنك تفهم لماذا يهم.","detailEn":"Say you understand why it matters."},{"id":"s3","labelAr":"تحديد الحقائق","labelEn":"Establish facts","detailAr":"اسأل: ما حدث، ومتى، وما فعله العميل بالفعل، وما يريد الآن.","detailEn":"Ask: what happened, when, what the customer has already done, and what they now want."},{"id":"s4","labelAr":"التحقق من السجل","labelEn":"Check the record","detailAr":"افحص السجل أثناء تواجد العميل.","detailEn":"Check the record while the customer is with you."},{"id":"s5","labelAr":"الملكية","labelEn":"Take ownership","detailAr":"كن الاسم الوحيد على الشكوى حتى تُغلق.","detailEn":"Be the only name on the complaint until it is closed."},{"id":"s6","labelAr":"الاتفاق على الخطوة التالية","labelEn":"Agree next step","detailAr":"حدد إجراءً محددًا ووقتًا محددًا.","detailEn":"Specify a specific action and a specific time."},{"id":"s7","labelAr":"الإغلاق","labelEn":"Close","detailAr":"قل كيف سيعرف العميل أن الأمر قد تم.","detailEn":"Say how the customer will know it happened."}]}},{"id":"b_l1_tip_avoid","type":"job_tip","objectiveId":"CS-01","payload":{"mdAr":"**ثلاثة أشياء لا تفعلها أبدًا:**\n- لا تعد بشيء لا يمكنك تحقيقه بنفسك؛ وعد بما يمكنك فعله والوقت الذي ستعود فيه.\n- لا تجادل السياسة؛ اشرحها مرة واحدة، ثم انتقل إلى ما يمكن فعله ضمنها.\n- لا تأخذ الغضب على محمل شخصي، ولا ترد عليه؛ العميل غاضب من الموقف وأنت أول شخص يمكنه تغييره.","mdEn":"**Three things never to do:**\n- Do not promise what you cannot personally make true; promise what you can do and the time by which you will report back.\n- Do not argue the policy; explain it once, then move to what can be done within it.\n- Do not take the anger personally, and do not match it; the customer is angry at a situation and you are the first person who could change it."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"CS-01","payload":{"itemsAr":["الشكوى فرصة وليست هجومًا: العميل الذي يشكو يمنحك فرصة لتصحيح الأمر.","الاعتراف يخفض التوتر قبل تحديد الحقائق.","الملكية تعني اسمًا واحدًا على الشكوى حتى تُغلق.","الخطوة التالية المتفق عليها تمنع تكرار الشكوى."],"itemsEn":["A complaint is an opportunity, not an attack: the customer who complains is giving you a chance to put it right.","Acknowledgement lowers the temperature before facts are established.","Ownership means one name on the complaint until it is closed.","An agreed next step prevents the complaint from becoming a repeat complaint."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"CS-01","payload":{"textAr":"طبّق ما قرأت","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_acknowledge","type":"worked_example","objectiveId":"CS-01","payload":{"promptAr":"تصل مكالمة من عميل يقول: «طلبت المنتج منذ أسبوعين ولم يصل، واتصلت ثلاث مرات ولم يرد أحد.» كيف تبدأ الرد؟","promptEn":"A call arrives from a customer saying: “I ordered the product two weeks ago and it has not arrived. I have called three times and nobody has called me back.” How do you start?","steps":[{"showAr":"قل ما حدث بكلماته.","showEn":"Say what happened in their words.","whyAr":"هذا يثبت أنك سمعت ما قاله، وليس ما توقعت أن يقوله.","whyEn":"This proves you heard what they said, not what you expected them to say."},{"showAr":"قل إنك تفهم لماذا يهم.","showEn":"Say you understand why it matters.","whyAr":"العميل يحتاج أن يعرف أنك ترى الأمر من منظوره قبل أن ينتقل إلى الحلول.","whyEn":"The customer needs to know you see it from their perspective before moving to fixes."},{"showAr":"لا تعتذر بعد، ولا تعد بشيء.","showEn":"Do not apologise yet, and do not promise anything.","whyAr":"الاعتذار الآن يبدو فارغًا، والوعد الآن قد لا يتحقق.","whyEn":"An apology now sounds hollow, and a promise now may not be deliverable."}],"answerAr":"«لقد طلبت منذ أسبوعين ولم يصل، واتصلت ثلاث مرات ولم يتصل بك أحد. أفهم لماذا أنت محبط.»","answerEn":"“You ordered two weeks ago and it has not arrived, and you have called three times and nobody called you back. I can see why you are frustrated.”"}},{"id":"b_l2_scenario_ownership","type":"scenario","objectiveId":"CS-01","payload":{"situationAr":"عميل يتصل ليقول إن طلبه لم يصل بعد ثلاثة أسابيع. لقد اتصلت بقسم الشحن وهم يقولون إن الطلب وصل منذ عشرة أيام. الموعد النهائي لإغلاق الشكوى اليوم.","situationEn":"A customer calls to say their order has not arrived after three weeks. You call the shipping department and they say the order was delivered ten days ago. The complaint must be closed today.","decisions":[{"id":"d1","optionAr":"قل للعميل إن الشحن يؤكد الوصول وأغلق المكالمة.","optionEn":"Tell the customer shipping confirms delivery and close the call.","consequenceAr":"العميل لا يشعر بأنه سمع، والشكوى ستتكرر.","consequenceEn":"The customer does not feel heard, and the complaint will repeat.","isBest":false},{"id":"d2","optionAr":"اطلب من العميل التحقق من العنوان، ثم أغلق.","optionEn":"Ask the customer to check the address, then close.","consequenceAr":"العميل يشعر بأنه تُرك وحده لحل المشكلة.","consequenceEn":"The customer feels left to solve the problem alone.","isBest":false},{"id":"d3","optionAr":"تواصل مع قسم الشحن لتحصل على إثبات التسليم، ثم اتصل بالعميل لتخبره بالنتيجة.","optionEn":"Contact shipping for proof of delivery, then call the customer back with the result.","consequenceAr":"العميل يعرف أن الشكوى تحمل اسمًا واحدًا وأنه سيُسمع منه اليوم. الملكية محفوظة.","consequenceEn":"The customer knows the complaint has one name and they will hear back today. Ownership is preserved.","isBest":true}]}},{"id":"b_l2_sort_facts","type":"sort_buckets","objectiveId":"CS-01","payload":{"buckets":[{"id":"customer","labelAr":"ما قاله العميل","labelEn":"What the customer said"},{"id":"record","labelAr":"ما يظهره السجل","labelEn":"What the record shows"}],"cards":[{"id":"c1","textAr":"«لم يصل طلبي بعد ثلاثة أسابيع.»","textEn":"“My order has not arrived after three weeks.”","bucketId":"customer","whyAr":"هذا ما قاله العميل، وليس بالضرورة ما حدث.","whyEn":"This is what the customer said, not necessarily what happened."},{"id":"c2","textAr":"«اتصلت ثلاث مرات ولم يرد أحد.»","textEn":"“I have called three times and nobody called me back.”","bucketId":"customer","whyAr":"هذا ما يشعر به العميل، وليس بالضرورة ما حدث.","whyEn":"This is how the customer feels, not necessarily what happened."},{"id":"c3","textAr":"طلب رقم 1428 أُرسل في 5 مايو.","textEn":"Order 1428 was dispatched on 5 May.","bucketId":"record","whyAr":"هذا ما يظهره السجل، وليس بالضرورة ما تلقاه العميل.","whyEn":"This is what the record shows, not necessarily what the customer received."},{"id":"c4","textAr":"إثبات التسليم موقع في 15 مايو.","textEn":"Proof of delivery signed on 15 May.","bucketId":"record","whyAr":"هذا ما يظهره السجل، وليس بالضرورة ما تلقاه العميل.","whyEn":"This is what the record shows, not necessarily what the customer received."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"CS-01","payload":{"itemRef":"CS-01-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"CS-01","payload":{"itemRef":"CS-01-KC-02"}}]}},"items":[{"key":"CS-01-KC-01","objectiveId":"CS-01","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"عميل يقول: «طلبت المنتج منذ أسبوع ولم يصل، واتصلت مرتين ولم يرد أحد.» ما أفضل رد أولي؟","stemEn":"A customer says: “I ordered the product a week ago and it has not arrived. I have called twice and nobody has called me back.” What is the best first response?","rationaleAr":"الاعتراف يثبت أنك سمعت العميل، وهو الخطوة الأولى لخفض التوتر.","rationaleEn":"Acknowledgement proves you heard the customer, which is the first step to lowering the temperature.","options":[{"textAr":"«آسف على الإزعاج. سأتحقق من الطلب الآن.»","textEn":"“I apologise for the inconvenience. I will check the order now.”","isCorrect":false,"feedbackAr":"هذا اعتذار قبل تحديد الحقائق، وقد يبدو فارغًا.","feedbackEn":"This is an apology before facts are established, and may sound hollow."},{"textAr":"«لقد طلبت منذ أسبوع ولم يصل، واتصلت مرتين ولم يتصل بك أحد. أفهم لماذا أنت محبط.»","textEn":"“You ordered a week ago and it has not arrived, and you have called twice and nobody has called you back. I can see why you are frustrated.”","isCorrect":true,"feedbackAr":"هذا اعتراف يثبت أنك سمعت العميل ويخفض التوتر.","feedbackEn":"This is acknowledgement, proving you heard the customer and lowering the temperature."},{"textAr":"«سياسة الشركة تقضي بالرد خلال 48 ساعة.»","textEn":"“The company policy is to respond within 48 hours.”","isCorrect":false,"feedbackAr":"هذا دفاع عن السياسة قبل خفض التوتر، وقد يزيد الغضب.","feedbackEn":"This is a defence of policy before de-escalation, and may increase anger."},{"textAr":"«هل أنت متأكد أنك أدخلت العنوان الصحيح؟»","textEn":"“Are you sure you entered the correct address?”","isCorrect":false,"feedbackAr":"هذا سؤال يفترض خطأ العميل قبل تحديد الحقائق.","feedbackEn":"This is a question that assumes the customer is wrong before facts are established."}]},{"key":"CS-01-KC-02","objectiveId":"CS-01","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"أي من هذه الخطوات جزء من «الخطوة التالية المتفق عليها»؟","stemEn":"Which of these steps are part of an “agreed next step”?","rationaleAr":"الخطوة التالية المتفق عليها تحتاج إجراءً محددًا ووقتًا محددًا وطريقة محددة.","rationaleEn":"An agreed next step needs a specific action, a specific time, and a specific way the customer will know.","options":[{"textAr":"«سأرفع طلب الاسترداد الآن.»","textEn":"“I will raise the refund request now.”","isCorrect":true,"feedbackAr":"هذا إجراء محدد.","feedbackEn":"This is a specific action."},{"textAr":"«سيصل إلى بطاقتك خلال خمسة أيام عمل.»","textEn":"“It will reach your card within five working days.”","isCorrect":true,"feedbackAr":"هذا وقت محدد.","feedbackEn":"This is a specific time."},{"textAr":"«ستتلقى تأكيدًا عبر البريد الإلكتروني اليوم.»","textEn":"“You will get a confirmation by email today.”","isCorrect":true,"feedbackAr":"هذه طريقة محددة يعرف بها العميل أن الأمر قد تم.","feedbackEn":"This is a specific way the customer will know it happened."},{"textAr":"«سأرى ما يمكنني فعله.»","textEn":"“I will see what I can do.”","isCorrect":false,"feedbackAr":"هذا وعد غامض، وليس خطوة محددة.","feedbackEn":"This is a vague promise, not a specific step."}]}]},{"lesson":{"slug":"writing-a-shift-handover","titleAr":"كتابة تسليم وردية العمل","titleEn":"Writing a shift handover","estMinutes":30,"bilingual":true,"levels":["L1","L2"],"objectives":["OPS-01"],"conceptsIntroduced":["handover","urgent_item","fact_guess","commitment"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"OPS-01","payload":{"textAr":"ما تسليم الورديّة؟","textEn":"What a handover is","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"OPS-01","payload":{"mdAr":"تسليم الورديّة هو اللحظة التي ينتقل فيها العمل دون السياق. الشخص المغادر يعرف لماذا لم يُكتمل التذكرة، وأي عميل سيردّ الاتصال، وما الذي جُرِّب بالفعل. الشخص القادم لا يعرف شيئًا من ذلك. كل ما لم يُكتب في نهاية الورديّة يُفقد عمليًا.\n\nالمعيار الوحيد لتسليم الورديّة هو: **هل يستطيع الشخص التالي التصرف بناءً عليه دون الاتصال بك؟** إذا احتاجوا إلى الاتصال أو التخمين، فقد فشل التسليم، مهما كان طويلًا. صفحة كاملة من السرد الذي يخفي العنصر العاجل أسوأ من ثلاث أسطر دقيقة.","mdEn":"A handover is the moment work changes hands while context does not. The person leaving knows why a ticket is half-done, which customer is about to call back, and what was already tried. The person arriving knows none of it. Whatever is not written down at the end of a shift is, for practical purposes, lost.\n\nThe only test of a handover is: **can the next person act on it without contacting you?** If they would have to call, message, or guess, the handover failed, however long it was. A page of narrative that buries the one urgent item is a worse handover than three precise lines."}},{"id":"b_l1_def_handover","type":"definition_card","objectiveId":"OPS-01","payload":{"termAr":"تسليم الورديّة","termEn":"Handover","defAr":"مستند قصير يُنقل فيه العمل المفتوح والسياق إلى الشخص التالي في الورديّة، مكتوب بحيث يمكنهم التصرف دون الاتصال بالشخص المغادر.","defEn":"A short document that transfers open work and context to the next person on shift, written so they can act without contacting the person leaving.","icon":"✏️","exampleAr":"مثال تدريبي: تذكرة دعم رقم 421: العميل طلب استردادًا، تمت الموافقة ولكن لم يُرسل بعد. أرسل قبل الساعة 14:00.","exampleEn":"Training example: Support ticket #421: Customer requested refund, approved but not sent. Send by 14:00."}},{"id":"b_l1_def_urgent_item","type":"definition_card","objectiveId":"OPS-01","payload":{"termAr":"العنصر العاجل","termEn":"Urgent item","defAr":"عنصر في تسليم الورديّة يحتاج إلى إجراء قبل نهاية الورديّة التالية، ويُشار إليه بوضوح في بداية التسليم.","defEn":"An item in a handover that requires action before the end of the next shift, marked clearly at the top of the handover.","icon":"⏰"}},{"id":"b_l1_def_fact_guess","type":"definition_card","objectiveId":"OPS-01","payload":{"termAr":"الحقيقة / التخمين","termEn":"Fact / Guess","defAr":"الحقيقة هي شيء يمكن التحقق منه من السجل أو النظام. التخمين هو تفسير أو رأي، ويجب تسميته بوضوح حتى لا يُعامل كحقيقة.","defEn":"A fact is something verifiable from the record or system. A guess is an interpretation or opinion, and must be labelled clearly so it is not treated as fact.","icon":"🔍"}},{"id":"b_l1_def_commitment","type":"definition_card","objectiveId":"OPS-01","payload":{"termAr":"التزام","termEn":"Commitment","defAr":"وعد تم تقديمه لعميل أو زميل أو مدير، مثل معاودة الاتصال أو التحديث بحلول وقت معين. الالتزامات تنتقل مع العمل، وليس مع الشخص.","defEn":"A promise made to a customer, colleague, or manager, such as a callback or an update by a certain time. Commitments travel with the work, not the person.","icon":"🤝"}},{"id":"b_l1_compare_handover","type":"compare_table","objectiveId":"OPS-01","payload":{"captionAr":"تسليم جيد مقابل تسليم سيئ","captionEn":"Good handover vs. bad handover","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"تسليم جيد","labelEn":"Good handover"},{"labelAr":"تسليم سيئ","labelEn":"Bad handover"}],"rows":[[{"textAr":"العنصر العاجل","textEn":"Urgent item"},{"textAr":"يُذكر أولاً ويُشار إليه بوضوح.","textEn":"Mentioned first and clearly marked."},{"textAr":"يُدفن في السرد أو يُذكر في النهاية.","textEn":"Buried in narrative or mentioned last."}],[{"textAr":"الحالة الحالية","textEn":"Current status"},{"textAr":"حالة محددة: \"في انتظار رد المورد على البريد الإلكتروني الصادر في الساعة 15:22\".","textEn":"Specific state: \"Waiting for supplier reply to email sent at 15:22\"."},{"textAr":"حالة غامضة: \"قيد التنفيذ\"، \"قيد الانتظار\".","textEn":"Vague state: \"In progress\", \"Pending\"."}],[{"textAr":"ما تم فعله","textEn":"What was done"},{"textAr":"يُذكر ما تم تجربته وفشل، مثل \"جرّبت إعادة التشغيل ولكن الخطأ استمر\".","textEn":"Lists what was tried and failed, e.g., \"Tried restarting but error persisted\"."},{"textAr":"لا يذكر المحاولات السابقة.","textEn":"Omits previous attempts."}],[{"textAr":"الإجراء التالي","textEn":"Next action"},{"textAr":"إجراء محدد مع وقت: \"اتصل بالعميل قبل الساعة 10:00 لتأكيد الاستلام\".","textEn":"Specific action with time: \"Call customer by 10:00 to confirm receipt\"."},{"textAr":"لا يذكر الإجراء أو الوقت.","textEn":"No action or time mentioned."}],[{"textAr":"الالتزامات","textEn":"Commitments"},{"textAr":"يُذكر بوضوح: \"وعدت العميل بمعاودة الاتصال قبل الظهر\".","textEn":"Clearly stated: \"Promised customer a callback by noon\"."},{"textAr":"يُترك خارجًا لأنه كان غير رسمي.","textEn":"Omitted because it felt informal."}]]}},{"id":"b_l1_flow_questions","type":"process_flow","objectiveId":"OPS-01","payload":{"steps":[{"id":"q1","labelAr":"ما هذا؟","labelEn":"What is it?","detailAr":"تحديد واحد للبحث عنه: رقم التذكرة، العميل، المهمة.","detailEn":"One-line identifier to find it: ticket number, customer, job."},{"id":"q2","labelAr":"أين يقف؟","labelEn":"Where does it stand?","detailAr":"الحالة الحالية كحقيقة، وليس شعورًا.","detailEn":"Current state as a fact, not a feeling."},{"id":"q3","labelAr":"ما الذي تم فعله بالفعل؟","labelEn":"What has already been done?","detailAr":"خاصة ما تم تجربته ولم ينجح.","detailEn":"Especially what was tried and did not work."},{"id":"q4","labelAr":"ما التالي، ومتى؟","labelEn":"What happens next, and by when?","detailAr":"إجراء محدد مع وقت.","detailEn":"Specific action with a time attached."}],"interactive":false}},{"id":"b_l1_tip_urgent","type":"job_tip","objectiveId":"OPS-01","payload":{"mdAr":"**ابدأ بما هو عاجل.** رتّب العناصر حسب موعد الإجراء، وليس حسب وقت الوصول أو الاهتمام. أي شيء له موعد نهائي خلال الورديّة التالية يأتي أولاً ويُشار إليه بوضوح. التسليم الذي يُقرأ من الأعلى لا ينبغي أن يفاجئ القارئ في الأسفل.","mdEn":"**Lead with what is urgent.** Order items by when they need action, not by when they arrived or how interesting they were. Anything with a deadline inside the next shift goes first and is marked clearly. A handover read from the top should never surprise the reader at the bottom."}},{"id":"b_l1_tip_fact_guess","type":"job_tip","objectiveId":"OPS-01","payload":{"mdAr":"**افصل بين الحقائق والتخمينات.** \"فشل الدفع مرتين\" هو حقيقة. \"أعتقد أن البطاقة منتهية الصلاحية\" هو تخمين، ويجب تسميته بوضوح، وإلا سيتصرف الشخص التالي كما لو كان حقيقة.","mdEn":"**Separate facts from guesses.** \"The payment failed twice\" is a fact. \"I think the card is expired\" is a guess, and it has to be labelled as one, or the next person will act on it as if it were true."}},{"id":"b_l1_tip_commitment","type":"job_tip","objectiveId":"OPS-01","payload":{"mdAr":"**الالتزامات تنتقل مع العمل.** إذا وعدت عميلاً أو زميلاً أو مديرًا بشيء — معاودة الاتصال، استرداد، تحديث بحلول وقت معين — فهذا الوعد الآن على عاتق الشخص التالي، ويجب أن يذكر التسليم ذلك بوضوح: من وُعد بماذا، ومتى.","mdEn":"**Commitments travel with the work.** If you promised a customer, colleague, or manager something — a callback, a refund, an update by a certain time — that promise is now the next person's, and the handover must say so in words: who was promised what, and by when."}},{"id":"b_l1_tip_location","type":"job_tip","objectiveId":"OPS-01","payload":{"mdAr":"**اكتبه حيث يعيش العمل.** التسليم على ورقة، رسالة خاصة أو ملاحظة شخصية لا يمكن العثور عليه من قبل من يغطي الورديّة التالية. اكتبه في السجل المشترك — التذكرة، السجل، القناة المتفق عليها — حتى يبقى بعد مغادرة من كتبه.","mdEn":"**Write it where the work lives.** A handover on a scrap of paper, a private message, or a personal note cannot be found by whoever covers the shift after next. Write it in the shared record — the ticket, the log, the team channel the team agreed on — so it survives the person who wrote it."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"OPS-01","payload":{"itemsAr":["تسليم الورديّة هو مستند قصير يجيب على أربعة أسئلة لكل عنصر مفتوح: ما هذا؟ أين يقف؟ ما الذي تم فعله؟ ما التالي ومتى؟","العناصر العاجلة تأتي أولاً وتُشار إليها بوضوح.","افصل بين الحقائق والتخمينات، وسمِّ التخمينات بوضوح.","الالتزامات تنتقل مع العمل، وليس مع الشخص، ويجب ذكرها بوضوح.","اكتب التسليم في السجل المشترك حتى يمكن العثور عليه لاحقًا."],"itemsEn":["A handover is a short document that answers four questions for every open item: What is it? Where does it stand? What has been done? What happens next, and by when?","Urgent items go first and are clearly marked.","Separate facts from guesses, and label guesses clearly.","Commitments travel with the work, not the person, and must be stated clearly.","Write the handover in the shared record so it can be found later."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"OPS-01","payload":{"textAr":"طبّق ما قرأت","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_example","type":"worked_example","objectiveId":"OPS-01","payload":{"promptAr":"أنت تغادر الورديّة، ولديك ثلاث مهام مفتوحة:\n\n1. تذكرة دعم رقم 312: عميل أبلغ عن خطأ في الفاتورة، وأرسلت بريدًا إلكترونيًا إلى المحاسبة في الساعة 16:10 ولم يردوا بعد.\n2. طلب استرداد رقم 789: تمت الموافقة ولكن لم يُرسل بعد، والعميل يتوقع استلامه اليوم.\n3. تقرير أسبوعي: يجب إرساله بحلول الساعة 17:00، ولم يبدأ بعد.\n\nاكتب تسليم الورديّة.","promptEn":"You are leaving shift, and you have three open items:\n\n1. Support ticket #312: Customer reported a billing error. You emailed Accounting at 16:10 and have not heard back.\n2. Refund request #789: Approved but not sent. Customer expects it today.\n3. Weekly report: Due by 17:00, not started yet.\n\nWrite the handover.","steps":[{"showAr":"**العنصر العاجل أولاً:** طلب الاسترداد رقم 789 يأتي أولاً لأنه يجب إرساله اليوم.","showEn":"**Lead with the urgent item:** Refund request #789 goes first because it must be sent today.","whyAr":"العميل يتوقع الاستلام اليوم، والتأخير يعني وعدًا مكسورًا.","whyEn":"The customer expects it today, and delay means a broken promise."},{"showAr":"**الحالة الحالية كحقيقة:** \"في انتظار رد المحاسبة\" ليس حالة، بل \"أرسلت بريدًا إلكترونيًا في الساعة 16:10 ولم يردوا بعد\".","showEn":"**Current state as fact:** \"Waiting for Accounting\" is not a state. \"Emailed at 16:10, no reply yet\" is.","whyAr":"الحالة الغامضة تجعل الشخص التالي يخمن ما يجب فعله.","whyEn":"A vague state makes the next person guess what to do."},{"showAr":"**ما تم فعله:** اذكر ما تم تجربته وفشل، مثل \"جرّبت إعادة التشغيل ولكن الخطأ استمر\".","showEn":"**What was done:** List what was tried and failed, e.g., \"Tried restarting but error persisted\".","whyAr":"بدون ذلك، قد يكرر الشخص التالي المحاولة الفاشلة.","whyEn":"Without it, the next person may repeat the failed attempt."},{"showAr":"**الإجراء التالي مع وقت:** \"أرسل الاسترداد قبل نهاية الورديّة\" وليس \"أرسل الاسترداد قريبًا\".","showEn":"**Next action with time:** \"Send refund before end of shift\" not \"Send refund soon\".","whyAr":"الوقت المحدد يمنع التأخير.","whyEn":"A specific time prevents delay."},{"showAr":"**الالتزامات:** إذا وعدت العميل بمعاودة الاتصال، فاكتب ذلك حتى يعرف الشخص التالي.","showEn":"**Commitments:** If you promised the customer a callback, write it so the next person knows.","whyAr":"الالتزام ينتقل مع العمل، وليس مع الشخص.","whyEn":"The commitment travels with the work, not the person."}],"answerAr":"**تسليم الورديّة:**\n\n1. **طلب الاسترداد رقم 789** (عاجل): تمت الموافقة ولكن لم يُرسل بعد. العميل يتوقع استلامه اليوم. أرسل قبل نهاية الورديّة.\n2. تذكرة الدعم رقم 312: أبلغ العميل عن خطأ في الفاتورة. أرسلت بريدًا إلكترونيًا إلى المحاسبة في الساعة 16:10 ولم يردوا بعد. اتبع معهم قبل الساعة 10:00 غدًا.\n3. التقرير الأسبوعي: يجب إرساله بحلول الساعة 17:00، ولم يبدأ بعد. أكمله وأرسله قبل الموعد النهائي.","answerEn":"**Handover:**\n\n1. **Refund request #789** (urgent): Approved but not sent. Customer expects it today. Send before end of shift.\n2. Support ticket #312: Customer reported billing error. Emailed Accounting at 16:10, no reply yet. Follow up by 10:00 tomorrow.\n3. Weekly report: Due by 17:00, not started. Complete and send before deadline."}},{"id":"b_l2_scenario_missing_commitment","type":"scenario","objectiveId":"OPS-01","payload":{"situationAr":"أنت تغادر الورديّة، ولديك تذكرة دعم مفتوحة: العميل أبلغ عن مشكلة في الشحن، وأرسلت بريدًا إلكترونيًا إلى الشحن في الساعة 15:30 ولم يردوا بعد. وعدت العميل بمعاودة الاتصال بحلول الساعة 16:00 لتحديثه، ولكن الساعة الآن 15:55 ولم تتلق ردًا بعد.","situationEn":"You are leaving shift, and you have one open support ticket: Customer reported a shipping issue. You emailed Shipping at 15:30 and have not heard back. You promised the customer a callback by 16:00 with an update, but it is now 15:55 and you have no reply yet.","decisions":[{"id":"d1","optionAr":"اكتب في التسليم: \"التذكرة رقم 123: في انتظار رد الشحن. اتبع معهم غدًا.\"","optionEn":"Write in the handover: \"Ticket #123: Waiting for Shipping reply. Follow up tomorrow.\"","consequenceAr":"الشخص التالي لا يعرف عن الوعد بمعاودة الاتصال، والعميل لن يتلقى تحديثًا بحلول الساعة 16:00. الوعد يُعتبر مكسورًا.","consequenceEn":"The next person does not know about the callback promise, and the customer will not receive an update by 16:00. The promise is treated as broken.","isBest":false},{"id":"d2","optionAr":"اتصل بالعميل الآن وقل إنك لم تتلق ردًا بعد، ثم اكتب في التسليم: \"التذكرة رقم 123: وعدت العميل بمعاودة الاتصال بحلول الساعة 16:00. أرسلت بريدًا إلكترونيًا إلى الشحن في الساعة 15:30 ولم يردوا بعد. اتصل بالعميل قبل الساعة 16:00 لتحديثه.\"","optionEn":"Call the customer now and say you have not received a reply yet, then write in the handover: \"Ticket #123: Promised customer callback by 16:00. Emailed Shipping at 15:30, no reply yet. Call customer by 16:00 with update.\"","consequenceAr":"العميل يتلقى تحديثًا فوريًا، والالتزام يُنقل بوضوح إلى الشخص التالي. الوعد يُحفظ.","consequenceEn":"The customer receives an immediate update, and the commitment is clearly transferred to the next person. The promise is kept.","isBest":true},{"id":"d3","optionAr":"اكتب في التسليم: \"التذكرة رقم 123: في انتظار رد الشحن. اتصل بالعميل إذا لم يردوا بحلول الساعة 16:00.\"","optionEn":"Write in the handover: \"Ticket #123: Waiting for Shipping reply. Call customer if they do not reply by 16:00.\"","consequenceAr":"الالتزام بمعاودة الاتصال بحلول الساعة 16:00 غير واضح، وقد يفوته الشخص التالي. الوعد قد يُكسر.","consequenceEn":"The commitment to call back by 16:00 is not clear, and the next person may miss it. The promise may be broken.","isBest":false}]}},{"id":"b_l2_scenario_vague_status","type":"scenario","objectiveId":"OPS-01","payload":{"situationAr":"أنت تغادر الورديّة، ولديك تذكرة دعم مفتوحة: العميل طلب استردادًا، وأرسلت الطلب إلى المحاسبة. تكتب في التسليم: \"التذكرة رقم 456: قيد الانتظار.\"","situationEn":"You are leaving shift, and you have one open support ticket: Customer requested a refund, and you sent the request to Accounting. You write in the handover: \"Ticket #456: Pending.\"","decisions":[{"id":"d1","optionAr":"اترك التسليم كما هو.","optionEn":"Leave the handover as is.","consequenceAr":"الشخص التالي لا يعرف ما يعني \"قيد الانتظار\"، وقد يفترض أن المحاسبة ستتصرف قريبًا. قد ينتظر دون متابعة، مما يؤخر الاسترداد.","consequenceEn":"The next person does not know what \"pending\" means, and may assume Accounting will act soon. They may wait without following up, delaying the refund.","isBest":false},{"id":"d2","optionAr":"اكتب: \"التذكرة رقم 456: أرسلت الطلب إلى المحاسبة في الساعة 14:45 ولم يردوا بعد. اتبع معهم قبل الساعة 10:00 غدًا.\"","optionEn":"Write: \"Ticket #456: Sent request to Accounting at 14:45, no reply yet. Follow up by 10:00 tomorrow.\"","consequenceAr":"الشخص التالي يعرف بالضبط ما حدث ومتى يتصرف. الاسترداد يُسرع.","consequenceEn":"The next person knows exactly what happened and when to act. The refund is expedited.","isBest":true},{"id":"d3","optionAr":"اكتب: \"التذكرة رقم 456: قيد الانتظار. المحاسبة بطيئة دائمًا.\"","optionEn":"Write: \"Ticket #456: Pending. Accounting is always slow.\"","consequenceAr":"الحالة ليست حقيقة، والتخمين غير مسمّى. قد يتصرف الشخص التالي بناءً على التخمين، وليس على الحقائق.","consequenceEn":"The state is not a fact, and the guess is unlabelled. The next person may act on the guess, not the facts.","isBest":false}]}},{"id":"b_l2_sort_fact_guess","type":"sort_buckets","objectiveId":"OPS-01","payload":{"buckets":[{"id":"fact","labelAr":"حقيقة","labelEn":"Fact"},{"id":"guess","labelAr":"تخمين","labelEn":"Guess"}],"cards":[{"id":"c1","textAr":"فشل الدفع مرتين.","textEn":"The payment failed twice.","bucketId":"fact","whyAr":"يمكن التحقق من ذلك من السجل.","whyEn":"Verifiable from the record."},{"id":"c2","textAr":"أعتقد أن البطاقة منتهية الصلاحية.","textEn":"I think the card is expired.","bucketId":"guess","whyAr":"ليس مؤكدًا، ويجب تسميته بوضوح.","whyEn":"Not certain, and must be labelled clearly."},{"id":"c3","textAr":"أرسلت بريدًا إلكترونيًا إلى المورد في الساعة 15:22 ولم يردوا بعد.","textEn":"Emailed the supplier at 15:22, no reply yet.","bucketId":"fact","whyAr":"يمكن التحقق من ذلك من سجل البريد الإلكتروني.","whyEn":"Verifiable from the email log."},{"id":"c4","textAr":"ربما يكون المورد في إجازة.","textEn":"Maybe the supplier is on holiday.","bucketId":"guess","whyAr":"ليس مؤكدًا، ويجب تسميته بوضوح.","whyEn":"Not certain, and must be labelled clearly."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"OPS-01","payload":{"itemRef":"OPS-01-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"OPS-01","payload":{"itemRef":"OPS-01-KC-02"}}]}},"items":[{"key":"OPS-01-KC-01","objectiveId":"OPS-01","type":"MCQ_SINGLE","bloom":"RECALL","formative":true,"stemAr":"ما المعيار الوحيد لتسليم الورديّة الجيد؟","stemEn":"What is the only test of a good handover?","rationaleAr":"المعيار الوحيد هو ما إذا كان الشخص التالي يستطيع التصرف دون الاتصال بالشخص المغادر.","rationaleEn":"The only test is whether the next person can act without contacting the person leaving.","options":[{"textAr":"أن يكون طويلًا ومفصلًا.","textEn":"That it is long and detailed.","isCorrect":false,"feedbackAr":"الطول ليس المعيار. التسليم القصير الذي يمكن التصرف بناءً عليه أفضل من الطويل الذي لا يمكن.","feedbackEn":"Length is not the test. A short handover that can be acted on is better than a long one that cannot."},{"textAr":"أن يكون مكتوبًا بخط اليد.","textEn":"That it is handwritten.","isCorrect":false,"feedbackAr":"المكان مهم، وليس الشكل.","feedbackEn":"The location matters, not the format."},{"textAr":"أن يستطيع الشخص التالي التصرف بناءً عليه دون الاتصال بك.","textEn":"That the next person can act on it without contacting you.","isCorrect":true,"feedbackAr":"هذا هو المعيار الوحيد.","feedbackEn":"This is the only test."},{"textAr":"أن يحتوي على كل التفاصيل التي تعرفها.","textEn":"That it contains every detail you know.","isCorrect":false,"feedbackAr":"التفاصيل الزائدة تدفن ما هو مهم.","feedbackEn":"Too much detail buries what matters."}]},{"key":"OPS-01-KC-02","objectiveId":"OPS-01","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"أي من هذه يجب أن يُذكر بوضوح في تسليم الورديّة؟","stemEn":"Which of these must be clearly stated in a handover?","rationaleAr":"العناصر العاجلة، الحقائق مقابل التخمينات، والالتزامات يجب ذكرها بوضوح.","rationaleEn":"Urgent items, facts vs. guesses, and commitments must be clearly stated.","options":[{"textAr":"العنصر الذي له موعد نهائي خلال الورديّة التالية.","textEn":"The item with a deadline inside the next shift.","isCorrect":true,"feedbackAr":"العناصر العاجلة تأتي أولاً وتُشار إليها بوضوح.","feedbackEn":"Urgent items go first and are clearly marked."},{"textAr":"ما تعتقد أنه قد يكون المشكلة.","textEn":"What you think might be the problem.","isCorrect":true,"feedbackAr":"التخمينات يجب تسميتها بوضوح، وإلا قد يُعامل الشخص التالي كحقيقة.","feedbackEn":"Guesses must be labelled clearly, or the next person may treat them as fact."},{"textAr":"الوعد الذي قطعته لعميل أو زميل.","textEn":"The promise you made to a customer or colleague.","isCorrect":true,"feedbackAr":"الالتزامات تنتقل مع العمل، ويجب ذكرها بوضوح.","feedbackEn":"Commitments travel with the work and must be stated clearly."},{"textAr":"كل التفاصيل التي تعرفها عن التذكرة.","textEn":"Every detail you know about the ticket.","isCorrect":false,"feedbackAr":"التفاصيل الزائدة تدفن ما هو مهم.","feedbackEn":"Too much detail buries what matters."}]},{"key":"OPS-01-KC-03","objectiveId":"OPS-01","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"اكتشفت أن تسليم الورديّة الذي كتبته بالأمس لم يذكر وعدًا قطعته لعميل بمعاودة الاتصال اليوم. ماذا تفعل الآن؟","stemEn":"You discover that yesterday's handover you wrote omitted a promise you made to a customer for a callback today. What do you do now?","rationaleAr":"الالتزامات تنتقل مع العمل، ويجب ذكرها بوضوح حتى لو تم نسيانها.","rationaleEn":"Commitments travel with the work, and must be stated clearly even if they were missed.","options":[{"textAr":"لا تفعل شيئًا. الوعد كان بالأمس، والشخص التالي لم يذكره.","textEn":"Do nothing. The promise was yesterday, and the next person did not mention it.","isCorrect":false,"feedbackAr":"الالتزام لا يختفي مع الورديّة. العميل يتوقع معاودة الاتصال.","feedbackEn":"The commitment does not disappear with the shift. The customer expects the callback."},{"textAr":"اتصل بالعميل الآن وأعترف بالخطأ، ثم اكتب في السجل المشترك أن الوعد لم يُذكر في التسليم.","textEn":"Call the customer now and acknowledge the oversight, then write in the shared record that the promise was omitted from the handover.","isCorrect":true,"feedbackAr":"هذا يحفظ الثقة ويضمن عدم تكرار الخطأ.","feedbackEn":"This preserves trust and ensures the mistake is not repeated."},{"textAr":"اكتب في السجل المشترك أن الوعد كان غير رسمي، لذلك لم يُذكر.","textEn":"Write in the shared record that the promise was informal, so it was not mentioned.","isCorrect":false,"feedbackAr":"الالتزامات الرسمية وغير الرسمية تنتقل مع العمل.","feedbackEn":"Formal and informal commitments travel with the work."},{"textAr":"انتظر حتى يتصل العميل، ثم اعتذر.","textEn":"Wait for the customer to call, then apologise.","isCorrect":false,"feedbackAr":"هذا يكسر الوعد ويضر بالثقة.","feedbackEn":"This breaks the promise and damages trust."}]}]},{"lesson":{"slug":"what-counts-as-personal-data","titleAr":"ما الذي يُعتبر بيانات شخصية؟","titleEn":"What counts as personal data?","estMinutes":30,"bilingual":true,"levels":["L1","L2"],"objectives":["PRV-01"],"conceptsIntroduced":["personal_data","identifiability","sensitive_data","data_subject_request","potential_breach"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"PRV-01","payload":{"textAr":"ما البيانات الشخصية؟","textEn":"What is personal data?","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"PRV-01","payload":{"mdAr":"البيانات الشخصية هي أي معلومة تتعلق بشخص حي محدد أو يمكن تحديده. الاختبار ليس في وجود اسم واضح، بل في إمكانية التعرف على الشخص. الاسم هو بيانات شخصية، وكذلك رقم الموظف، وعنوان البريد الإلكتروني، ورقم الهاتف، والصورة الفوتوغرافية، ولوحة السيارة، ومعرف الجهاز، والعنوان السكني. وكذلك مجموعة من الحقائق العادية التي تبدو غير ضارة، ولكنها معًا تشير إلى شخص واحد: مثل المسمى الوظيفي بالإضافة إلى القسم بالإضافة إلى تاريخ البدء يمكن أن تحدد شخصًا في فريق صغير مثلما تحدد اسمه.","mdEn":"Personal data is any information that relates to an identified or identifiable living person. The test is not whether there's an obvious name, but whether someone could work out who this is about. A name is personal data. So is an employee number, an email address, a phone number, a photograph, a vehicle plate, a device identifier, and a home address. So is a combination of ordinarily harmless facts that, together, point at one person: a job title plus a department plus a start date can identify someone in a small team just as their name would."}},{"id":"b_l1_def_personal_data","type":"definition_card","objectiveId":"PRV-01","payload":{"termAr":"البيانات الشخصية","termEn":"Personal data","defAr":"أي معلومة تتعلق بشخص حي محدد أو يمكن تحديده، سواء كانت مباشرة أو غير مباشرة.","defEn":"Any information relating to an identified or identifiable living person, whether directly or indirectly.","icon":"👤","exampleAr":"مثال تدريبي: عنوان البريد الإلكتروني لمريض في سجلات العيادة.","exampleEn":"Training example: a patient's email address in clinic records."}},{"id":"b_l1_def_identifiability","type":"definition_card","objectiveId":"PRV-01","payload":{"termAr":"قابلية التعرف","termEn":"Identifiability","defAr":"إمكانية الربط بين معلومة وشخص محدد، سواء بمفردها أو مع معلومات أخرى متاحة بشكل معقول.","defEn":"The ability to link information to a specific person, either alone or in combination with other reasonably available information.","icon":"🔍"}},{"id":"b_l1_def_sensitive_data","type":"definition_card","objectiveId":"PRV-01","payload":{"termAr":"البيانات الحساسة","termEn":"Sensitive data","defAr":"بيانات شخصية تتطلب حماية أعلى بسبب المخاطر المحتملة عند الكشف عنها، مثل المعلومات الصحية أو الدينية أو العرقية.","defEn":"Personal data requiring higher protection due to potential risks if disclosed, such as health information, religion, or ethnic origin.","icon":"🔒","exampleAr":"مثال تدريبي: سبب الإجازة المرضية المسجل في ملف الموظف.","exampleEn":"Training example: the reason for sick leave recorded in an employee file."}},{"id":"b_l1_compare_tests","type":"compare_table","objectiveId":"PRV-01","payload":{"captionAr":"اختبار الاسم مقابل اختبار التعرف","captionEn":"Name test vs. identifiability test","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"اختبار الاسم","labelEn":"Name test"},{"labelAr":"اختبار التعرف","labelEn":"Identifiability test"}],"rows":[[{"textAr":"السؤال","textEn":"Question"},{"textAr":"هل يوجد اسم؟","textEn":"Is there a name?"},{"textAr":"هل يمكن لشخص ما معرفة من يتعلق الأمر؟","textEn":"Could someone work out who this is about?"}],[{"textAr":"المثال الإيجابي","textEn":"Positive example"},{"textAr":"«محمد علي»","textEn":"\"Mohamed Ali\""},{"textAr":"«الموظف الجديد في قسم المحاسبة الذي بدأ في 15 يناير»","textEn":"\"The new employee in accounting who started on January 15\""}],[{"textAr":"المثال السلبي","textEn":"Negative example"},{"textAr":"«المريض في الغرفة 3»","textEn":"\"Patient in room 3\""},{"textAr":"«مجموع المبيعات لشهر يناير»","textEn":"\"Total sales for January\""}]]}},{"id":"b_l1_flow_habits","type":"process_flow","objectiveId":"PRV-01","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"الملاحظة","labelEn":"Notice","detailAr":"هل هذه المعلومة تتعلق بشخص؟","detailEn":"Is this information about a person?"},{"id":"s2","labelAr":"التقييم","labelEn":"Assess","detailAr":"هل يمكن التعرف على الشخص؟","detailEn":"Could the person be identified?"},{"id":"s3","labelAr":"التصنيف","labelEn":"Classify","detailAr":"هل هي بيانات حساسة؟","detailEn":"Is it sensitive data?"},{"id":"s4","labelAr":"التصرف","labelEn":"Act","detailAr":"طبق قواعد التعامل المناسبة.","detailEn":"Apply the appropriate handling rules."}]}},{"id":"b_l1_tip_collect","type":"job_tip","objectiveId":"PRV-01","payload":{"mdAr":"اجمع واستخدم فقط ما تحتاجه المهمة. إذا طلب النموذج تاريخ الميلاد ولم يستخدمه العملية أبدًا، فهذا الحقل مسؤولية وليس راحة. وينطبق الشيء نفسه على النسخ: جدول بيانات مُصدَّر «للتأكد فقط» هو نسخة ثانية من البيانات الشخصية التي لا يحميها أحد.","mdEn":"Collect and use only what the task needs. If a form asks for a date of birth and the process never uses it, that field is a liability, not a convenience. The same applies to copying: a spreadsheet exported \"just in case\" is a second copy of personal data that nobody is protecting."}},{"id":"b_l1_tip_share","type":"job_tip","objectiveId":"PRV-01","payload":{"mdAr":"شارك المعلومات على أساس الحاجة إلى المعرفة، عبر القنوات المعتمدة فقط. إرسال تفاصيل العميل إلى زميل لا يحتاجها هو إفشاء، حتى داخليًا. إرسالها عبر تطبيق مراسلة شخصي أو عنوان بريد إلكتروني شخصي ينقلها خارج كل الضوابط التي تمتلكها المؤسسة، ولهذا السبب هذا هو أكثر أنواع الخروقات شيوعًا في العمل المكتبي العادي. القناة المريحة ليست دائمًا القناة الصحيحة.","mdEn":"Share information on a need-to-know basis, through approved channels only. Forwarding a customer's details to a colleague who does not need them is a disclosure, even internally. Sending them over a personal messaging app or a personal email address moves them outside every control the organisation has, which is why that is the single most common breach in ordinary office work. The convenient channel is not always the right one."}},{"id":"b_l1_def_ds_request","type":"definition_card","objectiveId":"PRV-01","payload":{"termAr":"طلب صاحب البيانات","termEn":"Data-subject request","defAr":"طلب من شخص لمعرفة البيانات التي تحتفظ بها المؤسسة عنه، أو لتصحيحها، أو لحذفها.","defEn":"A request from a person to know what data the organisation holds about them, to correct it, or to delete it.","icon":"📩","exampleAr":"مثال تدريبي: مريض يطلب نسخة من سجلاته الطبية.","exampleEn":"Training example: a patient asking for a copy of their medical records."}},{"id":"b_l1_def_breach","type":"definition_card","objectiveId":"PRV-01","payload":{"termAr":"خرق محتمل","termEn":"Potential breach","defAr":"أي موقف تصل فيه البيانات الشخصية إلى مكان لا ينبغي أن تكون فيه، مثل المستلم الخطأ أو الجهاز المفقود.","defEn":"Any situation where personal data has gone somewhere it should not have, such as the wrong recipient or a lost device.","icon":"⚠️","exampleAr":"مثال تدريبي: إرسال بريد إلكتروني يحتوي على تفاصيل مريض إلى زميل خارج الفريق.","exampleEn":"Training example: emailing a patient's details to a colleague outside the team."}},{"id":"b_l1_tip_breach","type":"job_tip","objectiveId":"PRV-01","payload":{"mdAr":"إذا وصلت البيانات الشخصية إلى مكان لا ينبغي أن تكون فيه، أبلغ عن ذلك في نفس اليوم إلى الشخص المسؤول. التزامات المؤسسة بالإبلاغ تقاس بالساعات والأيام، والساعة تبدأ عادةً عندما يعلم أي موظف، وليس عندما يعلم مسؤول الخصوصية.","mdEn":"If personal data has gone somewhere it should not have, report it the same day to the person responsible. The organisation's reporting obligations are measured in hours and days, and the clock usually starts when any employee becomes aware, not when the privacy officer does."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"PRV-01","payload":{"itemsAr":["البيانات الشخصية هي أي معلومة يمكن أن تحدد شخصًا، وليس فقط ما يحمل اسمًا.","البيانات الحساسة تتطلب حماية أعلى بسبب المخاطر المحتملة عند الكشف عنها.","ثلاثة عادات تغطي معظم ما يتوقع من الموظف القيام به: جمع واستخدام ما تحتاجه المهمة فقط، والمشاركة على أساس الحاجة إلى المعرفة عبر القنوات المعتمدة فقط، والاحتفاظ بالبيانات فقط طالما كانت هناك حاجة إليها ثم التخلص منها بشكل صحيح.","إذا طلب شخص ما معرفة البيانات التي تحتفظ بها عنه أو تصحيحها أو حذفها، فهذا طلب صاحب بيانات، ويجب إرساله إلى الشخص المسؤول في نفس اليوم.","إذا وصلت البيانات الشخصية إلى مكان لا ينبغي أن تكون فيه، فهذا خرق محتمل، ويجب الإبلاغ عنه في نفس اليوم."],"itemsEn":["Personal data is any information that could identify a person, not just what carries a name.","Sensitive data requires higher protection due to potential risks if disclosed.","Three habits cover most of what an employee is expected to do: collect and use only what the task needs, share on a need-to-know basis through approved channels only, and keep data only as long as needed then dispose of it properly.","If a person asks what data you hold about them, asks for it to be corrected, or asks for it to be deleted, that is a data-subject request, and it must be sent to the responsible person the same day.","If personal data has gone somewhere it should not have, that is a potential breach, and it must be reported the same day."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"PRV-01","payload":{"textAr":"طبّق ما قرأت","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_example","type":"worked_example","objectiveId":"PRV-01","payload":{"promptAr":"تجد ملفًا على محرك أقراص مشترك يحمل اسم «ملاحظات الاجتماع». عند فتحه، ترى ملاحظات مكتوبة بخط اليد تتضمن: «المريض في الغرفة 4، تشخيص أولي DX-A102، بدأ العلاج اليوم، سيحتاج إلى متابعة لمدة أسبوعين». هل هذه بيانات شخصية؟","promptEn":"You find a file on a shared drive named \"Meeting notes\". Opening it, you see handwritten notes that include: \"Patient in room 4, preliminary diagnosis DX-A102, started treatment today, will need follow-up for two weeks.\" Is this personal data?","steps":[{"showAr":"اسأل: هل يمكن لشخص ما معرفة من يتعلق الأمر؟","showEn":"Ask: could someone work out who this is about?","whyAr":"الغرفة 4 وحدها قد لا تكون كافية، لكن التشخيص والعلاج يضيقان النطاق. في جناح صغير، يمكن أن يحددا شخصًا.","whyEn":"Room 4 alone might not be enough, but the diagnosis and treatment narrow it down. In a small ward, they could identify someone."},{"showAr":"صنّف المعلومات: هذا سجل صحي.","showEn":"Classify the information: this is health information.","whyAr":"السجلات الصحية هي بيانات حساسة بغض النظر عن كيفية وصولها.","whyEn":"Health records are sensitive data regardless of how they arrived."},{"showAr":"قرر ما يجب فعله: احمِ الملف وأبلغ عن وجوده.","showEn":"Decide what to do: secure the file and report its presence.","whyAr":"المعلومات حساسة ويمكن التعرف عليها، لذا يجب تأمينها والإبلاغ عنها وفقًا لقواعد المؤسسة.","whyEn":"The information is sensitive and identifiable, so it must be secured and reported according to the organisation's rules."}],"answerAr":"نعم، هذه بيانات شخصية حساسة. يجب تأمين الملف والإبلاغ عن وجوده إلى الشخص المسؤول عن الخصوصية في نفس اليوم.","answerEn":"Yes, this is sensitive personal data. The file must be secured and its presence reported to the privacy responsible person the same day."}},{"id":"b_l2_scenario_share","type":"scenario","objectiveId":"PRV-01","payload":{"situationAr":"تلقيت بريدًا إلكترونيًا من زميل يطلب منك إرسال قائمة بأسماء جميع المرضى الذين لديهم موعد غدًا لمساعدته في التحضير. القائمة موجودة في جدول بيانات على محرك أقراص مشترك.","situationEn":"You receive an email from a colleague asking you to send a list of all patients who have appointments tomorrow to help them prepare. The list exists in a spreadsheet on a shared drive.","decisions":[{"id":"d1","optionAr":"أرسل القائمة عبر البريد الإلكتروني كما هي.","optionEn":"Send the list by email as-is.","consequenceAr":"البيانات الشخصية تصل إلى شخص لا يحتاجها بالضرورة، عبر قناة غير محمية. هذا إفشاء غير ضروري.","consequenceEn":"The personal data reaches someone who may not need it, through an unprotected channel. This is an unnecessary disclosure.","isBest":false},{"id":"d2","optionAr":"أرسل فقط الأسماء الأولى، دون أي تفاصيل أخرى.","optionEn":"Send only first names, with no other details.","consequenceAr":"الأسماء الأولى وحدها قد تكون كافية للتعرف على المرضى في سياق صغير، خاصة إذا كانت غير شائعة.","consequenceEn":"First names alone may be enough to identify patients in a small context, especially if uncommon.","isBest":false},{"id":"d3","optionAr":"اطلب توضيحًا: ما الذي يحتاجه الزميل بالضبط ولماذا؟","optionEn":"Ask for clarification: what exactly does the colleague need, and why?","consequenceAr":"قد يكتشف أن ما يحتاجه يمكن توفيره دون مشاركة البيانات الشخصية، أو أن هناك طريقة معتمدة لمشاركتها.","consequenceEn":"You may find that what they need can be provided without sharing personal data, or that there is an approved way to share it.","isBest":true},{"id":"d4","optionAr":"أرسل القائمة عبر القناة المعتمدة للمشاركة الداخلية.","optionEn":"Send the list through the approved internal sharing channel.","consequenceAr":"البيانات تصل إلى الشخص المناسب بالطريقة الصحيحة، لكن لا يزال هناك إفشاء غير ضروري إذا كان الزميل لا يحتاج القائمة الكاملة.","consequenceEn":"The data reaches the right person in the right way, but it is still an unnecessary disclosure if the colleague does not need the full list.","isBest":false}]}},{"id":"b_l2_scenario_retention","type":"scenario","objectiveId":"PRV-01","payload":{"situationAr":"تجد مجلدًا على جهاز كمبيوتر قديم يحتوي على نسخ من ملفات المرضى من عام 2020. لم يتم الوصول إلى المجلد منذ عامين، ولا يوجد سجل لاحتياج أي شخص لهذه الملفات.","situationEn":"You find a folder on an old computer containing copies of patient files from 2020. The folder has not been accessed in two years, and there is no record of anyone needing these files.","decisions":[{"id":"d1","optionAr":"اترك الملفات كما هي. إذا احتاجها أحد، فسيبحث عنها.","optionEn":"Leave the files as they are. If someone needs them, they will look for them.","consequenceAr":"البيانات الشخصية تبقى دون حماية، والمسؤولية عن أي خرق مستمرة.","consequenceEn":"The personal data remains unprotected, and liability for any breach continues.","isBest":false},{"id":"d2","optionAr":"احذف الملفات الآن.","optionEn":"Delete the files now.","consequenceAr":"الاحتفاظ لم يعد مبررًا، والحذف هو التصرف الصحيح، لكن يجب التأكد من عدم وجود سياسة احتفاظ تتطلب أرشفة أولًا.","consequenceEn":"Retention is no longer justified, and deletion is the right action, but you must check whether a retention policy requires archiving first.","isBest":false},{"id":"d3","optionAr":"أبلغ الشخص المسؤول عن الخصوصية في نفس اليوم.","optionEn":"Report the folder to the privacy responsible person the same day.","consequenceAr":"الخبراء يقررون ما إذا كان يجب أرشفة الملفات أو حذفها، ويضمنون التخلص منها بشكل صحيح.","consequenceEn":"The experts decide whether the files should be archived or deleted, and ensure proper disposal.","isBest":true},{"id":"d4","optionAr":"انقل الملفات إلى محرك أقراص مشترك حيث يمكن للآخرين الوصول إليها.","optionEn":"Move the files to a shared drive where others can access them.","consequenceAr":"هذا يزيد من عدد النسخ ويوسع نطاق الوصول دون سبب، مما يزيد من المخاطر.","consequenceEn":"This increases the number of copies and broadens access without cause, increasing risk.","isBest":false}]}},{"id":"b_l2_sort_identifiability","type":"sort_buckets","objectiveId":"PRV-01","payload":{"buckets":[{"id":"personal","labelAr":"بيانات شخصية","labelEn":"Personal data"},{"id":"not_personal","labelAr":"ليست بيانات شخصية","labelEn":"Not personal data"}],"cards":[{"id":"c1","textAr":"رقم هاتف المريض","textEn":"Patient's phone number","bucketId":"personal","whyAr":"يمكن ربط رقم الهاتف مباشرة بشخص.","whyEn":"A phone number can be directly linked to a person."},{"id":"c2","textAr":"عنوان البريد الإلكتروني للموظف","textEn":"Employee's email address","bucketId":"personal","whyAr":"يمكن ربط عنوان البريد الإلكتروني مباشرة بشخص.","whyEn":"An email address can be directly linked to a person."},{"id":"c3","textAr":"«المريض في الغرفة 3»","textEn":"\"Patient in room 3\"","bucketId":"not_personal","whyAr":"الغرفة وحدها لا تحدد شخصًا في جناح كبير، ولا توجد معلومات أخرى متاحة بشكل معقول.","whyEn":"The room alone does not identify a person in a large ward, and no other reasonably available information is present."},{"id":"c4","textAr":"«المريض الذي بدأ العلاج في 15 يناير»","textEn":"\"Patient who started treatment on January 15\"","bucketId":"personal","whyAr":"في جناح صغير، يمكن أن يحدد التاريخ شخصًا إذا كان متاحًا بشكل معقول.","whyEn":"In a small ward, the date could identify someone if it is reasonably available."},{"id":"c5","textAr":"مجموع المبيعات لشهر يناير","textEn":"Total sales for January","bucketId":"not_personal","whyAr":"الأرقام المجمعة لا تتعلق بشخص محدد.","whyEn":"Aggregate numbers do not relate to an identified person."},{"id":"c6","textAr":"«الموظف الجديد في قسم المحاسبة الذي بدأ في 1 مارس»","textEn":"\"The new employee in accounting who started on March 1\"","bucketId":"personal","whyAr":"في فريق صغير، يمكن أن تحدد المجموعة شخصًا إذا كانت متاحة بشكل معقول.","whyEn":"In a small team, the combination could identify someone if reasonably available."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"PRV-01","payload":{"itemRef":"PRV-01-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"PRV-01","payload":{"itemRef":"PRV-01-KC-02"}}]}},"items":[{"key":"PRV-01-KC-01","objectiveId":"PRV-01","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"أي من هذه المعلومات يُعتبر بيانات شخصية؟","stemEn":"Which of these is personal data?","rationaleAr":"الاختبار هو قابلية التعرف، وليس وجود اسم واضح. المعلومات الشخصية هي أي معلومة يمكن ربطها بشخص محدد، سواء بمفردها أو مع معلومات أخرى متاحة بشكل معقول.","rationaleEn":"The test is identifiability, not the presence of an obvious name. Personal data is any information that can be linked to a specific person, either alone or with other reasonably available information.","options":[{"textAr":"عنوان الشارع بدون رقم الشقة","textEn":"A street address without the apartment number","isCorrect":false,"feedbackAr":"المفهوم الخاطئ: العنوان بدون رقم الشقة قد يكون كافيًا للتعرف على الشخص في سياق محدد، مثل حي صغير أو إذا كان العنوان فريدًا.","feedbackEn":"Misconception: A street address without the apartment number may be sufficient to identify a person in a specific context, such as a small neighborhood or if the address is unique."},{"textAr":"رقم هاتف المريض","textEn":"A patient's phone number","isCorrect":true,"feedbackAr":"الصحيح: رقم الهاتف يمكن ربطه مباشرة بشخص محدد، مما يجعله بيانات شخصية بغض النظر عن السياق.","feedbackEn":"Correct: A phone number can be directly linked to a specific person, making it personal data regardless of context."},{"textAr":"«المريض في الغرفة 3»","textEn":"\"Patient in room 3\"","isCorrect":false,"feedbackAr":"المفهوم الخاطئ: الغرفة وحدها لا تحدد شخصًا في جناح كبير ما لم تكن هناك معلومات أخرى متاحة بشكل معقول.","feedbackEn":"Misconception: The room alone does not identify a person in a large ward unless other reasonably available information is present."},{"textAr":"مجموع المبيعات لشهر يناير","textEn":"Total sales for January","isCorrect":false,"feedbackAr":"المفهوم الخاطئ: الأرقام المجمعة لا تتعلق بشخص محدد.","feedbackEn":"Misconception: Aggregate numbers do not relate to an identified person."}]},{"key":"PRV-01-KC-02","objectiveId":"PRV-01","type":"MULTI_SELECT","bloom":"APPLY","formative":true,"stemAr":"أي من هذه المواقف يُعتبر خرقًا محتملًا يتطلب الإبلاغ عنه في نفس اليوم؟","stemEn":"Which of these situations is a potential breach requiring same-day reporting?","rationaleAr":"الخرق المحتمل هو أي وصول غير مصرح به للبيانات الشخصية إلى مكان لا ينبغي أن تكون فيه، بغض النظر عن النية أو الضرر.","rationaleEn":"A potential breach is any unauthorized access of personal data to a place it should not be, regardless of intent or harm.","options":[{"textAr":"إرسال بريد إلكتروني يحتوي على تفاصيل مريض إلى زميل خارج الفريق","textEn":"Emailing a patient's details to a colleague outside the team","isCorrect":true,"feedbackAr":"الصحيح: هذا إفشاء غير مصرح به للبيانات الشخصية إلى شخص لا يحتاجها، مما يجعله خرقًا محتملًا.","feedbackEn":"Correct: This is an unauthorized disclosure of personal data to someone who does not need it, making it a potential breach."},{"textAr":"طباعة قائمة بالمرضى وتركها على طابعة مشتركة","textEn":"Printing a patient list and leaving it on a shared printer","isCorrect":true,"feedbackAr":"الصحيح: البيانات الشخصية أصبحت متاحة لأشخاص لا يحتاجونها، مما يشكل خرقًا محتملًا.","feedbackEn":"Correct: Personal data is now available to people who do not need it, constituting a potential breach."},{"textAr":"نسخ جدول بيانات يحتوي على أسماء الموظفين إلى محرك أقراص شخصي","textEn":"Copying a spreadsheet with employee names to a personal drive","isCorrect":true,"feedbackAr":"الصحيح: البيانات الشخصية انتقلت إلى مكان خارج الضوابط المؤسسية، مما يشكل خرقًا محتملًا.","feedbackEn":"Correct: Personal data has moved to a place outside institutional controls, constituting a potential breach."},{"textAr":"حذف ملف يحتوي على معلومات مريض بعد انتهاء الحاجة إليه","textEn":"Deleting a file containing patient information after it is no longer needed","isCorrect":false,"feedbackAr":"المفهوم الخاطئ: الحذف الصحيح للبيانات الشخصية بعد انتهاء الحاجة إليها ليس خرقًا، بل هو ممارسة جيدة.","feedbackEn":"Misconception: Properly deleting personal data after it is no longer needed is not a breach, but good practice."}]}]},{"lesson":{"slug":"recognising-a-phishing-email","titleAr":"التعرّف على رسائل التصيّد الاحتيالي","titleEn":"Recognising a phishing email","estMinutes":30,"bilingual":true,"levels":["L1","L2"],"objectives":["SEC-01"],"conceptsIntroduced":["display_name","look_alike_domain","link_destination","engineered_urgency","reply_to_address","phishing_action"],"blocks":{"l1":[{"id":"b_l1_h_intro","type":"heading","objectiveId":"SEC-01","payload":{"textAr":"ما هو التصيّد الاحتيالي؟","textEn":"What phishing is","level":2}},{"id":"b_l1_text_intro","type":"rich_text","objectiveId":"SEC-01","payload":{"mdAr":"التصيّد الاحتيالي لا يستهدف البرامج، بل يستهدف الشخص الذي يقرأ الشاشة. ولهذا السبب، حتى النظام المحمي تمامًا قد يقع ضحية لمهاجم مدرب جيدًا. الدفاع ليس أداة، بل عادة تتمثل في التحقق من شيئين أو ثلاثة قبل اتخاذ أي إجراء.\n\nرسالة التصيّد الاحتيالي تبدو غالبًا كرسالة شرعية، لكنها مصممة لخداع المتلقي لاتخاذ إجراء ضار، مثل النقر على رابط أو فتح مرفق أو مشاركة معلومات حساسة.","mdEn":"Phishing does not attack software — it attacks the person reading the screen. That is why a fully patched system with a well-trained attacker can still lose. The defence is not a tool; it is a habit of checking two or three things before acting.\n\nA phishing email often looks like a legitimate message, but it is designed to trick the recipient into taking a harmful action, such as clicking a link, opening an attachment, or sharing sensitive information."}},{"id":"b_l1_def_display_name","type":"definition_card","objectiveId":"SEC-01","payload":{"termAr":"اسم العرض","termEn":"Display name","defAr":"النص الحر الذي يظهر بجانب عنوان البريد الإلكتروني للمرسل. يمكن لأي شخص تعيينه لأي شيء، ولهذا السبب لا يجب الوثوق به دون التحقق من العنوان الفعلي.","defEn":"The free text shown next to a sender's email address. Anyone can set it to anything, which is why it should never be trusted without checking the actual address behind it.","icon":"👤","exampleAr":"اسم العرض: \"دعم بنك الجزيرة\"، العنوان الفعلي: support@g00gle.com","exampleEn":"Display name: \"Al Jazeera Bank Support\", actual address: support@g00gle.com"}},{"id":"b_l1_def_look_alike_domain","type":"definition_card","objectiveId":"SEC-01","payload":{"termAr":"نطاق شبيه","termEn":"Look-alike domain","defAr":"نطاق مسجل ليشبه نطاقًا شرعيًا، بهدف خداع المتلقين عند قراءته بسرعة. قد يحتوي على أحرف متشابهة بصريًا، أو شرطات إضافية، أو نطاق أعلى مختلف.","defEn":"A registered domain chosen to resemble a legitimate one, intended to deceive recipients when read quickly. It may use visually similar characters, extra hyphens, or a different top-level domain.","icon":"🔍","exampleAr":"النطاق الشرعي: example.com، النطاق الشبيه: examp1e.com أو example-security.com","exampleEn":"Legitimate domain: example.com, look-alike: examp1e.com or example-security.com"}},{"id":"b_l1_def_link_destination","type":"definition_card","objectiveId":"SEC-01","payload":{"termAr":"وجهة الرابط","termEn":"Link destination","defAr":"العنوان الفعلي الذي سيذهب إليه المستخدم عند النقر على الرابط. النص الظاهر للرابط (نص الرابط) منفصل عن الوجهة ويمكن تعيينه لأي شيء.","defEn":"The actual address a user will go to when they click a link. The visible text of the link (anchor text) is separate from the destination and can be set to anything.","icon":"🔗","exampleAr":"نص الرابط: \"تحديث كلمة المرور\"، الوجهة الفعلية: https://phishing-site.com/password-reset","exampleEn":"Anchor text: \"Update your password\", actual destination: https://phishing-site.com/password-reset"}},{"id":"b_l1_def_engineered_urgency","type":"definition_card","objectiveId":"SEC-01","payload":{"termAr":"الإلحاح المصطنع","termEn":"Engineered urgency","defAr":"طلب يتضمّن مهلة زمنية قصيرة أو تهديدًا، مصممًا لإجبار المتلقي على اتخاذ إجراء دون تفكير أو تحقق. غالبًا ما يُستخدم مع طلبات غير معتادة لتجاوز الإجراءات المعتادة.","defEn":"A request that includes a short deadline or threat, designed to force the recipient to act without pausing to think or verify. Often used alongside unusual requests to bypass normal procedures.","icon":"⏳","exampleAr":"\"يجب تحديث حسابك خلال ساعتين وإلا سيتم إغلاقه نهائيًا.\"","exampleEn":"\"Your account must be updated within two hours or it will be permanently closed.\""}},{"id":"b_l1_compare_signals","type":"compare_table","objectiveId":"SEC-01","payload":{"captionAr":"الإشارات الحقيقية مقابل الإشارات المزيفة","captionEn":"Legitimate signals compared with phishing signals","columns":[{"labelAr":"الجانب","labelEn":"Aspect"},{"labelAr":"رسالة شرعية","labelEn":"Legitimate message"},{"labelAr":"رسالة تصيّد","labelEn":"Phishing message"}],"rows":[[{"textAr":"اسم العرض","textEn":"Display name"},{"textAr":"يتطابق مع العنوان الفعلي أو يكون اسمًا معروفًا للمرسل","textEn":"Matches the actual address or is a known name of the sender"},{"textAr":"يبدو شرعيًا لكنه لا يتطابق مع العنوان الفعلي","textEn":"Appears legitimate but does not match the actual address"}],[{"textAr":"عنوان المرسل","textEn":"Sender address"},{"textAr":"نطاق معروف ومتسق مع المنظمة","textEn":"Known domain consistent with the organisation"},{"textAr":"نطاق شبيه أو عنوان غير متوقع","textEn":"Look-alike domain or unexpected address"}],[{"textAr":"نص الرابط","textEn":"Link text"},{"textAr":"يتطابق مع الوجهة الفعلية","textEn":"Matches the actual destination"},{"textAr":"يبدو شرعيًا لكن الوجهة مختلفة","textEn":"Appears legitimate but destination is different"}],[{"textAr":"الإلحاح","textEn":"Urgency"},{"textAr":"مهلة زمنية معقولة وطلب معتاد","textEn":"Reasonable deadline and routine request"},{"textAr":"مهلة قصيرة وطلب غير معتاد","textEn":"Short deadline and unusual request"}],[{"textAr":"الطلبات","textEn":"Requests"},{"textAr":"لا يطلب كلمات مرور أو رموز لمرة واحدة","textEn":"Never asks for passwords or one-time codes"},{"textAr":"يطلب كلمات مرور أو رموز لمرة واحدة أو معلومات حساسة","textEn":"Asks for passwords, one-time codes, or sensitive information"}]]}},{"id":"b_l1_flow_checks","type":"process_flow","objectiveId":"SEC-01","payload":{"interactive":false,"steps":[{"id":"s1","labelAr":"اقرأ اسم العرض","labelEn":"Read the display name","detailAr":"لا تثق به دون التحقق من العنوان الفعلي.","detailEn":"Do not trust it without checking the actual address."},{"id":"s2","labelAr":"افحص العنوان الفعلي","labelEn":"Examine the actual address","detailAr":"هل النطاق معروف ومتسق مع المرسل؟","detailEn":"Is the domain known and consistent with the sender?"},{"id":"s3","labelAr":"تحقق من الروابط","labelEn":"Check links","detailAr":"أظهر الوجهة الفعلية لكل رابط قبل النقر.","detailEn":"Reveal the actual destination of every link before clicking."},{"id":"s4","labelAr":"تعرّف على الإلحاح المصطنع","labelEn":"Recognise engineered urgency","detailAr":"هل المهلة قصيرة وطلب غير معتاد؟","detailEn":"Is the deadline short and the request unusual?"},{"id":"s5","labelAr":"تجاهل الطلبات المحظورة","labelEn":"Ignore forbidden requests","detailAr":"كلمات المرور ورموز لمرة واحدة لا تُشارك أبدًا.","detailEn":"Passwords and one-time codes are never shared."},{"id":"s6","labelAr":"تحقق من عنوان الرد","labelEn":"Check the reply-to address","detailAr":"هل يختلف عن عنوان الإرسال؟","detailEn":"Does it differ from the sending address?"},{"id":"s7","labelAr":"توقف قبل فتح المرفقات","labelEn":"Pause before opening attachments","detailAr":"هل المرفق متوقع؟","detailEn":"Is the attachment expected?"},{"id":"s8","labelAr":"تحقق عبر قناة معروفة","labelEn":"Verify through a known channel","detailAr":"استخدم عنوانًا أو رقم هاتف لديك مسبقًا.","detailEn":"Use an address or phone number you already have."},{"id":"s9","labelAr":"بلّغ عن الرسالة","labelEn":"Report the message","detailAr":"نفس الرسالة نادرًا ما تصل لشخص واحد فقط.","detailEn":"The same message rarely arrives at only one person."}]}},{"id":"b_l1_tip_display_name","type":"job_tip","objectiveId":"SEC-01","payload":{"mdAr":"اسم العرض هو أول ما تراه، ولهذا السبب هو أول ما يتلاعب به المهاجمون. لا تفترض أبدًا أن الاسم يطابق العنوان — افتح الرسالة وانظر إلى العنوان الفعلي.","mdEn":"The display name is the first thing you see, which is why it is the first thing attackers manipulate. Never assume the name matches the address — open the message and look at the actual address."}},{"id":"b_l1_tip_urgency","type":"job_tip","objectiveId":"SEC-01","payload":{"mdAr":"الإلحاح المصطنع موجود لإزالة التوقف الذي قد تفكر فيه. إذا كانت الرسالة تقول \"الآن أو أبدًا\"، فهذا سبب لفعل العكس: توقف وتحقق.","mdEn":"Engineered urgency exists to remove the pause in which you might think. If a message says \"now or never\", that is a reason to do the opposite: pause and verify."}},{"id":"b_l1_takeaways","type":"takeaways","objectiveId":"SEC-01","payload":{"itemsAr":["اسم العرض ليس عنوانًا — يمكن تعيينه لأي شيء.","النطاقات الشبيهة تعتمد على القراءة السريعة، وليس الفحص.","نص الرابط ووجهته مستقلان — أظهر الوجهة قبل النقر.","الإلحاح المصطنع مصمم لإزالة التوقف.","كلمات المرور ورموز لمرة واحدة لا تُشارك أبدًا.","الإجراء الصحيح هو التحقق ثم الإبلاغ، وليس النقر أو الرد."],"itemsEn":["The display name is not the address — it can be set to anything.","Look-alike domains rely on scanning, not reading.","Link text and destination are independent — reveal the destination before clicking.","Engineered urgency is designed to remove the pause.","Passwords and one-time codes are never shared.","The correct action is verify then report, not click or reply."]}}],"l2":[{"id":"b_l2_h_practice","type":"heading","objectiveId":"SEC-01","payload":{"textAr":"طبّق ما قرأت","textEn":"Put it to work","level":2}},{"id":"b_l2_worked_display_name","type":"worked_example","objectiveId":"SEC-01","payload":{"promptAr":"تتلقى رسالة بريد إلكتروني من \"دعم تقنية المعلومات\" تطلب منك تحديث كلمة المرور الخاصة بك. اسم العرض هو \"دعم تقنية المعلومات\"، والعنوان الفعلي هو it-support@company-secure.com. ماذا تفعل؟","promptEn":"You receive an email from \"IT Support\" asking you to update your password. The display name is \"IT Support\", and the actual address is it-support@company-secure.com. What do you do?","steps":[{"showAr":"اقرأ اسم العرض، ثم افحص العنوان الفعلي.","showEn":"Read the display name, then examine the actual address.","whyAr":"اسم العرض يمكن تزويره بسهولة، لكن العنوان الفعلي لا يمكن تزويره بنفس السهولة.","whyEn":"The display name can be easily faked, but the actual address cannot be spoofed as easily."},{"showAr":"قارن النطاق مع النطاق المعروف لدعم تقنية المعلومات.","showEn":"Compare the domain with the known domain for IT support.","whyAr":"النطاق company-secure.com غير متوقع لدعم تقنية المعلومات، مما يجعل العنوان مشبوهًا.","whyEn":"The domain company-secure.com is unexpected for IT support, making the address suspicious."},{"showAr":"تحقق من وجود طلب غير معتاد.","showEn":"Check for an unusual request.","whyAr":"الدعم الشرعي لا يطلب كلمات مرور عبر البريد الإلكتروني.","whyEn":"Legitimate support never asks for passwords via email."},{"showAr":"لا ترد أو تنقر على أي روابط.","showEn":"Do not reply or click any links.","whyAr":"الرد أو النقر قد يؤكد للمهاجم أن العنوان نشط.","whyEn":"Replying or clicking may confirm to the attacker that the address is active."},{"showAr":"بلّغ عن الرسالة عبر القناة الرسمية.","showEn":"Report the message through the official channel.","whyAr":"الإبلاغ يضمن أن الفريق الأمني على علم بالرسالة.","whyEn":"Reporting ensures the security team is aware of the message."}],"answerAr":"لا ترد أو تنقر على أي روابط. بلّغ عن الرسالة كتصيّد احتيالي.","answerEn":"Do not reply or click any links. Report the message as phishing."}},{"id":"b_l2_scenario_urgency","type":"scenario","objectiveId":"SEC-01","payload":{"situationAr":"تتلقى رسالة بريد إلكتروني من \"المدير المالي\" تقول: \"أحتاج إلى تحويل 50,000 جنيه إلى حساب جديد فورًا. أنا في اجتماع ولا يمكنني الرد على الهاتف. أرسل لي تفاصيل الحساب الآن.\" عنوان المرسل هو cfo@company.com، وعنوان الرد هو finance-update@company-secure.net.","situationEn":"You receive an email from \"The CFO\" saying: \"I need 50,000 transferred to a new account immediately. I'm in a meeting and can't take calls. Send me the account details now.\" The sender address is cfo@company.com, and the reply-to address is finance-update@company-secure.net.","decisions":[{"id":"d1","optionAr":"أرسل تفاصيل الحساب كما طلب.","optionEn":"Send the account details as requested.","consequenceAr":"المال يُحوّل إلى حساب المهاجم، ولا يمكن استرداده.","consequenceEn":"The money is transferred to the attacker's account and cannot be recovered.","isBest":false},{"id":"d2","optionAr":"اتصل بالمدير المالي على رقم هاتفه المعروف للتحقق.","optionEn":"Call the CFO on their known phone number to verify.","consequenceAr":"تكتشف أن الرسالة مزيفة، وتبلّغ الفريق الأمني. لا يُفقد أي مال.","consequenceEn":"You discover the message is fake and report it to the security team. No money is lost.","isBest":true},{"id":"d3","optionAr":"رد على الرسالة لتأكيد الطلب.","optionEn":"Reply to the message to confirm the request.","consequenceAr":"ردك يذهب إلى المهاجم، الذي قد يستخدمه لإقناع آخرين بأن الرسالة شرعية.","consequenceEn":"Your reply goes to the attacker, who may use it to convince others the message is legitimate.","isBest":false}]}},{"id":"b_l2_sort_signals","type":"sort_buckets","objectiveId":"SEC-01","payload":{"buckets":[{"id":"legitimate","labelAr":"إشارة شرعية","labelEn":"Legitimate signal"},{"id":"phishing","labelAr":"إشارة تصيّد","labelEn":"Phishing signal"}],"cards":[{"id":"c1","textAr":"اسم العرض يطابق العنوان الفعلي","textEn":"Display name matches the actual address","bucketId":"legitimate","whyAr":"اسم العرض الشرعي يتطابق مع العنوان الفعلي أو يكون اسمًا معروفًا.","whyEn":"A legitimate display name matches the actual address or is a known name."},{"id":"c2","textAr":"النطاق معروف ومتسق مع المنظمة","textEn":"Domain is known and consistent with the organisation","bucketId":"legitimate","whyAr":"الرسائل الشرعية تأتي من نطاقات معروفة ومتسقة.","whyEn":"Legitimate messages come from known, consistent domains."},{"id":"c3","textAr":"نص الرابط يطابق الوجهة الفعلية","textEn":"Link text matches the actual destination","bucketId":"legitimate","whyAr":"في الرسائل الشرعية، نص الرابط يتطابق مع الوجهة.","whyEn":"In legitimate messages, the link text matches the destination."},{"id":"c4","textAr":"مهلة زمنية معقولة وطلب معتاد","textEn":"Reasonable deadline and routine request","bucketId":"legitimate","whyAr":"الرسائل الشرعية لا تستخدم إلحاحًا مصطنعًا.","whyEn":"Legitimate messages do not use engineered urgency."},{"id":"c5","textAr":"اسم العرض يبدو شرعيًا لكنه لا يتطابق مع العنوان الفعلي","textEn":"Display name appears legitimate but does not match the actual address","bucketId":"phishing","whyAr":"المهاجمون يستخدمون أسماء عرض تبدو شرعية لخداع المتلقين.","whyEn":"Attackers use display names that appear legitimate to deceive recipients."},{"id":"c6","textAr":"نطاق شبيه أو عنوان غير متوقع","textEn":"Look-alike domain or unexpected address","bucketId":"phishing","whyAr":"النطاقات الشبيهة مصممة لخداع المتلقين عند القراءة السريعة.","whyEn":"Look-alike domains are designed to deceive recipients when scanned quickly."},{"id":"c7","textAr":"نص الرابط يبدو شرعيًا لكن الوجهة مختلفة","textEn":"Link text appears legitimate but destination is different","bucketId":"phishing","whyAr":"المهاجمون يخفون الوجهات الحقيقية خلف نصوص روابط تبدو شرعية.","whyEn":"Attackers hide real destinations behind link text that appears legitimate."},{"id":"c8","textAr":"مهلة قصيرة وطلب غير معتاد","textEn":"Short deadline and unusual request","bucketId":"phishing","whyAr":"الإلحاح المصطنع مصمم لإجبار المتلقي على التصرف دون تفكير.","whyEn":"Engineered urgency is designed to force the recipient to act without thinking."}]}},{"id":"b_l2_check_1","type":"knowledge_check","objectiveId":"SEC-01","payload":{"itemRef":"SEC-01-KC-01"}},{"id":"b_l2_check_2","type":"knowledge_check","objectiveId":"SEC-01","payload":{"itemRef":"SEC-01-KC-02"}}]}},"items":[{"key":"SEC-01-KC-01","objectiveId":"SEC-01","type":"MCQ_SINGLE","bloom":"APPLY","formative":true,"stemAr":"تتلقى رسالة بريد إلكتروني من \"دعم الموارد البشرية\" تطلب منك تحديث معلومات حسابك. اسم العرض هو \"دعم الموارد البشرية\"، والعنوان الفعلي هو hr-support@company-services.net. ما هو أفضل إجراء؟","stemEn":"You receive an email from \"HR Support\" asking you to update your account information. The display name is \"HR Support\", and the actual address is hr-support@company-services.net. What is the best action?","rationaleAr":"العنوان الفعلي لا يتطابق مع النطاق المعروف للموارد البشرية، مما يجعل الرسالة مشبوهة. أفضل إجراء هو التحقق عبر قناة معروفة ثم الإبلاغ.","rationaleEn":"The actual address does not match the known domain for HR, making the message suspicious. The best action is to verify through a known channel and then report.","options":[{"textAr":"اتبع الرابط لتحديث معلومات حسابك.","textEn":"Follow the link to update your account information.","isCorrect":false,"feedbackAr":"هذا هو الإجراء الذي يريد المهاجم منك اتخاذه. النقر على الرابط قد يؤدي إلى موقع مزيف.","feedbackEn":"This is the action the attacker wants you to take. Clicking the link may lead to a fake site."},{"textAr":"تحقق من الرسالة عبر الاتصال بالموارد البشرية على رقم هاتف معروف.","textEn":"Verify the message by contacting HR on a known phone number.","isCorrect":true,"feedbackAr":"هذا هو الإجراء الصحيح. التحقق عبر قناة معروفة يمنع المهاجم من تأكيد أن العنوان نشط.","feedbackEn":"This is the correct action. Verifying through a known channel prevents the attacker from confirming the address is active."},{"textAr":"رد على الرسالة لتأكيد الطلب.","textEn":"Reply to the message to confirm the request.","isCorrect":false,"feedbackAr":"الرد قد يذهب إلى المهاجم، الذي قد يستخدمه لإقناع الآخرين بأن الرسالة شرعية.","feedbackEn":"The reply may go to the attacker, who could use it to convince others the message is legitimate."},{"textAr":"افتح الرسالة وتجاهلها.","textEn":"Open the message and ignore it.","isCorrect":false,"feedbackAr":"التجاهل لا يمنع المهاجم من إرسال رسائل أخرى أو استهداف آخرين.","feedbackEn":"Ignoring it does not prevent the attacker from sending more messages or targeting others."}]},{"key":"SEC-01-KC-02","objectiveId":"SEC-01","type":"MULTI_SELECT","bloom":"ANALYZE","formative":true,"stemAr":"أي من الإشارات التالية تدل على أن رسالة البريد الإلكتروني قد تكون محاولة تصيّد؟","stemEn":"Which of the following signals indicate that an email may be a phishing attempt?","rationaleAr":"الإشارات الصحيحة هي تلك التي تم تصميمها لخداع المتلقي أو تجاوز الإجراءات المعتادة.","rationaleEn":"The correct signals are those designed to deceive the recipient or bypass normal procedures.","options":[{"textAr":"اسم العرض يطابق العنوان الفعلي.","textEn":"The display name matches the actual address.","isCorrect":false,"feedbackAr":"هذا ليس إشارة تصيّد — الرسائل الشرعية غالبًا ما يكون فيها اسم العرض والعنوان متطابقين.","feedbackEn":"This is not a phishing signal — legitimate messages often have matching display names and addresses."},{"textAr":"النطاق معروف ومتسق مع المنظمة.","textEn":"The domain is known and consistent with the organisation.","isCorrect":false,"feedbackAr":"هذا ليس إشارة تصيّد — الرسائل الشرعية تأتي من نطاقات معروفة.","feedbackEn":"This is not a phishing signal — legitimate messages come from known domains."},{"textAr":"نص الرابط يبدو شرعيًا لكن الوجهة مختلفة.","textEn":"The link text appears legitimate but the destination is different.","isCorrect":true,"feedbackAr":"هذا هو أحد الإشارات الرئيسية للتصيّد. المهاجمون يخفون الوجهات الحقيقية خلف نصوص تبدو شرعية.","feedbackEn":"This is a key phishing signal. Attackers hide real destinations behind text that appears legitimate."},{"textAr":"الرسالة تطلب كلمة مرور أو رمز لمرة واحدة.","textEn":"The message asks for a password or one-time code.","isCorrect":true,"feedbackAr":"هذا طلب محظور — المنظمات الشرعية لا تطلب كلمات مرور أو رموز لمرة واحدة عبر البريد الإلكتروني.","feedbackEn":"This is a forbidden request — legitimate organisations never ask for passwords or one-time codes via email."},{"textAr":"عنوان الرد يختلف عن عنوان الإرسال.","textEn":"The reply-to address differs from the sending address.","isCorrect":true,"feedbackAr":"هذا إشارة قوية للتصيّد، خاصة إذا كانت الرسالة تطلب إجراءً غير معتاد.","feedbackEn":"This is a strong phishing signal, especially if the message asks for an unusual action."}]}]}]};
